function TablePickerPopover({
  label,
  onPick,
  onClose: _onClose,
}: {
  label: string;
  onPick: (rows: number, cols: number, header: boolean) => void;
  onClose: () => void;
}) {
  const [hoverRows, setHoverRows] = useState(2);
  const [hoverCols, setHoverCols] = useState(2);
  const [header, setHeader] = useState(true);
  const MAX_ROWS = 8;
  const MAX_COLS = 8;

  // Note: outer wrapper + role="dialog" + Escape handling is provided
  // by Radix Popover.Content above. We just render the inner picker
  // grid + options.
  return (
    <div className="pagedly-table-picker" role="group" aria-label={label}>
      <div className="pagedly-table-picker__grid" role="grid" aria-label={`${label}: ${hoverRows} × ${hoverCols}`}>
        {Array.from({ length: MAX_ROWS }).map((_, rIdx) => (
          <div key={rIdx} role="row" className="pagedly-table-picker__row">
            {Array.from({ length: MAX_COLS }).map((__, cIdx) => {
              const active = rIdx < hoverRows && cIdx < hoverCols;
              return (
                <button
                  key={cIdx}
                  type="button"
                  role="gridcell"
                  aria-label={`${rIdx + 1} × ${cIdx + 1}`}
                  className={`pagedly-table-picker__cell${active ? " pagedly-table-picker__cell--active" : ""}`}
                  onMouseEnter={() => {
                    setHoverRows(rIdx + 1);
                    setHoverCols(cIdx + 1);
                  }}
                  onFocus={() => {
                    setHoverRows(rIdx + 1);
                    setHoverCols(cIdx + 1);
                  }}
                  onMouseDown={(event) => event.preventDefault()}
                  onClick={() => onPick(rIdx + 1, cIdx + 1, header)}
                />
              );
            })}
          </div>
        ))}
      </div>
      <label className="pagedly-table-picker__option">
        <input
          type="checkbox"
          checked={header}
          onChange={(event) => setHeader(event.target.checked)}
        />
        Header row
      </label>
      <div className="pagedly-table-picker__readout" aria-live="polite">
        {hoverRows} × {hoverCols}
      </div>
    </div>
  );
}

