/**
 * ContentEditableEditor — React port of vue-document-editor.
 *
 * Direct DOM management — React renders only the root container.
 * Page divs are created/destroyed imperatively to avoid the
 * React-reconciliation vs imperative-mutation conflict.
 *
 * Reference: https://github.com/motla/vue-document-editor (MIT).
 */
import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  type CSSProperties,
} from "react";
import {
  forceMigrateOneWordBackwards,
  moveChildrenBackwardsWithMerging,
  moveChildrenForwardRecursively,
  undoForceMigrate,
} from "./pageTransitionMgmt";
import { stampFootnotes, hasFootnotes } from "./footnotes";
import { resolveCrossRefs } from "./toc";
import { sanitizeEditorHtml } from "../sanitize";

/**
 * Strip junk `<span>` elements that Chrome's native contentEditable
 * wraps around merged text after a Backspace at a block boundary.
 * These spans carry inherited inline styles (most commonly
 * `font-family: Inter, ...` re-asserting the editor's own font) that
 * Chrome adds to "preserve" formatting even when nothing actually
 * changed. They don't carry the `s_tag` watermark we use to recognise
 * split-block continuations, so they break the matching chain and the
 * tighten pass can't migrate chars across the page boundary.
 *
 * We unwrap spans with no attributes, or whose only attribute is
 * `style` and the style only sets inherited-text properties (font,
 * color, line-height). User-styled spans with substantive style (e.g.
 * background-color highlight) are left alone.
 */
// Style props Chrome bakes into spans during merges to "preserve"
// inherited formatting. We strip spans whose only style sets these
// (they're all redundantly re-asserting the editor's own inherited
// values). NOTE: font-size deliberately NOT here — user-selected
// font-size lands on a <span style="font-size: ...">, and we want
// to keep those. Chrome rarely uses font-size on its junk wraps.
const INHERITED_STYLE_PROPS = new Set([
  "font-family",
  "font-weight",
  "font-style",
  "font-variant",
  "color",
  "line-height",
  "letter-spacing",
  "text-align",
]);
function unwrapPlainSpans(root: HTMLElement, keepColorSpans = false): void {
  // In "rich" paste mode, a span whose ONLY style is `color` is an
  // intentional colored word from the paste — don't treat it as Chrome
  // junk to unwrap. (background-color/highlight already survives because
  // it isn't in INHERITED_STYLE_PROPS.)
  const unwrappable = keepColorSpans
    ? new Set([...INHERITED_STYLE_PROPS].filter((p) => p !== "color"))
    : INHERITED_STYLE_PROPS;
  const spans = root.querySelectorAll("span");
  for (const span of Array.from(spans)) {
    let shouldUnwrap = span.attributes.length === 0;
    if (
      !shouldUnwrap &&
      span.attributes.length === 1 &&
      span.hasAttribute("style")
    ) {
      const style = (span.getAttribute("style") ?? "")
        .split(";")
        .map((s) => s.trim().toLowerCase())
        .filter(Boolean);
      const props = style
        .map((s) => s.split(":")[0]?.trim())
        .filter((p): p is string => Boolean(p));
      shouldUnwrap =
        props.length > 0 && props.every((p) => unwrappable.has(p));
    }
    if (!shouldUnwrap) continue;
    const parent = span.parentNode;
    if (!parent) continue;
    while (span.firstChild) parent.insertBefore(span.firstChild, span);
    parent.removeChild(span);
  }
}

export interface ContentEditableEditorProps {
  html: string;
  onChange?: (html: string) => void;
  pageWidthMm?: number;
  pageHeightMm?: number;
  pagePadding?: string;
  doNotBreak?: (el: HTMLElement) => boolean;
  /**
   * Optional hook to sanitize HTML coming from clipboard paste before
   * it is inserted into the editor. If omitted, the built-in sanitizer
   * is used — it strips inline style/class/id attributes (which is
   * what causes Chrome's "select all, copy, paste makes text larger"
   * regression where the browser bakes computed font-size into the
   * pasted spans).
   */
  sanitizePastedHtml?: (html: string) => string;
  /**
   * How much formatting to keep from a paste when no custom
   * `sanitizePastedHtml` is supplied. `"clean"` (default) keeps structure
   * + bold/italic/lists/tables/links but strips colors, fonts, and
   * alignment so pasted content adopts the document's look. `"rich"` also
   * preserves text color, highlight/background color, and text alignment.
   * Word/Office cruft and unsafe tags are stripped in both modes.
   */
  pasteFormatting?: "clean" | "rich";
  /** Per-page top-margin chrome. `{page}`/`{total}` placeholders. */
  pageHeaderHtml?: { left?: string; right?: string };
  /** Per-page bottom-margin chrome (e.g. page numbers). */
  pageFooterHtml?: { left?: string; right?: string };
  /** Per-page diagonal watermark text (inert, behind content, print-safe). */
  watermark?: string;
  /**
   * Running head: stamp each page's top margin with the nearest heading of the
   * given level at-or-before that page (a STYLEREF-style chapter title). Inert,
   * stripped before reflow + serialize.
   */
  runningHead?: { level?: number };
  /** Suppress the header/footer on the first page (title-page convention). */
  differentFirstPage?: boolean;
  /**
   * Debounce (ms) for the `onChange` notification — a burst of edits
   * coalesces into one host notification this long after the last
   * keystroke. Keeps large documents responsive (serialize + host
   * re-parse is O(document)). `getHTML()` is unaffected (synchronous).
   * Defaults to 120ms.
   */
  changeDebounceMs?: number;
  /**
   * When true the document is not editable: the content root is rendered with
   * `contentEditable={false}` and the paste / drop / beforeinput entry points
   * bail, so typing, paste, drag-drop and find/replace can't mutate it.
   * Pagination, scrolling and selection still work.
   */
  readOnly?: boolean;
}

/**
 * Default paste sanitizer.
 *
 * 1. Strip every `style`, `class`, `id`, and `data-*` attribute. Kills
 *    Chrome's "copy-then-paste makes everything bigger" regression
 *    (Chrome bakes computed font-size/font-family into the pasted
 *    spans). Also kills internal `data-section-id` / `data-section-
 *    anchor` attributes the letter editor uses, which we never want
 *    pasted back into content.
 * 2. Remove `<template>`, `<script>`, `<style>`, `<meta>`, and
 *    `<link>` elements outright.
 * 3. Unwrap headings that contain block children — `<h2><p>...</p>
 *    </h2>` is invalid HTML and causes the inner block to inherit
 *    bold from the heading, which is the visible "everything is
 *    bold after paste" symptom.
 * 4. Unwrap attribute-less `<span>`s left behind.
 *
 * Tags are preserved otherwise (paragraphs, headings, lists, links).
 * Style preservation is intentionally lossy: hosts that want the
 * source's exact look can pass a custom `sanitizePastedHtml` prop.
 */
// Inline-style declarations we allow through in "rich" paste mode. Visual
// formatting users actually want from a copy (color, highlight, alignment)
// — NOT layout/spacing cruft (margins, line-height, font-family, etc.).
const RICH_STYLE_PROPS = new Set([
  "color",
  "background-color",
  "background",
  "text-align",
  // text-decoration keeps style-based underline / line-through (e.g. a
  // tracked-change insertion). Safe to keep — unlike font-weight it can't
  // silently cancel a semantic tag the way `font-weight:normal` on a <b>
  // wrapper does.
  "text-decoration",
  "text-decoration-line",
]);

function filterInlineStyle(style: string): string {
  return style
    .split(";")
    .map((d) => d.trim())
    .filter(Boolean)
    .filter((decl) => {
      const prop = decl.split(":")[0]?.trim().toLowerCase();
      return prop && RICH_STYLE_PROPS.has(prop);
    })
    .join("; ");
}

function defaultSanitizePastedHtml(
  html: string,
  opts: { keepInlineStyles?: boolean } = {},
): string {
  const keepStyles = opts.keepInlineStyles === true;
  // 1. Strip HTML comments (including Word's
  //    <!--StartFragment--> / <!--EndFragment--> and conditional
  //    blocks like <!--[if gte mso 9]>...<![endif]-->) before
  //    parsing — comments at the top level survive innerHTML
  //    assignment and reappear in the output otherwise.
  html = html.replace(/<!--[\s\S]*?-->/g, "");

  // SECURITY pass FIRST (review Batch 1, issue 2): strip on* handlers,
  // javascript:/vbscript: URLs, and <script>/<style>/<svg>/<math>/<iframe>/
  // <object>/<embed>/<form>. The cosmetic cleanup below handles paste *tidiness*
  // (Office cruft, bold-unwrap, class/data-* strip), NOT safety — without this,
  // a pasted `<img src=x onerror=…>` executes via execCommand("insertHTML").
  html = sanitizeEditorHtml(html);

  const tmp = document.createElement("div");
  tmp.innerHTML = html;

  // 2. Drop dangerous / structural tags entirely.
  const toRemove = tmp.querySelectorAll(
    "template, script, style, meta, link, head, title",
  );
  for (const el of Array.from(toRemove)) el.remove();

  // 3. Strip Office / Word namespaced tags (`<o:p>`, `<w:*>`,
  //    `<v:*>`, `<m:*>`) and any other element whose tag name
  //    contains a colon (an XML-namespace marker that's never
  //    valid HTML).
  for (const el of Array.from(tmp.querySelectorAll<HTMLElement>("*"))) {
    if (el.tagName.includes(":")) {
      el.remove();
    }
  }

  // 4. Strip style/class/id, every data-*, plus a few attributes
  //    pasted content brings along that we never want
  //    (lang/dir/align/face/color/size/bgcolor — visual cruft).
  // In "clean" mode we drop alignment/color attrs too; in "rich" mode we
  // keep `align` (and filtered inline color/alignment styles, below).
  const STRIP_ATTRS = new Set(
    keepStyles
      ? ["lang", "dir", "face", "size", "valign", "border", "cellpadding", "cellspacing"]
      : ["lang", "dir", "align", "face", "color", "size", "bgcolor",
         "valign", "border", "cellpadding", "cellspacing"],
  );
  for (const el of Array.from(tmp.querySelectorAll<HTMLElement>("*"))) {
    if (keepStyles) {
      // Keep only the safe visual subset of inline style; drop the rest.
      const filtered = filterInlineStyle(el.getAttribute("style") ?? "");
      if (filtered) el.setAttribute("style", filtered);
      else el.removeAttribute("style");
    } else {
      el.removeAttribute("style");
    }
    el.removeAttribute("class");
    el.removeAttribute("id");
    for (const attr of Array.from(el.attributes)) {
      if (attr.name.startsWith("data-")) el.removeAttribute(attr.name);
      else if (STRIP_ATTRS.has(attr.name.toLowerCase())) {
        el.removeAttribute(attr.name);
      }
    }
  }

  // 5. Google Docs wraps the entire clipboard payload in a single
  //    <b style="font-weight:normal" id="docs-internal-guid-*">.
  //    After (4) strips the style, the <b> becomes a real bold
  //    wrapper around everything — turning every paste into bold.
  //    Unwrap any <b> that contains a block-level child.
  const BLOCK_RE = /^(p|div|ul|ol|li|blockquote|pre|table|tr|td|th|h[1-6])$/i;
  for (const b of Array.from(tmp.querySelectorAll("b, strong"))) {
    const hasBlockChild = Array.from(b.children).some((c) =>
      BLOCK_RE.test(c.tagName),
    );
    if (hasBlockChild) {
      const parent = b.parentNode;
      if (!parent) continue;
      while (b.firstChild) parent.insertBefore(b.firstChild, b);
      parent.removeChild(b);
    }
  }

  // 6. Unwrap headings that contain block-level children. The letter
  //    editor emits `<h2 data-section-id="opening"><p>Dear Alex,</p>...
  //    </h2>` for section anchoring — when re-pasted, the inner
  //    `<p>` inherits the h2's bold from CSS inheritance. Strip the
  //    anchor wrapper but keep its content.
  const headings = tmp.querySelectorAll("h1, h2, h3, h4, h5, h6");
  for (const h of Array.from(headings)) {
    const hasBlockChild = Array.from(h.children).some((c) =>
      BLOCK_RE.test(c.tagName),
    );
    if (hasBlockChild) {
      const parent = h.parentNode;
      if (!parent) continue;
      while (h.firstChild) parent.insertBefore(h.firstChild, h);
      parent.removeChild(h);
    }
  }

  // 7. Unwrap attribute-less spans that remained — once styles and
  //    lang/dir are stripped, most pasted spans are empty shells.
  for (const span of Array.from(tmp.querySelectorAll("span"))) {
    if (span.attributes.length === 0) {
      const parent = span.parentNode;
      if (!parent) continue;
      while (span.firstChild) parent.insertBefore(span.firstChild, span);
      parent.removeChild(span);
    }
  }

  return tmp.innerHTML;
}

export interface ContentEditableEditorHandle {
  getHTML(): string;
  setHTML(html: string): void;
  /**
   * This instance's `.pagedly-ce-content` element (or null pre-mount). Lets the
   * wrapper scope DOM work to THIS editor instead of a document-global
   * `querySelector(".pagedly-ce-content")`, which would grab the wrong editor
   * when two are mounted on one page.
   */
  getContentEl(): HTMLElement | null;
  focus(): void;
  /**
   * Run a contentEditable formatting command (bold, italic, etc.) via
   * the browser's `document.execCommand`. Yes, it's deprecated. Yes,
   * it's the path of least resistance for a contentEditable editor —
   * and the only thing that works without a full PM-style command
   * pipeline. Returns true if the browser executed the command.
   */
  execCommand(command: string, value?: string): boolean;
  /** Re-run pagination from scratch (e.g. after external HTML edits). */
  reflow(): void;
  /** Undo the last edit via the engine's own snapshot stack. */
  undo(): void;
  /** Redo the last undone edit. */
  redo(): void;
  /** Whether an undo is available (snapshot stack has a prior state). */
  canUndo(): boolean;
  /** Whether a redo is available (redo stack is non-empty). */
  canRedo(): boolean;
  /** List the document's top-level blocks with stable in-session ids. */
  getBlocks(): { pid: string; tag: string; text: string }[];
  /** Replace the inner HTML of a block addressed by its pid. Returns success. */
  replaceBlock(pid: string, html: string): boolean;
}

const BLOCK_TAGS = new Set([
  "P", "H1", "H2", "H3", "H4", "H5", "H6",
  "BLOCKQUOTE", "LI", "PRE", "DIV", "FIGURE",
]);

// ── Selection serialization for undo / redo ───────────────────────
// We snapshot content as innerHTML strings, which means node identity
// is lost on restore. To put the caret back we record a path of child
// indices from the content root down to the boundary container, plus
// the offset. On restore we walk the same path in the rebuilt DOM.
type SelectionPoint = { path: number[]; offset: number };
type SerializedSelection = { anchor: SelectionPoint; focus: SelectionPoint };

function pathFromRoot(root: Node, node: Node): number[] | null {
  const path: number[] = [];
  let n: Node | null = node;
  while (n && n !== root) {
    const parent: Node | null = n.parentNode;
    if (!parent) return null;
    path.unshift(Array.prototype.indexOf.call(parent.childNodes, n));
    n = parent;
  }
  return n === root ? path : null;
}

function nodeFromPath(root: Node, path: number[]): Node | null {
  let n: Node = root;
  for (const idx of path) {
    const child = n.childNodes[idx];
    if (!child) return null;
    n = child;
  }
  return n;
}

function serializeSelection(root: Element): SerializedSelection | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  if (!sel.anchorNode || !sel.focusNode) return null;
  if (!root.contains(sel.anchorNode) || !root.contains(sel.focusNode)) {
    return null;
  }
  const anchorPath = pathFromRoot(root, sel.anchorNode);
  const focusPath = pathFromRoot(root, sel.focusNode);
  if (!anchorPath || !focusPath) return null;
  return {
    anchor: { path: anchorPath, offset: sel.anchorOffset },
    focus: { path: focusPath, offset: sel.focusOffset },
  };
}

function restoreSelectionFrom(
  root: Element,
  serialized: SerializedSelection | null,
): void {
  if (!serialized) return;
  const anchorNode = nodeFromPath(root, serialized.anchor.path);
  const focusNode = nodeFromPath(root, serialized.focus.path);
  if (!anchorNode || !focusNode) return;
  const sel = window.getSelection();
  if (!sel) return;
  try {
    const range = document.createRange();
    const clamp = (node: Node, off: number) =>
      node.nodeType === Node.TEXT_NODE
        ? Math.min(off, (node.textContent ?? "").length)
        : Math.min(off, node.childNodes.length);
    range.setStart(anchorNode, clamp(anchorNode, serialized.anchor.offset));
    range.setEnd(focusNode, clamp(focusNode, serialized.focus.offset));
    sel.removeAllRanges();
    sel.addRange(range);
  } catch {
    /* path resolved to an invalid boundary — leave selection as is */
  }
}

// Walk up from a node to the nearest block-level element that is a
// descendant of the editor content root. Returns null if none.
function findBlockAncestor(
  node: Node | null,
  root: Element,
): HTMLElement | null {
  let n: Node | null = node;
  while (n && n !== root) {
    if (n.nodeType === Node.ELEMENT_NODE && BLOCK_TAGS.has((n as Element).tagName)) {
      return n as HTMLElement;
    }
    n = n.parentNode;
  }
  return null;
}

// True iff the collapsed caret sits at the start of `block` — meaning
// there's no VISIBLE TEXT between the block's start and the caret. We
// measure text (not boundary points) so a leading <br>/whitespace
// placeholder still counts as "at start", and an element-level caret
// (e.g. <p>@1 after typing) is judged by what text precedes it rather
// than by its container, which is what makes this robust.
function isAtStartOfBlock(range: Range, block: Element): boolean {
  if (!range.collapsed) return false;
  try {
    const probe = document.createRange();
    probe.selectNodeContents(block);
    probe.setEnd(range.startContainer, range.startOffset);
    return probe.toString().length === 0;
  } catch {
    return false;
  }
}

// True iff the collapsed caret sits at the end of `block` — no visible
// text between the caret and the block end (trailing <br>/whitespace
// tolerated).
function isAtEndOfBlock(range: Range, block: Element): boolean {
  if (!range.collapsed) return false;
  try {
    const probe = document.createRange();
    probe.selectNodeContents(block);
    probe.setStart(range.startContainer, range.startOffset);
    return probe.toString().length === 0;
  } catch {
    return false;
  }
}

// Place a collapsed caret at character `offset` within `block`,
// walking its text nodes. Used to restore the caret AFTER a merge +
// reflow: setting a live Range before dispatching the input event is
// fragile because content.normalize() coalesces text nodes and
// fitContentOverPages resets the selection — both invalidate an
// element-offset Range. A character offset re-resolved against the
// post-reflow DOM is stable.
function placeCaretAtTextOffset(block: Element, offset: number): void {
  const apply = () => {
    const sel = window.getSelection();
    if (!sel) return;
    const walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT);
    let remaining = offset;
    let node = walker.nextNode() as Text | null;
    let target: Text | null = null;
    let targetOffset = 0;
    while (node) {
      const len = node.textContent?.length ?? 0;
      if (remaining <= len) {
        target = node;
        targetOffset = remaining;
        break;
      }
      remaining -= len;
      node = walker.nextNode() as Text | null;
    }
    const range = document.createRange();
    if (target) {
      range.setStart(target, targetOffset);
    } else {
      // No text node (e.g. empty block) — collapse to the block start.
      range.setStart(block, 0);
    }
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
  };
  // Apply now, then re-apply after the current frame. A structural
  // merge fires an input event whose downstream work (host onChange →
  // React re-render, deferred reflow) can emit a follow-up
  // selectionchange that yanks the caret to the block end. Re-applying
  // in rAF makes our placement the last writer.
  apply();
  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(apply);
  }
}

// Remove a single trailing <br> placeholder from a block. Browsers
// keep an empty block alive with a bogus <br> (e.g. pressing Enter
// yields <p><br></p>); when merging such a block into a neighbour we
// must drop that <br> or the merged result gets a stray line break
// that pushes the caret onto a new visual line.
function stripTrailingBr(block: Element): void {
  const last = block.lastChild;
  if (last && last.nodeName === "BR") block.removeChild(last);
}

// True if a block has no meaningful content — empty, whitespace, or
// just a placeholder <br>.
function isEffectivelyEmptyBlock(block: Element): boolean {
  const text = (block.textContent ?? "").trim();
  if (text.length > 0) return false;
  // No text. Empty unless it holds a non-br element (e.g. an <img>).
  for (const child of Array.from(block.childNodes)) {
    if (child.nodeType === Node.ELEMENT_NODE && child.nodeName !== "BR") {
      return false;
    }
  }
  return true;
}

// Walk forward from a block to the nearest next sibling that is also
// a block-level element. Mirror of previousBlockSibling.
function nextBlockSibling(block: Element): HTMLElement | null {
  let sib: Node | null = block.nextSibling;
  while (sib) {
    if (sib.nodeType === Node.ELEMENT_NODE) {
      const el = sib as Element;
      if (el.tagName === "TEMPLATE" || isPageChrome(el)) {
        sib = sib.nextSibling;
        continue;
      }
      if (BLOCK_TAGS.has(el.tagName)) {
        return el as HTMLElement;
      }
      return null;
    }
    if (
      sib.nodeType === Node.TEXT_NODE &&
      (sib.textContent ?? "").trim().length === 0
    ) {
      sib = sib.nextSibling;
      continue;
    }
    return null;
  }
  return null;
}

// Per-page header/footer chrome — inert, not a merge target.
function isPageChrome(el: Element): boolean {
  return (
    el.classList?.contains("pagedly-ce-header") ||
    el.classList?.contains("pagedly-ce-footer")
  );
}

// A manual page break (toolbar insertPageBreak inserts an empty
// <div class="pagedly-page-break">) is an atomic decoration, NOT a
// merge target. Backspace/Delete next to it removes the break.
function isPageBreak(el: Element): boolean {
  return el.classList?.contains("pagedly-page-break") ?? false;
}

// ── On-screen forced breaks ────────────────────────────────────────
// A page/section-break sentinel forces the content AFTER it onto a new sheet;
// a .pagedly-break-before block forces ITSELF onto a new sheet. These let the
// live paginated view break early (not only in print). Integrated into the fit
// loop's per-page step so incremental + full reflow apply them identically (the
// invariant compares the same resulting distribution).
function isBreakSentinel(el: Element): boolean {
  return (
    el.classList?.contains("pagedly-page-break") ||
    el.classList?.contains("pagedly-section-break")
  );
}
function isBreakBefore(el: Element): boolean {
  return el.classList?.contains("pagedly-break-before") ?? false;
}
function isKeepWithNext(el: Element): boolean {
  return el.classList?.contains("pagedly-keep-with-next") ?? false;
}
// Content (non-chrome) element children of a page. During reflow chrome is
// already stripped, so this is just the real blocks.
function pageContentEls(page: Element): Element[] {
  return Array.from(page.children).filter(
    (c) => c.tagName !== "TEMPLATE" && !isPageChrome(c),
  );
}
// The first node to peel onto a fresh page to honor a forced break inside this
// page, or null if none. (break-before → that element; sentinel → the node
// after it.)
function forcedBreakPeelStart(page: Element): Node | null {
  const kids = pageContentEls(page);
  for (let i = 0; i < kids.length; i++) {
    if (isBreakBefore(kids[i]) && i > 0) return kids[i];
    if (isBreakSentinel(kids[i]) && i < kids.length - 1) return kids[i].nextSibling;
  }
  return null;
}
// Is there a forced boundary between `page` and `nextPage` that the backward
// pull must not cross (page ends with a sentinel, or next starts break-before)?
function forcedBoundaryBetween(page: Element, nextPage: Element): boolean {
  const pk = pageContentEls(page);
  const nk = pageContentEls(nextPage);
  const last = pk[pk.length - 1];
  const first = nk[0];
  return (
    (!!last && isBreakSentinel(last)) ||
    (!!first && isBreakBefore(first)) ||
    // A keep-with-next block at the top of the next page is there to stay with
    // what follows — never pull it back up. This holds even when it's ALONE on
    // the page (nk.length === 1): the old `nk.length > 1` restriction let the
    // backward pull yank a lone KWN up to the previous page, where the
    // keep-with-next peel-down then pushed it back down — a period-2 oscillation
    // that made fitContentOverPages non-idempotent (an incremental==full hazard)
    // whenever the KWN block's successor was unsplittable (image / table row /
    // keep-together). Blocking the pull can only prevent compaction, never
    // strand the block further from its successor or explode page count.
    (!!first && isKeepWithNext(first))
  );
}

// Walk back from a block to the nearest previous sibling that is
// also a block-level element. Skip <template> anchors and any inert
// whitespace text nodes — those are layout/section metadata, not
// merge targets.
function previousBlockSibling(block: Element): HTMLElement | null {
  let sib: Node | null = block.previousSibling;
  while (sib) {
    if (sib.nodeType === Node.ELEMENT_NODE) {
      const el = sib as Element;
      if (el.tagName === "TEMPLATE" || isPageChrome(el)) {
        sib = sib.previousSibling;
        continue;
      }
      if (BLOCK_TAGS.has(el.tagName)) {
        return el as HTMLElement;
      }
      return null;
    }
    if (
      sib.nodeType === Node.TEXT_NODE &&
      (sib.textContent ?? "").trim().length === 0
    ) {
      sib = sib.previousSibling;
      continue;
    }
    return null;
  }
  return null;
}

function mmToPx(mm: number): number {
  return Math.round((mm / 25.4) * 96);
}

export const ContentEditableEditor = forwardRef<
  ContentEditableEditorHandle,
  ContentEditableEditorProps
>(function ContentEditableEditor(
  {
    html,
    onChange,
    pageWidthMm = 210,
    pageHeightMm = 297,
    pagePadding = "20mm",
    doNotBreak,
    sanitizePastedHtml,
    pasteFormatting,
    pageHeaderHtml,
    pageFooterHtml,
    watermark,
    runningHead,
    differentFirstPage,
    changeDebounceMs,
    readOnly = false,
  },
  ref,
) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);
  const pagesHeightRef = useRef<number>(0);
  // Skips the geometry-change effect on its first (mount) run — the mount layout
  // effect already measured the baseline; we only want to RE-measure on a live
  // page-size / orientation change.
  const geomInitRef = useRef(false);
  const paraIdCounterRef = useRef(1);
  const fitInProgressRef = useRef(false);
  // Deferred downstream reflow: an incremental pass only reflows a bounded
  // WINDOW of pages around the edit so per-keystroke cost stays O(window)
  // however long the document is. If the cascade hasn't settled by the end
  // of the window, the frontier page index is parked here and the rest is
  // settled in idle time (settleIdleRef holds the pending callback handle).
  const deferredReflowFromRef = useRef<number | null>(null);
  const settleIdleRef = useRef<number | null>(null);
  // When the parked frontier came from a FULL pass (initial load / setHTML /
  // reflow of a big doc) rather than an edit cascade, the idle drain must run
  // all the way to the last page — an edit cascade can stop early once a page
  // stops changing, but a full-pass backlog has no such natural end, so we
  // drive it to completion. See the `drainToEnd` arg of fitContentOverPages.
  const deferredDrainToEndRef = useRef(false);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  // onChange is debounced: serializing the whole document and letting the
  // host re-parse it is O(document), so firing it on every keystroke is
  // what makes large docs feel sluggish even when reflow is cheap. We
  // coalesce a burst of edits into one notification. getHTML() stays
  // synchronous (reads the DOM directly), so save/flush paths are exact.
  const emitChangeTimerRef = useRef<number | null>(null);
  const changeDebounceRef = useRef(changeDebounceMs);
  changeDebounceRef.current = changeDebounceMs;
  // Read by the once-bound event handlers (paste/drop/beforeinput) to bail when
  // read-only. contentEditable={!readOnly} blocks native typing/paste already;
  // this also stops the custom paste-chunker and drop-image paths.
  const readOnlyRef = useRef(readOnly);
  readOnlyRef.current = readOnly;
  const doNotBreakRef = useRef(doNotBreak);
  doNotBreakRef.current = doNotBreak;
  const sanitizePasteRef = useRef(sanitizePastedHtml);
  sanitizePasteRef.current = sanitizePastedHtml;
  const pasteFormattingRef = useRef(pasteFormatting);
  pasteFormattingRef.current = pasteFormatting;
  // True while a large paste is being inserted in chunks across animation
  // frames (see insertHtmlPaste). onInput skips the per-chunk host-notify and
  // undo snapshot while this is set, so a chunked paste collapses into ONE
  // emit + ONE undo step at the end instead of one per chunk.
  const pasteInProgressRef = useRef(false);
  const pageHeaderRef = useRef(pageHeaderHtml);
  pageHeaderRef.current = pageHeaderHtml;
  const pageFooterRef = useRef(pageFooterHtml);
  pageFooterRef.current = pageFooterHtml;
  const watermarkRef = useRef(watermark);
  watermarkRef.current = watermark;
  const runningHeadRef = useRef(runningHead);
  runningHeadRef.current = runningHead;
  const differentFirstPageRef = useRef(differentFirstPage);
  differentFirstPageRef.current = differentFirstPage;

  // ── Undo / redo ────────────────────────────────────────────────
  // Native contentEditable undo only knows about input it processed;
  // our structural mutations (block merges, table insert, image
  // resize, sanitised paste) bypass it. We run our own snapshot
  // stack instead: capture { html, selection } after every change
  // (debounced so a burst of typing coalesces into one step), and
  // intercept Cmd/Ctrl+Z / +Shift+Z to restore.
  type UndoSnapshot = { html: string; selection: SerializedSelection | null };
  const undoStackRef = useRef<UndoSnapshot[]>([]);
  const redoStackRef = useRef<UndoSnapshot[]>([]);
  const undoTimerRef = useRef<number | null>(null);
  const isRestoringRef = useRef(false);
  // Set synchronously when an edit is made but the snapshot is still in the
  // 350ms debounce window. canUndo() honors it so the toolbar's Undo button
  // enables on the first keystroke instead of lagging behind the commit.
  const pendingEditRef = useRef(false);
  const UNDO_LIMIT = 200;

  const pageWidthPx = mmToPx(pageWidthMm);
  const pageHeightPx = mmToPx(pageHeightMm);
  const PAGE_GAP_PX = 24;

  const applyPageStyle = (pageEl: HTMLDivElement) => {
    pageEl.style.width = `${pageWidthPx}px`;
    // min-height (not height) so the box grows when content overflows —
    // that's how we detect overflow via clientHeight. overflow: hidden
    // clips painting but doesn't constrain the box.
    pageEl.style.minHeight = `${pageHeightPx}px`;
    pageEl.style.height = "auto";
    pageEl.style.padding = pagePadding;
    pageEl.style.boxSizing = "border-box";
    pageEl.style.background = "var(--pagedly-page-background, white)";
    pageEl.style.boxShadow =
      "var(--pagedly-page-box-shadow, 0 0 0 1px rgba(60,64,67,0.08), 0 1px 3px 1px rgba(60,64,67,0.15))";
    pageEl.style.borderRadius = "var(--pagedly-page-border-radius, 3px)";
    pageEl.style.overflow = "hidden";
    pageEl.style.overflowAnchor = "none";
    pageEl.style.margin = `0 auto ${PAGE_GAP_PX}px`;
    pageEl.style.position = "relative";
    pageEl.classList.add("pagedly-ce-page");
  };

  const refreshPageStyles = () => {
    const content = contentRef.current;
    if (!content) return;
    const allPages = Array.from(
      content.querySelectorAll<HTMLDivElement>(".pagedly-ce-page"),
    );
    allPages.forEach((p) => applyPageStyle(p));
  };

  // The fit loop's targetHeight is the content-box height of an EMPTY page. A
  // visible empty page is exactly `pageHeightPx` tall (min-height, border-box,
  // no border), so a measured value far below that means a degenerate mount —
  // a display:none parent or a detached node yields clientHeight 0. Falling back
  // to the geometric page height keeps targetHeight sane; without this guard a
  // hidden mount stores targetHeight ≈ 1 and the fit loop bin-packs one block
  // per page, grinding toward MAX_PAGES and never settling.
  const measureBaselineHeight = (emptyPage: HTMLElement): number => {
    const measured = emptyPage.clientHeight;
    return (measured >= pageHeightPx * 0.5 ? measured : pageHeightPx) + 1;
  };

  const getPages = (): HTMLDivElement[] => {
    const content = contentRef.current;
    if (!content) return [];
    return Array.from(content.querySelectorAll<HTMLDivElement>(".pagedly-ce-page"));
  };

  // Index of the page the caret currently sits in, or undefined if it
  // can't be resolved (→ caller falls back to a full reflow). Used to
  // drive incremental reflow from the edited page only.
  const pageIndexOfSelection = (): number | undefined => {
    const content = contentRef.current;
    const sel = window.getSelection();
    if (!content || !sel || sel.rangeCount === 0) return undefined;
    let node: Node | null = sel.getRangeAt(0).startContainer;
    while (node && node !== content) {
      if (
        node.nodeType === Node.ELEMENT_NODE &&
        (node as Element).classList?.contains("pagedly-ce-page")
      ) {
        const idx = getPages().indexOf(node as HTMLDivElement);
        return idx >= 0 ? idx : undefined;
      }
      node = node.parentNode;
    }
    return undefined;
  };

  // ── Per-page header / footer chrome (page numbers etc.) ─────────
  // Chrome lives inside each page div as inert, absolutely-positioned
  // nodes in the margin zone. It is REMOVED before every reflow +
  // serialization (so it never moves between pages, never counts as
  // content, and never saves into the source) and RE-STAMPED after.
  const CHROME_SELECTOR = ".pagedly-ce-header, .pagedly-ce-footer, .pagedly-ce-watermark, .pagedly-ce-running-head, .pagedly-ce-footnotes";
  // Repeated table headers (P0-3) are inert decoration too — stripped
  // before reflow/serialization and regenerated after, exactly like the
  // page chrome above.
  const REPEATED_THEAD_SELECTOR = ".pagedly-repeated-thead";
  const NON_SOURCE_DECORATION_SELECTOR = `${CHROME_SELECTOR}, ${REPEATED_THEAD_SELECTOR}`;

  const removePageChrome = (root: ParentNode = contentRef.current ?? document) => {
    for (const el of Array.from(root.querySelectorAll(NON_SOURCE_DECORATION_SELECTOR))) {
      el.remove();
    }
  };

  // Serialize the page content for the host, stripping the inert
  // decorations (chrome / page numbers, repeated table headers) so they
  // never reach the saved source. Shared by onChange + getHTML().
  const serializeForSource = (): string =>
    getPages()
      .map((p) => {
        if (!p.querySelector(NON_SOURCE_DECORATION_SELECTOR)) return p.innerHTML;
        const clone = p.cloneNode(true) as HTMLElement;
        removePageChrome(clone);
        return clone.innerHTML;
      })
      .join("")
      // Strip zero-width boundary markers (used transiently to exit inline
      // emphasis after a markdown autoformat) so they never reach saved source.
      .replace(/​/g, "")
      // Strip transient block anchor ids — they live only in the DOM for
      // in-session addressing and must never reach saved source (keeps the
      // output deterministic + clean regardless of reflow/split timing).
      .replace(/\s+data-pid="[^"]*"/g, "");

  // ── Stable per-block anchor ids (paraId) ─────────────────────────
  // Live-DOM-only ids for in-session block addressing (agent patches). A block
  // keeps its id once assigned (creation-order, never renumbered), so anchors
  // are stable across reflow/moves; stripped on serialize (above) so they never
  // pollute saved source or affect the incremental==full invariant (sig()
  // compares text distribution, not attributes).
  const BLOCK_CHILD_SELECTOR =
    "p, h1, h2, h3, h4, h5, h6, blockquote, pre, ul, ol, table, figure, hr, div.pagedly-page-break";
  const topLevelBlocks = (): HTMLElement[] => {
    const out: HTMLElement[] = [];
    for (const page of getPages()) {
      for (const child of Array.from(page.children) as HTMLElement[]) {
        if (child.matches(NON_SOURCE_DECORATION_SELECTOR)) continue;
        if (child.tagName === "TEMPLATE") continue;
        if (child.matches(BLOCK_CHILD_SELECTOR)) out.push(child);
      }
    }
    return out;
  };
  const ensureParaIds = (): HTMLElement[] => {
    const blocks = topLevelBlocks();
    for (const b of blocks) {
      if (!b.getAttribute("data-pid")) {
        b.setAttribute("data-pid", `b${paraIdCounterRef.current++}`);
      }
    }
    return blocks;
  };

  const DEFAULT_EMIT_DEBOUNCE_MS = 120;
  const emitChange = () => {
    if (!contentRef.current) return;
    const cb = onChangeRef.current;
    if (cb) cb(serializeForSource());
  };
  const scheduleEmitChange = () => {
    if (emitChangeTimerRef.current !== null) {
      window.clearTimeout(emitChangeTimerRef.current);
    }
    const delay = changeDebounceRef.current ?? DEFAULT_EMIT_DEBOUNCE_MS;
    emitChangeTimerRef.current = window.setTimeout(() => {
      emitChangeTimerRef.current = null;
      emitChange();
    }, delay);
  };

  const substitutePlaceholders = (
    html: string,
    displayPage: number,
    total: number,
  ): string =>
    html
      .replace(/\{page\}/g, String(displayPage))
      .replace(/\{total\}/g, String(total));

  const buildChromeNode = (
    kind: "header" | "footer",
    spec: { left?: string; right?: string },
    displayPage: number,
    total: number,
  ): HTMLDivElement => {
    const div = document.createElement("div");
    div.className = `pagedly-ce-${kind}`;
    div.setAttribute("contenteditable", "false");
    div.setAttribute("aria-hidden", "true");
    const left = document.createElement("span");
    left.className = "pagedly-ce-chrome-left";
    left.innerHTML = substitutePlaceholders(spec.left ?? "", displayPage, total);
    const right = document.createElement("span");
    right.className = "pagedly-ce-chrome-right";
    right.innerHTML = substitutePlaceholders(spec.right ?? "", displayPage, total);
    div.appendChild(left);
    div.appendChild(right);
    return div;
  };

  const stampPageChrome = () => {
    const header = pageHeaderRef.current;
    const footer = pageFooterRef.current;
    const mark = watermarkRef.current;
    const rh = runningHeadRef.current;
    const content = contentRef.current;
    const footnotesPresent = content ? hasFootnotes(content) : false;
    const xrefsPresent = !!content?.querySelector(".pagedly-xref[data-xref-index]");
    if (!header && !footer && !mark && !rh && !footnotesPresent && !xrefsPresent) return;
    const pages = getPages();
    // Per-page footnotes: number refs (doc order) + stamp the bottom-margin
    // area for each page that carries refs. Inert (in CHROME_SELECTOR), so it's
    // stripped before reflow + serialize — no fit-loop / invariant contact.
    if (footnotesPresent && content) stampFootnotes(content, pages);
    // Cross-references resolve to their target heading's laid-out page.
    if (xrefsPresent && content) resolveCrossRefs(content);
    const total = pages.length;
    // Section-aware page numbering: {page} restarts at 1 on any page that begins
    // a new section (contains a .pagedly-section-break). No section breaks → the
    // usual global 1..N. Computed here in the (inert) chrome pass only.
    const hasSections = !!content?.querySelector(".pagedly-section-break");
    let sectionPage = 0;
    const displayNumberFor = (page: HTMLElement, i: number): number => {
      if (!hasSections) return i + 1;
      if (i === 0 || page.querySelector(".pagedly-section-break")) sectionPage = 1;
      else sectionPage += 1;
      return sectionPage;
    };
    // Running head: track the governing heading as we walk pages top-to-bottom.
    const rhSelector = rh ? (rh.level ? `h${rh.level}` : "h1, h2") : "";
    let rhText = "";
    pages.forEach((page, i) => {
      const displayPage = displayNumberFor(page, i);
      if (rh) {
        const hs = page.querySelectorAll(rhSelector);
        if (hs.length) rhText = (hs[hs.length - 1].textContent ?? "").trim();
        if (rhText) {
          const rhDiv = document.createElement("div");
          rhDiv.className = "pagedly-ce-running-head";
          rhDiv.setAttribute("contenteditable", "false");
          rhDiv.setAttribute("aria-hidden", "true");
          rhDiv.textContent = rhText;
          page.appendChild(rhDiv);
        }
      }
      const suppressFirst = differentFirstPageRef.current && i === 0;
      if (header && !suppressFirst) page.appendChild(buildChromeNode("header", header, displayPage, total));
      if (footer && !suppressFirst) page.appendChild(buildChromeNode("footer", footer, displayPage, total));
      if (mark) {
        // Inert, absolutely positioned (out of flow → no effect on the
        // clientHeight measurement), stripped before reflow + serialize.
        const wm = document.createElement("div");
        wm.className = "pagedly-ce-watermark";
        wm.setAttribute("contenteditable", "false");
        wm.setAttribute("aria-hidden", "true");
        wm.textContent = mark;
        page.appendChild(wm);
      }
    });
  };

  // P0-3: when a table is split across pages, each continuation fragment
  // gets a copy of the origin's <thead> so the header row repeats on
  // every page the table spans. Continuation fragments share the origin's
  // `s_tag` (set by the forward-split). The clone is inert + class-marked
  // so removePageChrome() strips it before reflow + serialization and it
  // never lands in the saved source. Stamped AFTER reflow, so on a table
  // that spans pages the continuation page grows by one header row's
  // height (acceptable — see BUGS_AND_FIXES known limitations).
  const stampRepeatedTableHeads = () => {
    const content = contentRef.current;
    if (!content) return;
    const originBySTag = new Map<string, Element>();
    for (const table of Array.from(content.querySelectorAll("table"))) {
      const sTag = (table as unknown as { s_tag?: string }).s_tag;
      if (!sTag) continue; // standalone table — never split
      const origin = originBySTag.get(sTag);
      if (!origin) {
        originBySTag.set(sTag, table);
        continue;
      }
      // `table` is a continuation fragment of `origin`.
      if (table.querySelector(":scope > thead")) continue;
      const originThead = origin.querySelector(":scope > thead");
      if (!originThead) continue;
      const clone = originThead.cloneNode(true) as HTMLElement;
      clone.classList.add("pagedly-repeated-thead");
      clone.setAttribute("contenteditable", "false");
      clone.setAttribute("aria-hidden", "true");
      table.insertBefore(clone, table.firstChild);
    }
  };

  // Run the fit loop with the SAME strip→fit→stamp protocol the input handler
  // uses, so caller-driven reflows (the public handle's reflow()/setHTML(), the
  // TOC fixpoint loop, host/agent calls) measure clean content and end with the
  // page chrome correctly re-stamped. Calling fitContentOverPages() bare would
  // (a) measure absolutely-positioned footers / in-flow repeated theads as
  // content and produce different boundaries than a normal pass, and (b) for
  // setHTML, leave page numbers unstamped until the first edit.
  const reflowWithChrome = (editIndex?: number) => {
    const content = contentRef.current;
    if (content) removePageChrome(content);
    fitContentOverPages(editIndex);
    stampPageChrome();
    stampRepeatedTableHeads();
  };

  // ── Undo / redo machinery ───────────────────────────────────────
  const captureSnapshot = (): UndoSnapshot | null => {
    const content = contentRef.current;
    if (!content) return null;
    return {
      html: content.innerHTML,
      selection: serializeSelection(content),
    };
  };

  // Commit the CURRENT state to the undo stack. Called debounced from
  // onInput (after each change settles) and synchronously flushed
  // before an undo/redo so the latest edit is always on the stack.
  const commitUndoSnapshot = () => {
    if (isRestoringRef.current) return;
    const snap = captureSnapshot();
    if (!snap) return;
    // The debounced edit is now resolved — clear the pending flag FIRST, even on
    // the dedup path below, so canUndo() doesn't keep reporting a phantom pending
    // edit after a no-op change settles.
    pendingEditRef.current = false;
    const stack = undoStackRef.current;
    // Skip if identical to the current top (no real change). No fresh content, so
    // the redo branch stays valid.
    if (stack.length > 0 && stack[stack.length - 1].html === snap.html) {
      return;
    }
    stack.push(snap);
    if (stack.length > UNDO_LIMIT) stack.shift();
    // Any fresh edit invalidates the redo branch.
    redoStackRef.current = [];
  };

  const scheduleUndoSnapshot = () => {
    if (isRestoringRef.current) return;
    pendingEditRef.current = true;
    if (undoTimerRef.current !== null) {
      window.clearTimeout(undoTimerRef.current);
    }
    undoTimerRef.current = window.setTimeout(() => {
      undoTimerRef.current = null;
      commitUndoSnapshot();
    }, 350);
  };

  const flushPendingSnapshot = () => {
    if (undoTimerRef.current !== null) {
      window.clearTimeout(undoTimerRef.current);
      undoTimerRef.current = null;
    }
    commitUndoSnapshot();
  };

  const restoreSnapshot = (snap: UndoSnapshot) => {
    const content = contentRef.current;
    if (!content) return;
    isRestoringRef.current = true;
    content.innerHTML = snap.html;
    refreshPageStyles();
    restoreSelectionFrom(content, snap.selection);
    isRestoringRef.current = false;
    // Notify the host of the reverted content. MUST go through serializeForSource
    // — the snapshot html is captured after stampPageChrome, so the live DOM now
    // carries page-number footers, repeated theads, watermarks and data-pid. The
    // serializer strips all of that; emitting raw innerHTML here would leak inert
    // chrome into the host's saved source (and autosave would persist it).
    const cb = onChangeRef.current;
    if (cb) cb(serializeForSource());
  };

  const performUndo = () => {
    flushPendingSnapshot();
    const undoStack = undoStackRef.current;
    // The top of the stack is the current state; we need the one
    // before it. Need at least 2 entries to have somewhere to go.
    if (undoStack.length < 2) return;
    const current = undoStack.pop()!;
    redoStackRef.current.push(current);
    restoreSnapshot(undoStack[undoStack.length - 1]);
  };

  const performRedo = () => {
    // Mirror performUndo: commit any debounced-but-uncommitted edit first. If
    // there IS fresh uncommitted typing, flushing commits it and clears the redo
    // branch (a new edit invalidates redo — standard editor semantics), so the
    // typed text is preserved instead of being silently destroyed by the restore.
    flushPendingSnapshot();
    const redoStack = redoStackRef.current;
    if (redoStack.length === 0) return;
    const next = redoStack.pop()!;
    undoStackRef.current.push(next);
    restoreSnapshot(next);
  };

  // The block element (direct child of a page) the caret currently sits in —
  // used to re-anchor a chunked paste between animation frames.
  const currentCaretBlock = (): HTMLElement | null => {
    const content = contentRef.current;
    const sel = window.getSelection();
    if (!content || !sel || sel.rangeCount === 0) return null;
    let node: Node | null = sel.getRangeAt(0).startContainer;
    while (node && node !== content) {
      if (
        node.nodeType === Node.ELEMENT_NODE &&
        (node.parentElement?.classList.contains("pagedly-ce-page") ?? false)
      ) {
        return node as HTMLElement;
      }
      node = node.parentNode;
    }
    return null;
  };

  // Insert pasted HTML. A normal-size paste goes straight through
  // execCommand("insertHTML") — the browser handles block-splitting, section
  // anchors, selection-replace and caret correctly. But execCommand's own
  // machinery is ~O(n^1.5): pasting a whole document (e.g. 2000 paragraphs)
  // blocks the main thread for ~2s in ONE task — a hard freeze.
  //
  // For a large paste we therefore feed execCommand the blob in CHUNKS, one per
  // animation frame, so no single task is long: the first chunk lands
  // immediately (the tab stays responsive between the rest, content streams
  // in). Each subsequent chunk re-anchors the caret to the end of the last
  // inserted block — a real node, so no stray DOM marker can leak into the
  // saved source, and stray interaction between frames can't misplace it.
  const PASTE_CHUNK_THRESHOLD = 160; // top-level blocks; below → single insert
  const PASTE_CHUNK_BLOCKS = 80;
  const insertHtmlPaste = (htmlStr: string) => {
    const content = contentRef.current;
    if (!content) return;
    const tpl = document.createElement("template");
    tpl.innerHTML = htmlStr;
    const topNodes = Array.from(tpl.content.childNodes);
    const blockCount = topNodes.reduce(
      (n, x) => n + (x.nodeType === Node.ELEMENT_NODE ? 1 : 0),
      0,
    );
    // Small paste, or one giant indivisible block: a single execCommand is
    // both correct and fast enough.
    if (blockCount <= PASTE_CHUNK_THRESHOLD) {
      document.execCommand("insertHTML", false, htmlStr);
      return;
    }
    const serialize = (nodes: ChildNode[]): string => {
      const d = document.createElement("div");
      for (const nd of nodes) d.appendChild(nd.cloneNode(true));
      return d.innerHTML;
    };
    const chunks: string[] = [];
    for (let i = 0; i < topNodes.length; i += PASTE_CHUNK_BLOCKS) {
      chunks.push(serialize(topNodes.slice(i, i + PASTE_CHUNK_BLOCKS)));
    }
    pasteInProgressRef.current = true;
    // First chunk synchronously — handles selection-replace + initial caret.
    document.execCommand("insertHTML", false, chunks[0]);
    let anchor = currentCaretBlock();
    let k = 1;
    const step = () => {
      const c = contentRef.current;
      if (!c || k >= chunks.length) {
        pasteInProgressRef.current = false;
        if (c) {
          // One emit + one undo step for the whole paste.
          scheduleEmitChange();
          scheduleUndoSnapshot();
        }
        return;
      }
      // Re-anchor the caret to the end of the last inserted block so the next
      // chunk appends in order even if focus/selection drifted between frames.
      if (anchor && c.contains(anchor)) {
        c.focus({ preventScroll: true });
        const r = document.createRange();
        r.selectNodeContents(anchor);
        r.collapse(false);
        const s = window.getSelection();
        s?.removeAllRanges();
        s?.addRange(r);
      }
      document.execCommand("insertHTML", false, chunks[k]);
      anchor = currentCaretBlock() ?? anchor;
      k++;
      requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  };

  // Fast O(n) pre-slice for a massively over-full page — the bulk-insert /
  // paste / initial-load case where a whole document was dumped into ONE
  // page. The normal word-level forward split grinds such a page down one
  // piece at a time, re-measuring the giant page's height after every move
  // → O(n²) (a 100-page paste froze the tab for ~2 minutes). Here we
  // partition the page's blocks into ~page-sized bins in a single layout
  // pass (batch all height reads, then pure-arithmetic packing, then pure
  // DOM moves with no interleaved measuring), so the per-page fitting that
  // follows only ever sees a roughly page-sized page. Boundaries are
  // approximate on purpose — the backward/forward loop in fitContentOverPages
  // fine-tunes each one to the pixel afterwards.
  //
  // Returns true if it re-sliced (caller must refresh its page list).
  // Only fires for the pathological "much more than one page in one page"
  // regime; ordinary typing (a page a line or two over) takes the precise
  // word-level path untouched.
  const BULK_PREDISTRIBUTE_FACTOR = 2;
  const bulkPredistribute = (
    page: HTMLDivElement,
    targetHeight: number,
  ): boolean => {
    const content = contentRef.current;
    if (!content) return false;
    if (page.clientHeight <= targetHeight * BULK_PREDISTRIBUTE_FACTOR) return false;

    const nodes = Array.from(page.childNodes);
    // Block-level slicing needs at least two element children; a single
    // giant block (e.g. one huge paragraph) is left to the word-level
    // forward split, which can break inside a block.
    const elementCount = nodes.reduce(
      (n, node) => n + (node.nodeType === Node.ELEMENT_NODE ? 1 : 0),
      0,
    );
    if (elementCount < 2) return false;

    // Content budget = page inner box minus vertical padding. targetHeight
    // is the full page clientHeight (content + padding), so a page overflows
    // once its content stack passes (targetHeight − padding).
    const cs = getComputedStyle(page);
    const padV =
      (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
    const budget = Math.max(1, targetHeight - padV);

    // Phase 1 — batch every height read with NO interleaved writes, so the
    // browser does one layout and the rest are cached (O(n), not O(n²)).
    // offsetHeight EXCLUDES margins, so summed bins skew slightly OVER-full —
    // a deliberate choice: an over-full bin is settled by the existing
    // forward-PUSH path, which converges to exactly the full-reflow result
    // (the locked `incremental == full` invariant). Under-counting toward
    // under-full bins instead would lean on the backward-MERGE settle, which
    // lands a boundary one block off and breaks that invariant. The cost is
    // only that, during a huge PASTE, later pages parked for the idle settle
    // are transiently over-full (~sub-second) until it drains; initial-load /
    // setHTML use the full synchronous pass and never show it. See
    // BUGS_AND_FIXES.
    const heights = nodes.map((node) =>
      node.nodeType === Node.ELEMENT_NODE
        ? (node as HTMLElement).offsetHeight
        : 0,
    );

    // Phase 2 — greedy bin-packing by cumulative height (pure arithmetic).
    // A block that alone exceeds the budget gets its own bin (the word-level
    // split breaks it across pages later).
    const bins: ChildNode[][] = [];
    let bin: ChildNode[] = [];
    let acc = 0;
    for (let k = 0; k < nodes.length; k++) {
      const h = heights[k];
      if (bin.length > 0 && acc + h > budget) {
        bins.push(bin);
        bin = [];
        acc = 0;
      }
      bin.push(nodes[k]);
      acc += h;
    }
    if (bin.length) bins.push(bin);

    // It all fits in one page after all — nothing to gain.
    if (bins.length < 2) return false;

    // Phase 3 — distribute. Bin 0 stays in `page`; later bins go into fresh
    // sibling pages inserted in order right after it. appendChild MOVES the
    // node; no clientHeight reads here, so no forced layout until the caller
    // measures. Whole blocks only — never splits one, so s_tag-watermarked
    // halves and do-not-break atoms (img/figure) are preserved.
    let anchor: HTMLDivElement = page;
    bins.forEach((b, bi) => {
      let dest: HTMLDivElement;
      if (bi === 0) {
        dest = page;
      } else {
        dest = document.createElement("div");
        applyPageStyle(dest);
        content.insertBefore(dest, anchor.nextSibling);
      }
      for (const node of b) dest.appendChild(node);
      anchor = dest;
    });
    return true;
  };

  // `editIndex` enables INCREMENTAL reflow: when the caller knows which
  // page the edit touched, we only re-paginate from the page before it
  // forward and stop once the cascade settles — instead of walking every
  // page from 0 on every keystroke (the old O(all-pages) behaviour that
  // made large documents sluggish). Omit it (or after adopting orphans)
  // for a full pass.
  const fitContentOverPages = (
    editIndex?: number,
    isSettlePass = false,
    drainToEnd = false,
  ) => {
    if (fitInProgressRef.current) return;
    if (!pagesHeightRef.current) return;
    const content = contentRef.current;
    if (!content) return;

    fitInProgressRef.current = true;
    let adoptedOrphans = false;

    // Adoption pass: any direct child of `content` that isn't a
    // `.pagedly-ce-page` is an "orphan" — Chrome's default Backspace on a
    // blank editor can promote the placeholder block out of its page
    // div, leaving content as a sibling of the page (which renders
    // OUTSIDE the page card, in the desk area). Move every orphan
    // into the first page so nothing escapes the page boundary.
    //
    // Skipped on settle/drain passes: orphans are only ever created by a user
    // edit, which always runs a non-settle pass first — so scanning every
    // direct child of `content` (O(pages)) on each idle drain slice is pure
    // overhead. This keeps a drain slice's cost proportional to its window.
    if (!isSettlePass) {
      let firstPage = content.querySelector<HTMLDivElement>(".pagedly-ce-page");
      const orphans: ChildNode[] = [];
      for (const child of Array.from(content.childNodes)) {
        if (
          child.nodeType === Node.ELEMENT_NODE &&
          (child as Element).classList?.contains("pagedly-ce-page")
        ) {
          continue;
        }
        orphans.push(child);
      }
      if (orphans.length > 0) {
        adoptedOrphans = true;
        if (!firstPage) {
          firstPage = document.createElement("div");
          // Insert AT THE TOP so the page card is the first visible
          // child, with orphans about to be moved INTO it.
          content.insertBefore(firstPage, content.firstChild);
          applyPageStyle(firstPage);
        }
        // Prepend orphans in original order at the start of the
        // first page so they keep their relative ordering.
        for (let i = orphans.length - 1; i >= 0; i--) {
          firstPage.insertBefore(orphans[i], firstPage.firstChild);
        }
      }
    }

    // Preserve cursor across DOM surgery.
    const sel = window.getSelection();
    const startMarker = document.createElement("pagedly-marker");
    const endMarker = document.createElement("pagedly-marker");
    let markersInserted = false;
    if (
      sel &&
      sel.rangeCount &&
      sel.anchorNode &&
      content.contains(sel.anchorNode)
    ) {
      try {
        const range = sel.getRangeAt(0);
        range.insertNode(startMarker);
        range.collapse(false);
        range.insertNode(endMarker);
        markersInserted = true;
      } catch {
        /* selection not in editable area */
      }
    }

    let pages = getPages();
    // If all pages are gone (e.g. user backspaced the last placeholder
    // out of existence and Chrome's default action removed the page
    // div too) recreate a fresh first page with a placeholder block
    // so the rest of the algorithm has something to work with — and
    // so the empty-doc protection at the end of this function has
    // a page to seed into.
    if (pages.length === 0) {
      const newFirst = document.createElement("div");
      content.appendChild(newFirst);
      applyPageStyle(newFirst);
      newFirst.innerHTML = "<div><br></div>";
      pages = getPages();
    }
    // Reserve bottom space for footnotes when the document has any: content
    // breaks earlier on every page so the per-page footnote area (stamped into
    // the bottom margin by the chrome pass) has room without overlapping. A
    // fixed reserve keeps it deterministic — both incremental + full reflow
    // subtract the same amount, so incremental==full holds.
    const FOOTNOTE_RESERVE_PX = 72;
    const footnoteReserve =
      content && hasFootnotes(content) ? FOOTNOTE_RESERVE_PX : 0;
    const targetHeight = pagesHeightRef.current - footnoteReserve;

    // Safety cap against runaway page creation (algorithm failing to make
    // progress). High enough for long documents now that the editor is
    // meant to scale past a few pages.
    const MAX_PAGES = 5000;

    // Incremental pass: start one page before the edit (a margin so a
    // boundary-adjacent edit still rebalances correctly) and break as soon
    // as a page at/after the edit settles without any content moving — at
    // that point every later page is already balanced. A full pass
    // (no editIndex, or after adopting orphans) runs from 0 with no early
    // exit so a fresh document paginates completely.
    const fullPass = editIndex === undefined || adoptedOrphans;
    const startAt = fullPass
      ? 0
      : Math.max(0, Math.min(editIndex, pages.length - 1) - 1);

    // Bound a pass to a window of pages so it never re-paginates an unbounded
    // run synchronously — the dominant cost when editing early in (or loading)
    // a long document, since every clientHeight read flushes layout for the
    // whole growing doc. Whatever doesn't finish inside the window is parked
    // and settled later, in idle time.
    //   - Incremental edit: a small window keeps per-keystroke cost O(window).
    //   - Full pass (initial load / setHTML / reflow): a larger budget so the
    //     first screenful-plus paginates synchronously, then the rest drains
    //     in idle instead of freezing the tab on a one-shot load. A doc that
    //     fits within the budget still completes in one synchronous pass
    //     (no deferral, no behaviour change for normal-size docs).
    const REFLOW_WINDOW = 6;
    const FULL_PASS_SYNC_BUDGET = 16;
    // A full-document drain runs cooperatively in idle time, so prefer SHORTER
    // slices: each one measures pages against the whole DOM (a layout flush per
    // clientHeight read), so a small window keeps any single idle slice brief
    // and unlikely to drop a frame if it overlaps a stray interaction. The
    // total settles in more (cheaper) steps.
    const DRAIN_WINDOW = 3;
    const syncBudget = fullPass
      ? FULL_PASS_SYNC_BUDGET
      : drainToEnd
        ? DRAIN_WINDOW
        : REFLOW_WINDOW;
    let exitReason: "settled" | "window" | "end" = "end";
    let processed = 0;
    let lastIndex = startAt;
    // Did this pass slice a massively over-full page? If so the leftover backlog
    // is full-document-sized (a big paste / bulk insert), so its drain should be
    // treated like a full-load drain — cooperative, small idle slices — not a
    // short edit-cascade settle.
    let didBulk = false;

    for (let i = startAt; i < pages.length && i < MAX_PAGES; i++) {
      if (processed >= syncBudget) {
        exitReason = "window";
        lastIndex = i;
        break;
      }
      processed++;
      lastIndex = i;
      const page = pages[i];
      let nextPage = pages[i + 1] ?? null;
      const beforeHtml = page.innerHTML;
      let pushed = false;

      // Fast path for a massively over-full page (e.g. a large paste that
      // dumped a whole document into one page): slice it into ~page-sized
      // pages first, so the word-level split below stays O(n), not O(n²).
      if (bulkPredistribute(page, targetHeight)) {
        didBulk = true;
        pages = getPages();
        nextPage = pages[i + 1] ?? null;
      }

      // Forced break: peel content after an internal page/section break (or a
      // break-before block that isn't first) onto a fresh page so the break
      // starts a new sheet on screen. Monotonic (only adds pages) → terminates.
      const peelStart = forcedBreakPeelStart(page);
      if (peelStart) {
        const fresh = document.createElement("div");
        applyPageStyle(fresh);
        page.after(fresh);
        let node: Node | null = peelStart;
        const toMove: Node[] = [];
        while (node) { toMove.push(node); node = node.nextSibling; }
        for (const n of toMove) fresh.appendChild(n);
        pages = getPages();
        nextPage = pages[i + 1] ?? null;
      }

      // Backward propagation: pull from next if room — UNLESS a forced break
      // separates the two pages (pulling would cross it).
      if (
        page.clientHeight <= targetHeight &&
        nextPage &&
        !forcedBoundaryBetween(page, nextPage)
      ) {
        moveChildrenBackwardsWithMerging(page, nextPage, () => {
          return (
            !nextPage!.childNodes.length || page.clientHeight > targetHeight
          );
        });
      }

      // Forward propagation: push to next if overflow.
      if (page.clientHeight > targetHeight) {
        if (!nextPage) {
          nextPage = document.createElement("div");
          content.appendChild(nextPage);
          applyPageStyle(nextPage);
          pages = getPages();
        }
        moveChildrenForwardRecursively(
          page,
          nextPage,
          () => page.clientHeight <= targetHeight,
          doNotBreakRef.current,
        );
        pushed = true;
      }

      // keep-with-next: if this page ends with a keep-with-next block and the
      // next page already has content, move that block down so it sits with its
      // successor. Guarded by kids.length > 1 (never empties a page) → bounded.
      if (nextPage && pageContentEls(nextPage).length > 0) {
        const kids = pageContentEls(page);
        const last = kids[kids.length - 1];
        if (last && isKeepWithNext(last) && kids.length > 1) {
          nextPage.insertBefore(last, nextPage.firstChild);
          pushed = true;
        }
      }

      // Clean: remove empty next page.
      if (nextPage && nextPage.childNodes.length === 0) {
        nextPage.remove();
        pages = getPages();
      }

      // Settle detection (incremental edit only): if this page is at/after
      // the edit and nothing entered or left it, the cascade has ended and
      // every later page is untouched — stop here. Skipped when draining a
      // full-pass backlog (drainToEnd): an over-full backlog page can look
      // "unchanged" for one iteration without the run being over, so we must
      // process every page to the end instead of trusting an early settle.
      if (
        !fullPass &&
        !drainToEnd &&
        i >= editIndex! &&
        !pushed &&
        page.innerHTML === beforeHtml
      ) {
        exitReason = "settled";
        break;
      }
    }

    // Deferred-settle bookkeeping. When a pass outruns its sync window, park
    // the frontier and keep settling it in idle time; otherwise clear it once
    // the run that owns it has reached its end.
    if (exitReason === "window") {
      // A settle/drain continuation advances the frontier to where it
      // stopped; a fresh pass (edit or full) only ever pulls it earlier so a
      // still-dirty upstream region is never skipped.
      deferredReflowFromRef.current = isSettlePass
        ? lastIndex
        : Math.min(deferredReflowFromRef.current ?? Infinity, lastIndex);
      // A full pass, a continuation already draining one, or any pass that
      // sliced a bulk over-full page (a big paste) must run to the last page
      // and drain cooperatively; an edit must never downgrade a pending full
      // drain.
      deferredDrainToEndRef.current =
        deferredDrainToEndRef.current || fullPass || drainToEnd || didBulk;
      scheduleDeferredSettle();
    } else if (isSettlePass || fullPass) {
      // The owning run finished within this pass: a settle/drain continuation
      // that didn't hit the window has drained everything it was parked for,
      // and a full pass that completed paginated the whole doc from 0. Either
      // way the backlog is gone — clear the frontier. (A plain edit that
      // happens to settle must NOT clear it, lest it abandon a downstream
      // region parked by an earlier pass.)
      deferredReflowFromRef.current = null;
      deferredDrainToEndRef.current = false;
      cancelDeferredSettle();
    }

    // (No tighten / force-migrate pass — they caused mid-word breaks
    // and content reshuffling that looked like the page was "jumping
    // weirdly". Word-level forward split + the natural backward+
    // forward loop above gives Google Docs / Word style pagination:
    // boundaries always fall at word breaks, and the boundary shifts
    // smoothly as content reflows. Trade-off: some single-char edits
    // won't visibly shift the boundary — that's how Word behaves too.)

    // Normalise text nodes per page — only the window we actually touched
    // (startAt..lastIndex), plus one trailing page that may have received
    // pushed-forward content. The old `slice(startAt)` normalised every page
    // to the end of the document on EVERY pass, which made each idle drain
    // slice O(document) instead of O(window) — a dominant per-slice cost on
    // large docs. Pages past the window are normalised when the drain reaches
    // them.
    for (const p of getPages().slice(startAt, lastIndex + 2)) p.normalize();

    // Restore selection.
    if (markersInserted && document.body.contains(startMarker)) {
      const range = document.createRange();
      range.setStart(startMarker, 0);
      if (document.body.contains(endMarker)) range.setEnd(endMarker, 0);
      sel?.removeAllRanges();
      sel?.addRange(range);
    }
    startMarker.remove();
    endMarker.remove();

    // Empty-doc protection: AFTER marker removal we may discover the
    // first page has no usable cursor landing.
    //
    // The naive "no children" check isn't enough — the letter editor
    // peppers the doc with `<template data-section-anchor>` elements
    // for section anchoring. After Cmd+A + Backspace those templates
    // survive (browser default doesn't delete them) AND any heading
    // wrappers become empty (`<h2><br></h2>`). The page LOOKS empty
    // (templates are display:none, headings with just <br> render as
    // a blank line) but `childNodes.length` is non-zero, so the old
    // check skipped reseed.
    //
    // Worse: if Chrome placed the cursor inside a <template> it has
    // NO RENDERED CARET position — visually the cursor disappears
    // into the page background, or worse, gets clamped into the
    // surrounding desk margin. User reported "cursor flashing off in
    // the grey area" — that's this state.
    //
    // Fix: detect "effectively empty" (no visible text + no <br>
    // placeholder in a visible block) and seed a placeholder block
    // AFTER any templates so anchors are preserved. Then put the
    // caret into the placeholder.
    {
      const isInert = (n: Node): boolean => {
        if (n.nodeType !== Node.ELEMENT_NODE) return false;
        const el = n as Element;
        const tag = el.tagName.toLowerCase();
        return tag === "template" || tag === "script" || tag === "style";
      };
      const hasVisibleContent = (page: Element): boolean => {
        for (const child of Array.from(page.childNodes)) {
          if (isInert(child)) continue;
          if (child.nodeType === Node.TEXT_NODE) {
            if ((child.textContent ?? "").trim().length > 0) return true;
          } else if (child.nodeType === Node.ELEMENT_NODE) {
            const el = child as Element;
            // Empty heading / paragraph with only a <br> isn't
            // visible content — it renders as a blank line and the
            // caret may or may not land in it usably. Treat as empty.
            const text = (el.textContent ?? "").trim();
            if (text.length > 0) return true;
            // Block with a <br> still gives the caret a landing
            // (so we don't need to seed) IFF the block itself isn't
            // a heading-only structure. Allow <div>/<p> with <br>.
            const tag = el.tagName.toLowerCase();
            if (
              (tag === "div" || tag === "p") &&
              el.children.length === 1 &&
              el.children[0].tagName.toLowerCase() === "br"
            ) {
              return true;
            }
          }
        }
        return false;
      };

      let ps = getPages();
      if (ps.length === 0) {
        const newFirst = document.createElement("div");
        content.appendChild(newFirst);
        applyPageStyle(newFirst);
        ps = getPages();
      }
      if (!hasVisibleContent(ps[0])) {
        // Append a typable placeholder AFTER any leading templates
        // / anchor nodes so section-anchor markup is preserved.
        const placeholder = document.createElement("div");
        placeholder.appendChild(document.createElement("br"));
        ps[0].appendChild(placeholder);
        const range = document.createRange();
        range.setStart(placeholder, 0);
        range.collapse(true);
        sel?.removeAllRanges();
        sel?.addRange(range);
      }
    }

    fitInProgressRef.current = false;
  };

  // ── Deferred downstream settle ──────────────────────────────────
  // Continues a cascade the windowed incremental pass left unfinished,
  // a window at a time, during browser idle time. It only touches pages
  // downstream of the cursor, so the caret (preserved by the marker pass
  // inside fitContentOverPages) is never disturbed. Strips/re-stamps the
  // inert chrome around the reflow, like the input handler does.
  const runDeferredSettle = () => {
    settleIdleRef.current = null;
    const from = deferredReflowFromRef.current;
    const content = contentRef.current;
    if (from === null || !content) return;
    const wasFullDrain = deferredDrainToEndRef.current;
    removePageChrome(content);
    fitContentOverPages(from + 1, true, wasFullDrain);
    // Re-stamping chrome (page numbers, repeated table heads) is O(pages):
    // page numbers carry "/ total", so any change in page count restamps all.
    // For a long FULL drain that would be O(pages) on every slice (O(pages²)
    // overall) and is the bulk of each slice's cost — so defer it to the slice
    // that actually FINISHES the drain (frontier cleared). Short edit-cascade
    // settles still stamp every slice so page numbers never flicker mid-edit.
    const finished = deferredReflowFromRef.current === null;
    if (finished || !wasFullDrain) {
      stampPageChrome();
      stampRepeatedTableHeads();
    }
    // fitContentOverPages() has either advanced the frontier and
    // re-scheduled, or cleared it — nothing more to do here.
  };
  const scheduleDeferredSettle = () => {
    if (settleIdleRef.current !== null) return;
    const ric = (
      window as unknown as {
        requestIdleCallback?: (cb: () => void, opts?: { timeout?: number }) => number;
      }
    ).requestIdleCallback;
    // A full-document drain (big load / setHTML / reflow) runs PURELY
    // cooperatively — no idle timeout — so a settle slice never preempts the
    // user mid-scroll or mid-type. The content is all present; far pages just
    // finish settling a beat later, whenever the main thread is genuinely
    // idle. An edit-cascade settle keeps a short timeout so it completes
    // promptly around the caret (where the user is looking).
    const fullDrain = deferredDrainToEndRef.current;
    settleIdleRef.current = ric
      ? ric(runDeferredSettle, fullDrain ? {} : { timeout: 200 })
      : window.setTimeout(runDeferredSettle, fullDrain ? 200 : 32);
  };
  const cancelDeferredSettle = () => {
    if (settleIdleRef.current === null) return;
    const cic = (window as unknown as { cancelIdleCallback?: (h: number) => void })
      .cancelIdleCallback;
    if (cic) cic(settleIdleRef.current);
    else window.clearTimeout(settleIdleRef.current);
    settleIdleRef.current = null;
  };

  // ── Initial setup ──
  useLayoutEffect(() => {
    const content = contentRef.current;
    if (!content) return;

    // DEV instrumentation: count mount effect invocations. Should be 1
    // per real mount; if we see >1 without an intervening real unmount,
    // we've found a remount path that's running the seed logic again.
    if (typeof window !== "undefined" && (import.meta as { env?: { DEV?: boolean } }).env?.DEV) {
      const counter =
        ((window as unknown as Record<string, number>)["__phe_mount_count"] ?? 0) + 1;
      (window as unknown as Record<string, number>)["__phe_mount_count"] = counter;
      // eslint-disable-next-line no-console
      console.warn(`[pagedly-ce] mount useLayoutEffect run #${counter}`, {
        htmlLength: (html || "").length,
        existingPagesInDom: content.querySelectorAll(".pagedly-ce-page").length,
      });
    }

    // Build the first page div from scratch.
    content.innerHTML = "";
    const firstPage = document.createElement("div");
    content.appendChild(firstPage);
    applyPageStyle(firstPage);
    // Measure baseline page content height. With min-height set,
    // clientHeight reflects that minimum until content forces growth.
    pagesHeightRef.current = measureBaselineHeight(firstPage);
    // Seed initial HTML.
    firstPage.innerHTML = html || "<div><br></div>";
    fitContentOverPages();
    stampPageChrome();
    stampRepeatedTableHeads();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ── Live page-geometry change ──
  // When pageWidth/Height/padding props change (page-size, orientation, or
  // margin switch — e.g. DOCX import adopting the source margins), the
  // mount layout effect's baseline measurement is stale — it was taken for the
  // OLD page height, so the fit loop would keep paginating to the wrong height.
  // Re-apply the page styling, re-derive the baseline geometrically (an empty
  // page is exactly pageHeightPx tall), and re-paginate. Skipped on the first
  // run (the mount effect already handled it).
  useEffect(() => {
    if (!geomInitRef.current) {
      geomInitRef.current = true;
      return;
    }
    if (!contentRef.current) return;
    refreshPageStyles();
    pagesHeightRef.current = pageHeightPx + 1;
    reflowWithChrome();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pageWidthPx, pageHeightPx, pagePadding]);

  // ── Input handler ──
  useEffect(() => {
    const content = contentRef.current;
    if (!content) return;
    const onInput = (e: Event) => {
      const ie = e as InputEvent;
      const isDeletion =
        typeof ie.inputType === "string" && ie.inputType.startsWith("delete");

      // Remove per-page header/footer chrome before any DOM work so it
      // never moves between pages, never counts as content during
      // reflow, and never serializes into the source. Re-stamped at
      // the end of this handler.
      removePageChrome(content);

      // Strip Chrome's junk <span> wraps BEFORE pagination so the
      // s_tag matching chain isn't broken across page boundaries.
      unwrapPlainSpans(content, pasteFormattingRef.current === "rich");
      // Merge any adjacent text nodes that came out of the unwrap.
      content.normalize();

      // Snapshot the first text content on each page BEFORE pagination
      // so we can detect "the boundary didn't move" after.
      const beforeBoundary = isDeletion
        ? getPages().map(
            (p) => (p.textContent ?? "").slice(0, 30),
          )
        : null;

      // Incremental reflow: re-paginate only from the edited page forward.
      const editIndex = pageIndexOfSelection();
      const __reflowT0 =
        typeof performance !== "undefined" ? performance.now() : 0;
      fitContentOverPages(editIndex);
      // DEV-only perf hook (read by the smoke/debug harness). Gated behind
      // import.meta.env.DEV so it's dead-code-eliminated from production
      // builds and never pollutes a host's window.
      if (
        (import.meta as { env?: { DEV?: boolean } }).env?.DEV &&
        typeof window !== "undefined" &&
        typeof performance !== "undefined"
      ) {
        (window as unknown as { __pagedlyLastReflowMs?: number }).__pagedlyLastReflowMs =
          performance.now() - __reflowT0;
      }

      // After Backspace / Delete, if the boundary at any pair of
      // adjacent pages didn't actually visibly shift, attempt a
      // word-level force migration from the next page back to the
      // current page. BUT only commit it if the new word fits without
      // growing the page card — otherwise the migrated word wraps to
      // a new line that visually "bleeds" below the rest of the page
      // content (clipped by overflow:hidden, looks orphaned).
      //
      // If the word would overflow, we undo the migration and accept
      // that the boundary stays stuck for this keystroke. The user
      // can keep backspacing until enough chars are deleted for the
      // word to fit naturally — same as Word's actual behavior.
      if (isDeletion && beforeBoundary) {
        const psAfter = getPages();
        if (psAfter.length >= 2) {
          // Only inspect the boundary pairs around the edit (a stuck
          // boundary after a backspace is adjacent to where content was
          // removed). Scanning every pair would re-introduce O(all-pages)
          // work on each deletion. A full pass (editIndex undefined) still
          // scans everything.
          const lo = editIndex === undefined ? 0 : Math.max(0, editIndex - 1);
          const hi =
            editIndex === undefined
              ? psAfter.length - 2
              : Math.min(psAfter.length - 2, editIndex + 1);
          for (let i = lo; i <= hi; i++) {
            const nextFirstAfter = (
              psAfter[i + 1].textContent ?? ""
            ).slice(0, 30);
            const nextFirstBefore = beforeBoundary[i + 1] ?? "";
            if (
              nextFirstAfter !== nextFirstBefore ||
              nextFirstAfter.length === 0
            ) {
              continue;
            }
            // Tentatively force-migrate, then check if the page grew.
            // If yes, the migrated word wrapped to a new line — looks
            // orphaned. Roll back by reversing the exact word we just
            // moved (string-equality match).
            const heightBefore = psAfter[i].clientHeight;
            const migratedWord = forceMigrateOneWordBackwards(
              psAfter[i],
              psAfter[i + 1],
            );
            if (!migratedWord) continue;
            const heightAfter = psAfter[i].clientHeight;
            if (heightAfter > heightBefore) {
              undoForceMigrate(psAfter[i], psAfter[i + 1], migratedWord);
            }
          }
        }
      }

      // Notify the host of the change — debounced so a burst of typing
      // coalesces into one O(document) serialize + host re-parse instead
      // of paying it on every keystroke (the dominant felt-latency cost
      // at scale once reflow itself is incremental). serializeForSource
      // strips chrome, so re-stamping below is fine.
      //
      // Suppressed mid-chunked-paste: that path fires one input per chunk but
      // wants a single emit + single undo step at the very end (it calls them
      // itself once done), not O(chunks) of each.
      if (!pasteInProgressRef.current) {
        scheduleEmitChange();
      }

      // Re-stamp per-page chrome AFTER reflow so page numbers show on
      // screen / print but stay out of the saved source.
      stampPageChrome();
      stampRepeatedTableHeads();

      // Record an undo step once this edit settles. Debounced so a
      // burst of typing collapses into a single undo. Skipped while
      // we're mid-restore (restoreSnapshot sets isRestoringRef).
      if (!pasteInProgressRef.current) {
        scheduleUndoSnapshot();
      }
    };
    content.addEventListener("input", onInput as EventListener);

    // Seed the baseline snapshot so the very first edit has a state
    // to undo back to.
    if (undoStackRef.current.length === 0) {
      const seed = captureSnapshot();
      if (seed) undoStackRef.current.push(seed);
    }

    // Intercept undo / redo keyboard shortcuts. We own the stack, so
    // always preventDefault to stop the browser's native undo from
    // also firing (which would corrupt our restored DOM).
    const onUndoRedoKey = (e: KeyboardEvent) => {
      const mod = e.metaKey || e.ctrlKey;
      if (!mod) return;
      const key = e.key.toLowerCase();
      if (key === "z" && !e.shiftKey) {
        e.preventDefault();
        performUndo();
      } else if ((key === "z" && e.shiftKey) || key === "y") {
        e.preventDefault();
        performRedo();
      }
    };
    content.addEventListener("keydown", onUndoRedoKey);

    // Paste handler: sanitize before insertion. This kills Chrome's
    // "select-all + copy + paste makes everything larger" regression —
    // Chrome bakes the source's computed font-size into the pasted
    // spans, which then renders differently in the new context.
    const onPaste = (e: ClipboardEvent) => {
      if (readOnlyRef.current) {
        e.preventDefault();
        return;
      }
      const cd = e.clipboardData;
      if (!cd) return;
      const html = cd.getData("text/html");
      const text = cd.getData("text/plain");
      const rich = pasteFormattingRef.current === "rich";
      const sanitizer =
        sanitizePasteRef.current ??
        ((h: string) => defaultSanitizePastedHtml(h, { keepInlineStyles: rich }));
      if (html) {
        e.preventDefault();
        const cleaned = sanitizer(html);
        insertHtmlPaste(cleaned);
      } else if (text) {
        e.preventDefault();
        document.execCommand("insertText", false, text);
      }
      // Browser will fire `input` after our preventDefault path's
      // execCommand call too, so pagination will rerun via onInput.
    };
    content.addEventListener("paste", onPaste as EventListener);

    // beforeinput guard: swallow Backspace / Delete when the editor
    // is logically empty. Chrome's default action on an empty
    // contentEditable can promote the placeholder block out of its
    // page div (or remove the page div entirely), leaving subsequent
    // typing to land outside the page card. Easier to just block the
    // deletion when there's nothing to delete.
    const onBeforeInput = (e: Event) => {
      if (readOnlyRef.current) {
        e.preventDefault();
        return;
      }
      const ie = e as InputEvent;
      const t = ie.inputType;
      if (t !== "deleteContentBackward" && t !== "deleteContentForward") {
        return;
      }

      // Detect "selection covers the whole document" (e.g. Cmd+A
      // followed by Backspace). Safari's native handler wipes EVERY
      // child of the page — including `<template data-section-anchor>`
      // elements the letter editor uses to track which content belongs
      // to which section. Once those are gone, splitLetterEditorHtml
      // can't attribute subsequent typing to a section.
      //
      // Intercept and replace with a controlled clear: remove regular
      // content, KEEP <template> anchors. Place a fresh placeholder
      // <div><br></div> right after the FIRST template so user-typed
      // content lands in the first section by default.
      const sel = window.getSelection();
      if (sel && sel.rangeCount > 0) {
        const selText = sel.toString();
        const docText = content.textContent ?? "";
        // toString() returns visible text only — templates have no
        // visible text, so they're not in selText. If selText is the
        // entire visible doc, the user is select-all-deleting.
        if (
          selText.length > 0 &&
          docText.length > 0 &&
          selText.length >= docText.length
        ) {
          e.preventDefault();
          // Consolidate ALL templates (across all pages) onto the first
          // page in document order, then drop the other pages. This
          // gives the user a clean single-page reset while preserving
          // every section anchor — and lets us place a single
          // placeholder + cursor in the FIRST section (opening),
          // matching what the user expects after "clear and start
          // over".
          const allPages = getPages();
          if (allPages.length === 0) return;
          const allTemplates: Element[] = [];
          for (const page of allPages) {
            for (const child of Array.from(page.childNodes)) {
              if (
                child.nodeType === Node.ELEMENT_NODE &&
                (child as Element).tagName.toLowerCase() === "template"
              ) {
                allTemplates.push(child as Element);
              }
            }
          }
          // Clear every page and remove all but the first.
          for (let i = allPages.length - 1; i >= 1; i--) {
            allPages[i].remove();
          }
          const firstPage = allPages[0];
          firstPage.innerHTML = "";
          // Re-add templates in document order.
          for (const t of allTemplates) firstPage.appendChild(t);
          // Add ONE placeholder right after the FIRST template so typed
          // content lands in the first section (opening).
          const placeholder = document.createElement("div");
          placeholder.appendChild(document.createElement("br"));
          const firstTemplate = firstPage.querySelector("template");
          if (firstTemplate) {
            firstTemplate.parentNode?.insertBefore(
              placeholder,
              firstTemplate.nextSibling,
            );
          } else {
            firstPage.appendChild(placeholder);
          }
          // Caret into the placeholder.
          const range = document.createRange();
          range.setStart(placeholder, 0);
          range.collapse(true);
          sel.removeAllRanges();
          sel.addRange(range);
          // Dispatch an input event so React's onChange + pagination
          // see the change.
          content.dispatchEvent(
            new InputEvent("input", {
              bubbles: true,
              inputType: "deleteContent",
            }),
          );
          return;
        }
      }

      // Backspace at the very start of a block: handle the
      // cross-block merge ourselves. The browser's native handler
      // will happily delete the preceding <template
      // data-section-anchor> sibling — which silently re-attributes
      // every following block to the previous section. Worse, when
      // the previous block sits in a different section, the native
      // merge crosses the boundary without warning.
      //
      // Our controlled merge:
      //   - At offset 0 of a block, look back past inert siblings
      //     (templates, whitespace text) for the nearest real block.
      //   - If found AND it's in the same section → append the
      //     current block's children into it, remove the current
      //     block, place the caret at the merge boundary.
      //   - If found but in a DIFFERENT section → refuse the merge
      //     (preventDefault, no-op) so the section anchors survive.
      // Undo / redo for these structural mutations is handled by the
      // engine's own snapshot stack (see commitUndoSnapshot /
      // performUndo): each dispatches an `input` event, which schedules
      // a snapshot, so Cmd+Z reverts them like any other edit.

      // Non-collapsed selection (multi-character drag) + delete: when
      // the range spans across one or more <template data-section-
      // anchor> elements, the native delete will quietly eat those
      // along with the visible text — re-attributing every following
      // block to a different section. Save the templates, run the
      // delete, then re-insert them in their original DOM order at
      // the collapse point. They stay invisible (templates always
      // are) but the section structure survives.
      if (
        (t === "deleteContentBackward" || t === "deleteContentForward")
      ) {
        const selRange = window.getSelection();
        if (
          selRange &&
          selRange.rangeCount > 0 &&
          !selRange.isCollapsed
        ) {
          const r0 = selRange.getRangeAt(0);
          const templates: Element[] = [];
          const walker = document.createTreeWalker(
            r0.commonAncestorContainer,
            NodeFilter.SHOW_ELEMENT,
            {
              acceptNode(node) {
                const el = node as Element;
                if (
                  el.tagName === "TEMPLATE" &&
                  el.hasAttribute("data-section-anchor") &&
                  r0.intersectsNode(el)
                ) {
                  return NodeFilter.FILTER_ACCEPT;
                }
                return NodeFilter.FILTER_SKIP;
              },
            },
          );
          let n: Node | null;
          while ((n = walker.nextNode())) templates.push(n as Element);
          if (templates.length > 0) {
            e.preventDefault();
            r0.deleteContents();
            // The range collapses post-delete. Re-insert each saved
            // template at the collapsed point, in DOM order.
            const insertAt = r0.startContainer;
            const insertOffset = r0.startOffset;
            // Wrap the insertion in a single fragment so the cursor
            // stays at the same logical spot.
            const frag = document.createDocumentFragment();
            for (const tpl of templates) frag.appendChild(tpl);
            if (insertAt.nodeType === Node.TEXT_NODE) {
              const txt = insertAt as Text;
              const parent = txt.parentNode;
              if (parent) {
                if (insertOffset >= (txt.textContent ?? "").length) {
                  parent.insertBefore(frag, txt.nextSibling);
                } else if (insertOffset <= 0) {
                  parent.insertBefore(frag, txt);
                } else {
                  const tail = txt.splitText(insertOffset);
                  parent.insertBefore(frag, tail);
                }
              }
            } else {
              const parent = insertAt as Element;
              const refNode = parent.childNodes[insertOffset] ?? null;
              parent.insertBefore(frag, refNode);
            }
            content.dispatchEvent(
              new InputEvent("input", {
                bubbles: true,
                inputType: t,
              }),
            );
            return;
          }
        }
      }

      if (t === "deleteContentBackward") {
        const sel0 = window.getSelection();
        if (sel0 && sel0.rangeCount > 0 && sel0.isCollapsed) {
          const r = sel0.getRangeAt(0);
          const currentBlock = findBlockAncestor(r.startContainer, content);
          if (currentBlock && isAtStartOfBlock(r, currentBlock)) {
            const prevBlock = previousBlockSibling(currentBlock);
            if (prevBlock) {
              // A manual page break is atomic. Backspacing at the start
              // of the line AFTER a break removes the break (content
              // reflows up) instead of merging the line's content into
              // the inert break div — the old behaviour trapped the
              // caret inside the break div and left the break in place
              // ("can't backspace a page break"). See BUGS_AND_FIXES.
              if (isPageBreak(prevBlock)) {
                e.preventDefault();
                prevBlock.remove();
                content.dispatchEvent(
                  new InputEvent("input", {
                    bubbles: true,
                    inputType: "deleteContentBackward",
                  }),
                );
                // Caret stays at the start of the current line.
                placeCaretAtTextOffset(currentBlock, 0);
                return;
              }
              // Cross-section merge is handled by the same controlled
              // path as a within-section merge: we move the current
              // block's children into the previous block (which keeps
              // its own data-section-id) and leave the <template
              // data-section-anchor> in place, so splitBySection still
              // routes everything to the right section on round-trip.
              // The historical no-op here was a TipTap-era workaround:
              // back then the editor was *controlled* and re-seeded its
              // DOM from the html prop on every host re-render, so a
              // cross-section edit triggered a content swap that killed
              // the caret. The current engine is uncontrolled after
              // mount, so no rebuild happens and the caret survives via
              // placeCaretAtTextOffset (see BUGS_AND_FIXES).
              e.preventDefault();
              // Drop the previous block's placeholder <br> so the
              // merged content doesn't sit below a blank line.
              if (
                prevBlock.childNodes.length === 1 &&
                prevBlock.firstChild?.nodeName === "BR"
              ) {
                prevBlock.removeChild(prevBlock.firstChild);
              }
              // Drop the CURRENT block's trailing placeholder <br>
              // too — otherwise deleting an empty line (Enter then
              // Backspace) appends a stray <br> into the previous
              // block and the caret renders on a new line below.
              stripTrailingBr(currentBlock);
              // The join point is where prevBlock's existing text
              // ends — that's where the caret must land so typing
              // continues from the seam, not the end of the merged
              // content. Captured as a CHARACTER offset (stable across
              // the normalize() + reflow that the input event triggers).
              const joinOffset = (prevBlock.textContent ?? "").length;
              while (currentBlock.firstChild) {
                prevBlock.appendChild(currentBlock.firstChild);
              }
              currentBlock.remove();
              // If the merge left the previous block empty (deleting
              // an empty line that followed an empty line), re-seed a
              // <br> so it remains a valid, focusable editable line.
              if (prevBlock.childNodes.length === 0) {
                prevBlock.appendChild(document.createElement("br"));
              }
              content.dispatchEvent(
                new InputEvent("input", {
                  bubbles: true,
                  inputType: "deleteContentBackward",
                }),
              );
              // Restore the caret AFTER reflow so it sits at the seam.
              placeCaretAtTextOffset(prevBlock, joinOffset);
              return;
            }
          }
        }
      }

      // Symmetric: forward Delete at the very end of a block. Native
      // handler would walk past <template> anchors to find a next
      // block to merge with, often deleting the anchor along the
      // way. Our controlled merge appends the next block's children
      // into the current block, removes the next block, leaves the
      // section template(s) untouched.
      if (t === "deleteContentForward") {
        const sel0 = window.getSelection();
        if (sel0 && sel0.rangeCount > 0 && sel0.isCollapsed) {
          const r = sel0.getRangeAt(0);
          const currentBlock = findBlockAncestor(r.startContainer, content);
          if (currentBlock && isAtEndOfBlock(r, currentBlock)) {
            const nextBlock = nextBlockSibling(currentBlock);
            if (nextBlock) {
              // Symmetric page-break handling: forward-Delete at the end
              // of the line BEFORE a break removes the break rather than
              // pulling the break div's (empty) content into the line.
              if (isPageBreak(nextBlock)) {
                e.preventDefault();
                nextBlock.remove();
                content.dispatchEvent(
                  new InputEvent("input", {
                    bubbles: true,
                    inputType: "deleteContentForward",
                  }),
                );
                placeCaretAtTextOffset(
                  currentBlock,
                  (currentBlock.textContent ?? "").length,
                );
                return;
              }
              // Cross-section forward-Delete is allowed for the same
              // reason as cross-section Backspace (see the Backspace
              // path above): the controlled merge re-attributes the
              // next block's content into the current block's section
              // and the uncontrolled engine keeps the caret put.
              e.preventDefault();
              // Strip the current block's trailing placeholder <br>
              // so the merged content doesn't sit below a blank line.
              stripTrailingBr(currentBlock);
              // Strip the next block's trailing <br> too so an empty
              // next line collapses cleanly.
              stripTrailingBr(nextBlock);
              // Join point = end of currentBlock's existing text. The
              // caret must stay there (Delete doesn't move the caret),
              // captured as a stable character offset.
              const joinOffset = (currentBlock.textContent ?? "").length;
              while (nextBlock.firstChild) {
                currentBlock.appendChild(nextBlock.firstChild);
              }
              // If the merge left the current block empty, re-seed a
              // <br> so it stays a valid editable line.
              if (currentBlock.childNodes.length === 0) {
                currentBlock.appendChild(document.createElement("br"));
              }
              nextBlock.remove();
              content.dispatchEvent(
                new InputEvent("input", {
                  bubbles: true,
                  inputType: "deleteContentForward",
                }),
              );
              // Restore caret at the seam AFTER reflow.
              placeCaretAtTextOffset(currentBlock, joinOffset);
              return;
            }
          }
        }
      }

      // "Empty" = first page has only the placeholder OR is whitespace.
      const ps = getPages();
      if (ps.length !== 1) return;
      const text = ps[0].textContent ?? "";
      const html = ps[0].innerHTML.trim();
      const isEmpty =
        text.trim().length === 0 &&
        (html === "" ||
          html === "<br>" ||
          html === "<div><br></div>" ||
          html === "<p><br></p>");
      if (isEmpty) {
        e.preventDefault();
      }
    };
    content.addEventListener("beforeinput", onBeforeInput as EventListener);

    return () => {
      content.removeEventListener("input", onInput as EventListener);
      content.removeEventListener("paste", onPaste as EventListener);
      content.removeEventListener(
        "beforeinput",
        onBeforeInput as EventListener,
      );
      content.removeEventListener("keydown", onUndoRedoKey);
      if (undoTimerRef.current !== null) {
        window.clearTimeout(undoTimerRef.current);
      }
      if (emitChangeTimerRef.current !== null) {
        window.clearTimeout(emitChangeTimerRef.current);
      }
      cancelDeferredSettle();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Inline image select + drag-to-resize. Native contentEditable
  // image resize handles are inconsistent (Firefox only via the
  // deprecated execCommand("enableObjectResizing"), Chromium/WebKit
  // nothing). We render our own: click an <img> to "select" it, a
  // single SE-corner handle appears, drag it to resize. Aspect ratio
  // is preserved. The image's width/height attributes get updated so
  // the size persists through serialization.
  useEffect(() => {
    const content = contentRef.current;
    if (!content) return;
    let selectedImg: HTMLImageElement | null = null;
    let handle: HTMLDivElement | null = null;
    let dragState: {
      startX: number;
      startW: number;
      startH: number;
      aspect: number;
    } | null = null;

    const deselect = () => {
      if (selectedImg) {
        selectedImg.removeAttribute("data-pagedly-selected");
        selectedImg = null;
      }
      if (handle) {
        handle.remove();
        handle = null;
      }
    };

    const positionHandle = () => {
      if (!selectedImg || !handle) return;
      const rect = selectedImg.getBoundingClientRect();
      const parentRect = content.getBoundingClientRect();
      handle.style.left = `${rect.right - parentRect.left - 8}px`;
      handle.style.top = `${rect.bottom - parentRect.top - 8}px`;
    };

    const onClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === "IMG") {
        deselect();
        selectedImg = target as HTMLImageElement;
        selectedImg.setAttribute("data-pagedly-selected", "true");
        handle = document.createElement("div");
        handle.className = "pagedly-img-handle";
        handle.setAttribute("contenteditable", "false");
        handle.setAttribute("aria-hidden", "true");
        content.appendChild(handle);
        positionHandle();
      } else if (selectedImg && !target.classList?.contains("pagedly-img-handle")) {
        deselect();
      }
    };

    const onScroll = () => {
      if (selectedImg && handle) positionHandle();
    };

    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as HTMLElement;
      if (!handle || target !== handle || !selectedImg) return;
      e.preventDefault();
      e.stopPropagation();
      const w = selectedImg.getBoundingClientRect().width;
      const h = selectedImg.getBoundingClientRect().height;
      dragState = {
        startX: e.clientX,
        startW: w,
        startH: h,
        aspect: h > 0 ? w / h : 1,
      };
      handle.setPointerCapture(e.pointerId);
    };

    const onPointerMove = (e: PointerEvent) => {
      if (!dragState || !selectedImg) return;
      const dx = e.clientX - dragState.startX;
      const newW = Math.max(40, dragState.startW + dx);
      const newH = Math.max(40, newW / dragState.aspect);
      selectedImg.style.width = `${Math.round(newW)}px`;
      selectedImg.style.height = `${Math.round(newH)}px`;
      selectedImg.setAttribute("width", String(Math.round(newW)));
      selectedImg.setAttribute("height", String(Math.round(newH)));
      positionHandle();
    };

    const onPointerUp = (e: PointerEvent) => {
      if (!dragState) return;
      dragState = null;
      handle?.releasePointerCapture(e.pointerId);
      // Fire input so onChange + pagination re-run with the new size.
      content.dispatchEvent(
        new InputEvent("input", { bubbles: true, inputType: "insertReplacementText" }),
      );
    };

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && selectedImg) {
        deselect();
      } else if ((e.key === "Backspace" || e.key === "Delete") && selectedImg) {
        e.preventDefault();
        const toRemove = selectedImg;
        deselect();
        toRemove.remove();
        content.dispatchEvent(
          new InputEvent("input", { bubbles: true, inputType: "deleteContent" }),
        );
      }
    };

    content.addEventListener("click", onClick);
    content.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("scroll", onScroll, true);
    content.addEventListener("keydown", onKey);
    return () => {
      deselect();
      content.removeEventListener("click", onClick);
      content.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("scroll", onScroll, true);
      content.removeEventListener("keydown", onKey);
    };
  }, []);

  // Table column + row resize. Hovering near a cell's right edge
  // shows a col-resize cursor; dragging moves the boundary between
  // that column and its neighbour (the dragged column grows, the
  // next shrinks — Word/Excel behaviour). Near a cell's bottom edge
  // gives row-resize, dragging sets the row's height. Relies on the
  // table being table-layout: fixed so per-cell widths are stable.
  useEffect(() => {
    const content = contentRef.current;
    if (!content) return;
    const EDGE = 6; // px hit-zone around a border

    type ColDrag = {
      kind: "col";
      table: HTMLTableElement;
      colIndex: number;
      startX: number;
      startW: number;
      startNextW: number;
    };
    type RowDrag = {
      kind: "row";
      row: HTMLTableRowElement;
      startY: number;
      startH: number;
    };
    let drag: ColDrag | RowDrag | null = null;

    // Set an explicit width on every cell in a column so table-layout:
    // fixed honours it across all rows.
    const setColumnWidth = (table: HTMLTableElement, colIndex: number, w: number) => {
      for (const row of Array.from(table.rows)) {
        const cell = row.cells[colIndex];
        if (cell) cell.style.width = `${Math.round(w)}px`;
      }
    };

    // Which border (if any) is the pointer near? A pointer sitting on
    // a column border usually hit-tests to the cell on its RIGHT, so
    // we resolve a near-left-edge hit to the previous cell's right
    // border. Returns the cell whose RIGHT (or BOTTOM) border is being
    // dragged.
    const hitTest = (
      e: PointerEvent,
    ): { cell: HTMLTableCellElement; edge: "right" | "bottom" } | null => {
      const target = (e.target as HTMLElement)?.closest?.("td, th") as
        | HTMLTableCellElement
        | null;
      if (!target || !content.contains(target)) return null;
      const rect = target.getBoundingClientRect();
      const row = target.parentElement as HTMLTableRowElement;
      // Near this cell's right edge → drag this column's right border.
      if (Math.abs(e.clientX - rect.right) <= EDGE) {
        return { cell: target, edge: "right" };
      }
      // Near this cell's left edge → that's the previous column's
      // right border. Resolve to the previous cell.
      if (Math.abs(e.clientX - rect.left) <= EDGE && target.cellIndex > 0) {
        const prev = row.cells[target.cellIndex - 1];
        if (prev) return { cell: prev, edge: "right" };
      }
      // Near this cell's bottom edge → drag this row's bottom border.
      if (Math.abs(e.clientY - rect.bottom) <= EDGE) {
        return { cell: target, edge: "bottom" };
      }
      // Near this cell's top edge → previous row's bottom border.
      if (Math.abs(e.clientY - rect.top) <= EDGE) {
        const prevRow = row.previousElementSibling as HTMLTableRowElement | null;
        const prevCell = prevRow?.cells[target.cellIndex];
        if (prevCell) return { cell: prevCell, edge: "bottom" };
      }
      return null;
    };

    const onMove = (e: PointerEvent) => {
      if (drag) {
        if (drag.kind === "col") {
          const dx = e.clientX - drag.startX;
          const newW = Math.max(30, drag.startW + dx);
          const newNext = Math.max(30, drag.startNextW - dx);
          setColumnWidth(drag.table, drag.colIndex, newW);
          setColumnWidth(drag.table, drag.colIndex + 1, newNext);
        } else {
          const dy = e.clientY - drag.startY;
          drag.row.style.height = `${Math.max(20, Math.round(drag.startH + dy))}px`;
        }
        return;
      }
      // Hover cursor feedback.
      const hit = hitTest(e);
      if (!hit) {
        content.style.cursor = "";
        return;
      }
      if (hit.edge === "right") {
        // Only show col-resize if there's a next column to trade with.
        const row = hit.cell.parentElement as HTMLTableRowElement;
        content.style.cursor =
          hit.cell.cellIndex < row.cells.length - 1 ? "col-resize" : "";
      } else {
        content.style.cursor = "row-resize";
      }
    };

    const onDown = (e: PointerEvent) => {
      const hit = hitTest(e);
      if (!hit) return;
      const cell = hit.cell;
      const row = cell.parentElement as HTMLTableRowElement;
      const table = cell.closest("table") as HTMLTableElement | null;
      if (!table) return;
      if (hit.edge === "right") {
        const colIndex = cell.cellIndex;
        if (colIndex >= row.cells.length - 1) return; // last col: nothing to trade
        const nextCell = row.cells[colIndex + 1];
        e.preventDefault();
        drag = {
          kind: "col",
          table,
          colIndex,
          startX: e.clientX,
          startW: cell.getBoundingClientRect().width,
          startNextW: nextCell.getBoundingClientRect().width,
        };
      } else {
        e.preventDefault();
        drag = {
          kind: "row",
          row,
          startY: e.clientY,
          startH: row.getBoundingClientRect().height,
        };
      }
      content.setPointerCapture?.(e.pointerId);
    };

    const onUp = (e: PointerEvent) => {
      if (!drag) return;
      drag = null;
      content.releasePointerCapture?.(e.pointerId);
      content.style.cursor = "";
      content.dispatchEvent(
        new InputEvent("input", { bubbles: true, inputType: "insertReplacementText" }),
      );
    };

    content.addEventListener("pointermove", onMove);
    content.addEventListener("pointerdown", onDown);
    window.addEventListener("pointerup", onUp);
    return () => {
      content.removeEventListener("pointermove", onMove);
      content.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointerup", onUp);
    };
  }, []);

  useImperativeHandle(
    ref,
    () => ({
      getHTML(): string {
        // Synchronous, always current — strips the inert decorations
        // (chrome / page numbers, repeated table headers) so save/flush
        // paths get the exact source regardless of the onChange debounce.
        return serializeForSource();
      },
      getContentEl(): HTMLElement | null {
        return contentRef.current;
      },
      setHTML(newHtml: string): void {
        const content = contentRef.current;
        if (!content) return;
        content.innerHTML = "";
        const firstPage = document.createElement("div");
        content.appendChild(firstPage);
        applyPageStyle(firstPage);
        firstPage.innerHTML = newHtml || "<div><br></div>";
        // Strip→fit→stamp protocol — without the stamp, page numbers / running
        // heads / repeated theads would be missing until the first edit.
        reflowWithChrome();
      },
      focus(): void {
        const content = contentRef.current;
        if (!content) return;
        // contentEditable focus also requires a selection in the
        // editable area for the cursor to show up immediately.
        content.focus({ preventScroll: true });
        if (!window.getSelection()?.rangeCount) {
          const range = document.createRange();
          range.selectNodeContents(content);
          range.collapse(true);
          const sel = window.getSelection();
          sel?.removeAllRanges();
          sel?.addRange(range);
        }
      },
      execCommand(command: string, value?: string): boolean {
        const content = contentRef.current;
        if (!content) return false;
        // Ensure the editable area has focus so the command applies
        // to its selection — without this, hosts that call this from
        // a toolbar button (which steals focus) get a no-op.
        if (document.activeElement !== content) {
          content.focus({ preventScroll: true });
        }
        try {
          return document.execCommand(command, false, value);
        } catch {
          return false;
        }
      },
      reflow(): void {
        // Strip→fit→stamp: a bare fitContentOverPages() would measure the inert
        // chrome (footers, repeated theads) as content and shift boundaries.
        reflowWithChrome();
      },
      undo(): void {
        performUndo();
      },
      redo(): void {
        performRedo();
      },
      canUndo(): boolean {
        // performUndo needs the current snapshot PLUS a prior one to
        // restore, so a stack of ≥2 means undo is available. A pending
        // (debounced) edit also counts — performUndo flushes it first.
        return undoStackRef.current.length >= 2 || pendingEditRef.current;
      },
      canRedo(): boolean {
        return redoStackRef.current.length > 0;
      },
      getBlocks() {
        return ensureParaIds().map((b) => ({
          pid: b.getAttribute("data-pid") ?? "",
          tag: b.tagName.toLowerCase(),
          text: (b.textContent ?? "").replace(/​/g, "").trim(),
        }));
      },
      replaceBlock(pid: string, html: string): boolean {
        const content = contentRef.current;
        if (!content) return false;
        const block = content.querySelector<HTMLElement>(`[data-pid="${pid}"]`);
        if (!block) return false;
        block.innerHTML = html;
        block.dispatchEvent(
          new InputEvent("input", { bubbles: true, inputType: "insertReplacementText" }),
        );
        return true;
      },
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  const wrapperStyle: CSSProperties = {
    background: "var(--pagedly-desk-background, #e8eaed)",
    padding: "40px 0 56px",
    minHeight: "100vh",
    overflowAnchor: "none",
  };

  return (
    <div ref={rootRef} className="pagedly-ce-editor" style={wrapperStyle}>
      <div
        ref={contentRef}
        className="pagedly-ce-content"
        contentEditable={!readOnly}
        suppressContentEditableWarning
        role="textbox"
        aria-multiline="true"
        aria-readonly={readOnly || undefined}
        style={{ outline: "none", overflowAnchor: "none" }}
      />
    </div>
  );
});
