// HTML <-> Markdown converters. Boundary-only (no engine/pagination contact):
// htmlToMarkdown serializes the editor's HTML for export / copy-as-markdown;
// markdownToHtml parses Markdown for import. Hand-rolled, dependency-free, and
// scoped to the constructs the editor actually produces.
import { safeUrl } from "./sanitize";

// ── HTML -> Markdown ──────────────────────────────────────────────

const INLINE_WRAP: Record<string, string> = {
  STRONG: "**",
  B: "**",
  EM: "_",
  I: "_",
  S: "~~",
  STRIKE: "~~",
  DEL: "~~",
};

function inlineToMd(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) {
    return (node.nodeValue ?? "").replace(/​/g, "");
  }
  if (node.nodeType !== Node.ELEMENT_NODE) return "";
  const el = node as HTMLElement;
  const tag = el.tagName;
  const inner = Array.from(el.childNodes).map(inlineToMd).join("");
  if (tag === "BR") return "\n";
  if (tag === "CODE") return `\`${el.textContent ?? ""}\``;
  if (tag === "A") {
    const href = el.getAttribute("href") ?? "";
    return `[${inner}](${href})`;
  }
  if (tag === "IMG") {
    const src = el.getAttribute("src") ?? "";
    const alt = el.getAttribute("alt") ?? "";
    return `![${alt}](${src})`;
  }
  const wrap = INLINE_WRAP[tag];
  if (wrap) {
    if (!inner.trim()) return inner;
    return `${wrap}${inner}${wrap}`;
  }
  return inner;
}

function listToMd(list: HTMLElement, depth: number): string {
  const ordered = list.tagName === "OL";
  const checklist = list.classList.contains("pagedly-checklist");
  const indent = "  ".repeat(depth);
  const lines: string[] = [];
  let i = 1;
  for (const li of Array.from(list.children)) {
    if (li.tagName !== "LI") continue;
    // Split nested lists out of the item content.
    const nested = Array.from(li.children).filter(
      (c) => c.tagName === "UL" || c.tagName === "OL",
    ) as HTMLElement[];
    const contentNodes = Array.from(li.childNodes).filter(
      (c) => !(c.nodeType === Node.ELEMENT_NODE && ((c as Element).tagName === "UL" || (c as Element).tagName === "OL")),
    );
    const text = contentNodes.map(inlineToMd).join("").trim();
    let marker: string;
    if (checklist) {
      const checked = (li as HTMLElement).getAttribute("data-checked") === "true";
      marker = `- [${checked ? "x" : " "}]`;
    } else if (ordered) {
      marker = `${i}.`;
    } else {
      marker = "-";
    }
    lines.push(`${indent}${marker} ${text}`);
    for (const n of nested) lines.push(listToMd(n, depth + 1));
    i += 1;
  }
  return lines.join("\n");
}

function tableToMd(table: HTMLElement): string {
  const rows = Array.from(table.querySelectorAll("tr"));
  if (rows.length === 0) return "";
  const cellText = (r: Element) =>
    Array.from(r.querySelectorAll("th,td")).map((c) =>
      Array.from(c.childNodes).map(inlineToMd).join("").trim().replace(/\|/g, "\\|"),
    );
  const header = cellText(rows[0]);
  const lines = [
    `| ${header.join(" | ")} |`,
    `| ${header.map(() => "---").join(" | ")} |`,
  ];
  for (const r of rows.slice(1)) {
    const cells = cellText(r);
    lines.push(`| ${cells.join(" | ")} |`);
  }
  return lines.join("\n");
}

// A generated TOC serializes as the title + one line per entry. Flattening it as
// a plain DIV concatenates every entry + page number into one run-on
// ("ContentsIntroduction3Methods7"). Page numbers are dropped — markdown has no
// pages.
function tocToMd(toc: HTMLElement): string {
  const lines: string[] = [];
  const title = toc.querySelector(".pagedly-toc__title")?.textContent?.trim();
  if (title) lines.push(`**${title}**`, "");
  for (const entry of Array.from(toc.querySelectorAll(".pagedly-toc__entry"))) {
    const text = (entry.querySelector(".pagedly-toc__text")?.textContent ?? "").trim();
    if (text) lines.push(`- ${text}`);
  }
  return lines.join("\n");
}

function blockToMd(el: HTMLElement): string {
  const tag = el.tagName;
  if (/^H[1-6]$/.test(tag)) {
    const level = Number(tag[1]);
    return `${"#".repeat(level)} ${Array.from(el.childNodes).map(inlineToMd).join("").trim()}`;
  }
  if (tag === "DIV" && el.classList.contains("pagedly-toc")) {
    return tocToMd(el);
  }
  if (tag === "P" || tag === "DIV") {
    return Array.from(el.childNodes).map(inlineToMd).join("").trim();
  }
  if (tag === "UL" || tag === "OL") return listToMd(el, 0);
  if (tag === "BLOCKQUOTE") {
    const inner = Array.from(el.childNodes)
      .map((c) => (c.nodeType === Node.ELEMENT_NODE ? blockToMd(c as HTMLElement) : inlineToMd(c)))
      .join("\n")
      .trim();
    return inner
      .split("\n")
      .map((l) => `> ${l}`)
      .join("\n");
  }
  if (tag === "PRE") {
    return "```\n" + (el.textContent ?? "").replace(/\n$/, "") + "\n```";
  }
  if (tag === "HR") return "---";
  if (tag === "FIGURE") {
    const img = el.querySelector("img");
    const cap = el.querySelector("figcaption");
    const imgMd = img ? inlineToMd(img) : "";
    return cap ? `${imgMd}\n*${cap.textContent ?? ""}*` : imgMd;
  }
  if (tag === "TABLE") return tableToMd(el);
  if (tag === "IMG") return inlineToMd(el);
  // Fallback: treat as a paragraph.
  return Array.from(el.childNodes).map(inlineToMd).join("").trim();
}

/** Convert editor HTML to Markdown. Requires a DOM (browser or jsdom). */
export function htmlToMarkdown(html: string): string {
  const container = document.createElement("div");
  container.innerHTML = html;
  const blocks: string[] = [];
  for (const node of Array.from(container.childNodes)) {
    if (node.nodeType === Node.TEXT_NODE) {
      const t = (node.nodeValue ?? "").trim();
      if (t) blocks.push(t);
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      const md = blockToMd(node as HTMLElement);
      if (md.trim()) blocks.push(md);
    }
  }
  return blocks.join("\n\n").replace(/\n{3,}/g, "\n\n").trim() + "\n";
}

// ── Markdown -> HTML ──────────────────────────────────────────────

const escapeHtml = (s: string): string =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

/** Inline Markdown -> HTML (code, bold, italic, strikethrough, links, images). */
function inlineMdToHtml(text: string): string {
  // Protect inline code spans first.
  const codes: string[] = [];
  let s = text.replace(/`([^`]+)`/g, (_m, c) => {
    codes.push(`<code>${escapeHtml(c)}</code>`);
    return `�${codes.length - 1}�`;
  });
  s = escapeHtml(s);
  // Images before links. URLs go through safeUrl (scheme allow-list + attribute
  // escaping) so `[x](javascript:…)` / `![x](u" onerror=…)` can't inject — the
  // raw `${src}`/`${href}` interpolation here bypasses DOMPurify's URI check.
  // alt is already entity-escaped by escapeHtml above EXCEPT the double-quote,
  // which would still break out of alt="…".
  s = s.replace(
    /!\[([^\]]*)\]\(([^)]+)\)/g,
    (_m, alt, src) => `<img src="${safeUrl(src)}" alt="${alt.replace(/"/g, "&quot;")}" />`,
  );
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t, href) => `<a href="${safeUrl(href)}">${t}</a>`);
  s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  s = s.replace(/~~([^~]+)~~/g, "<s>$1</s>");
  s = s.replace(/(?:^|(?<=\s))_([^_]+)_(?=\s|$)/g, "<em>$1</em>");
  s = s.replace(/(?:^|(?<=[^*]))\*([^*]+)\*/g, "<em>$1</em>");
  // Restore code spans.
  s = s.replace(/�(\d+)�/g, (_m, i) => codes[Number(i)]);
  return s;
}

/** Convert Markdown to editor-compatible HTML. */
export function markdownToHtml(md: string): string {
  const lines = md.replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;
  let listType: "ul" | "ol" | null = null;
  let checklist = false;
  const closeList = () => {
    if (listType) {
      out.push(checklist ? "</ul>" : `</${listType}>`);
      listType = null;
      checklist = false;
    }
  };
  while (i < lines.length) {
    const line = lines[i];
    // Code fence
    if (/^```/.test(line)) {
      closeList();
      const body: string[] = [];
      i += 1;
      while (i < lines.length && !/^```/.test(lines[i])) {
        body.push(lines[i]);
        i += 1;
      }
      i += 1; // skip closing fence
      out.push(`<pre><code>${escapeHtml(body.join("\n"))}</code></pre>`);
      continue;
    }
    // Horizontal rule
    if (/^\s*(?:---|\*\*\*|___)\s*$/.test(line)) {
      closeList();
      out.push("<hr />");
      i += 1;
      continue;
    }
    // Heading
    const h = /^(#{1,6})\s+(.*)$/.exec(line);
    if (h) {
      closeList();
      out.push(`<h${h[1].length}>${inlineMdToHtml(h[2].trim())}</h${h[1].length}>`);
      i += 1;
      continue;
    }
    // Blockquote (collect consecutive)
    if (/^>\s?/.test(line)) {
      closeList();
      const body: string[] = [];
      while (i < lines.length && /^>\s?/.test(lines[i])) {
        body.push(lines[i].replace(/^>\s?/, ""));
        i += 1;
      }
      out.push(`<blockquote>${inlineMdToHtml(body.join(" "))}</blockquote>`);
      continue;
    }
    // Checklist
    const cl = /^\s*[-*+]\s+\[([ xX])\]\s+(.*)$/.exec(line);
    if (cl) {
      if (!checklist) {
        closeList();
        out.push('<ul class="pagedly-checklist">');
        listType = "ul";
        checklist = true;
      }
      const checked = cl[1].toLowerCase() === "x";
      out.push(`<li data-checked="${checked}">${inlineMdToHtml(cl[2].trim())}</li>`);
      i += 1;
      continue;
    }
    // Bullet list
    const ul = /^\s*[-*+]\s+(.*)$/.exec(line);
    if (ul) {
      if (listType !== "ul" || checklist) {
        closeList();
        out.push("<ul>");
        listType = "ul";
      }
      out.push(`<li>${inlineMdToHtml(ul[1].trim())}</li>`);
      i += 1;
      continue;
    }
    // Ordered list
    const ol = /^\s*\d+[.)]\s+(.*)$/.exec(line);
    if (ol) {
      if (listType !== "ol") {
        closeList();
        out.push("<ol>");
        listType = "ol";
      }
      out.push(`<li>${inlineMdToHtml(ol[1].trim())}</li>`);
      i += 1;
      continue;
    }
    // Blank line
    if (line.trim() === "") {
      closeList();
      i += 1;
      continue;
    }
    // Paragraph
    closeList();
    out.push(`<p>${inlineMdToHtml(line.trim())}</p>`);
    i += 1;
  }
  closeList();
  return out.join("");
}
