// List nesting (Tab / Shift-Tab) — pure DOM surgery on <ul>/<ol> structures.
// A nested list is just a <ul>/<ol> appended inside the preceding <li>. These
// helpers keep the moved <li> node identity (so the caret inside it survives)
// and leave numbering/marker styling to CSS counters.

/** Find the nearest <li> ancestor of a node, within the editor root. */
export function findListItem(node: Node | null, root?: Element): HTMLLIElement | null {
  let n: Node | null = node;
  while (n && n !== root) {
    if (n.nodeType === Node.ELEMENT_NODE && (n as Element).tagName === "LI") {
      return n as HTMLLIElement;
    }
    n = n.parentNode;
  }
  return null;
}

/**
 * Nest a list item one level deeper. Moves it into a sub-list of its previous
 * sibling <li> (reusing an existing trailing sub-list of the same type, or
 * creating one). Returns the moved <li>, or null if it can't nest (no previous
 * sibling item).
 */
export function indentListItem(li: HTMLLIElement): HTMLLIElement | null {
  const parentList = li.parentElement;
  if (!parentList || (parentList.tagName !== "UL" && parentList.tagName !== "OL")) {
    return null;
  }
  const prev = li.previousElementSibling;
  if (!prev || prev.tagName !== "LI") return null; // can't nest the first item

  const listTag = parentList.tagName.toLowerCase();
  // Reuse a trailing sub-list on the previous item, else make one of the same
  // type (inherit the checklist class so checkbox styling carries down).
  let sublist = prev.lastElementChild;
  if (!sublist || (sublist.tagName !== "UL" && sublist.tagName !== "OL")) {
    sublist = document.createElement(listTag);
    if (parentList.classList.contains("pagedly-checklist")) {
      sublist.classList.add("pagedly-checklist");
    }
    const sid = parentList.getAttribute("data-section-id");
    if (sid) sublist.setAttribute("data-section-id", sid);
    prev.appendChild(sublist);
  }
  sublist.appendChild(li);
  return li;
}

/**
 * Outdent a nested list item one level. Moves it to be the next sibling of its
 * grandparent <li> in the outer list; trailing siblings follow it into a
 * sub-list so ordering is preserved. Returns the moved <li>, or null if it's
 * already at the top level.
 */
export function outdentListItem(li: HTMLLIElement): HTMLLIElement | null {
  const innerList = li.parentElement;
  if (!innerList || (innerList.tagName !== "UL" && innerList.tagName !== "OL")) {
    return null;
  }
  const parentLi = innerList.parentElement;
  if (!parentLi || parentLi.tagName !== "LI") return null; // top level already
  const outerList = parentLi.parentElement;
  if (!outerList) return null;

  // Any siblings after `li` in the inner list should remain nested under `li`.
  const following: Element[] = [];
  let sib = li.nextElementSibling;
  while (sib) {
    following.push(sib);
    sib = sib.nextElementSibling;
  }
  if (following.length > 0) {
    let tail = li.lastElementChild;
    if (!tail || (tail.tagName !== "UL" && tail.tagName !== "OL")) {
      tail = document.createElement(innerList.tagName.toLowerCase());
      if (innerList.classList.contains("pagedly-checklist")) {
        tail.classList.add("pagedly-checklist");
      }
      li.appendChild(tail);
    }
    for (const f of following) tail.appendChild(f);
  }

  // Move li to just after parentLi in the outer list.
  outerList.insertBefore(li, parentLi.nextSibling);

  // If the inner list is now empty, drop it.
  if (innerList.children.length === 0) innerList.remove();
  return li;
}
