type RebuildBlockItem = {
  kind: "block";
  ref: string;
  first: HTMLElement;
  innerParts: string[];
};

type RebuildAnchorItem = {
  kind: "anchor";
  sectionId: string;
  outerHTML: string;
};

type RebuildItem = RebuildBlockItem | RebuildAnchorItem;

export type SourceTransformOptions = {
  readOnlyChromeSelector?: string;
  editableRootSelector?: string;
};

const EDITABLE_ROOT_REF_ATTR = "data-pagedly-editable-root-ref";

export function stampPagedRefs(html: string, options: SourceTransformOptions = {}): string {
  const doc = new DOMParser().parseFromString(`<div>${html}</div>`, "text/html");
  const root = doc.body.firstElementChild as HTMLElement | null;
  if (!root) return html;

  wrapLooseTopLevelContent(root);
  // Strip section anchors from every editable root BEFORE paged.js sees them,
  // and migrate their section IDs onto the next real block. paged.js otherwise
  // tries to lay out the (invisible) anchor and can emit blank or duplicated
  // first pages. (HRLETTER fix, paged-edit/Editor.tsx:1117-1128.)
  stripSectionAnchorsAndMigrateSectionIds(root, options.editableRootSelector);
  stampEditableRootRefs(root, options.editableRootSelector);
  let index = 0;
  for (const child of Array.from(root.children) as HTMLElement[]) {
    child.setAttribute("data-pagedly-ref", String(index));
    if (matchesReadOnlyChrome(child, options.readOnlyChromeSelector)) {
      child.setAttribute("data-pagedly-readonly-source", "true");
    }
    for (const chrome of queryReadOnlyChrome(child, options.readOnlyChromeSelector)) {
      chrome.setAttribute("data-pagedly-readonly-source", "true");
    }
    index++;
  }
  return root.innerHTML;
}

function stripSectionAnchorsAndMigrateSectionIds(root: HTMLElement, editableRootSelector?: string): void {
  // Anchors live as direct children of editable roots (e.g. .letter-body).
  // If the host uses the body-only source convention (chrome added via
  // wrapSourceForRender), there is no editable-root wrapper in the source —
  // `root` itself IS the body content. Fall back to that case so anchor
  // stripping still happens.
  let editableRoots: HTMLElement[] = editableRootSelector
    ? safeQueryAll(root, editableRootSelector).filter(
        (el) => !el.parentElement?.closest(editableRootSelector),
      )
    : [];
  if (editableRoots.length === 0) editableRoots = [root];

  for (const editable of editableRoots) {
    let currentSectionId: string | null = null;
    for (const child of Array.from(editable.children) as HTMLElement[]) {
      if (child.hasAttribute("data-section-anchor")) {
        currentSectionId = child.getAttribute("data-section-id");
        child.remove();
        continue;
      }
      if (child.hasAttribute("data-generated-letter-chrome")) continue;
      if (currentSectionId) {
        child.setAttribute("data-section-id", currentSectionId);
      }
    }
  }
}

function safeQueryAll(root: HTMLElement, selector: string): HTMLElement[] {
  try {
    return Array.from(root.querySelectorAll<HTMLElement>(selector));
  } catch {
    return [];
  }
}

export function reconstructSourceHtml(
  container: HTMLElement,
  options: SourceTransformOptions = {},
): string {
  const snapshot = container.cloneNode(true) as HTMLElement;
  normalizeRenderedPagedRefs(snapshot, options);
  const roots = findRenderedSourceRoots(snapshot, options);
  const items: RebuildItem[] = [];
  const blockIndex = new Map<string, number>();
  const seenAnchors = new Set<string>();
  let currentSectionId: string | null = null;

  // Anchors were stripped before paged.js rendered (see stampPagedRefs). When
  // a block's data-section-id flips, emit a synthetic anchor for that section
  // so the source round-trips with the same section structure it went in
  // with. (HRLETTER reconstructSourceHtml, paged-edit/Editor.tsx:1562.)
  const appendAnchor = (sectionId: string | null) => {
    if (!sectionId || seenAnchors.has(sectionId)) return;
    seenAnchors.add(sectionId);
    items.push({ kind: "anchor", sectionId, outerHTML: anchorHtmlFor(sectionId) });
  };

  for (const root of roots) {
    for (const node of Array.from(root.children) as HTMLElement[]) {
      if (node.hasAttribute("data-section-anchor")) {
        // Anchor element survived rendering (rare — usually stripped earlier).
        const id = node.getAttribute("data-section-id") || "";
        currentSectionId = id || currentSectionId;
        appendAnchor(id);
        continue;
      }
      // Letter-specific chrome (e.g. signature image) is re-composed at
      // render time by wrapSourceForRender, so it shouldn't leak back into
      // the editable source. Other readonly chrome — e.g. the generic
      // [data-generated-chrome] convention — still round-trips because it
      // IS part of the source. (HRLETTER reconstructSourceHtml does the same.)
      if (node.hasAttribute("data-generated-letter-chrome")) continue;
      if (!node.hasAttribute("data-pagedly-ref")) continue;

      const ref = reconstructionRefFor(node);
      if (!ref) continue;

      const sectionId = node.getAttribute("data-section-id") || currentSectionId;
      if (sectionId) {
        currentSectionId = sectionId;
        appendAnchor(sectionId);
      }

      if (blockIndex.has(ref)) {
        const existing = items[blockIndex.get(ref)!];
        if (existing.kind === "block") existing.innerParts.push(node.innerHTML);
      } else {
        blockIndex.set(ref, items.length);
        items.push({ kind: "block", ref, first: node, innerParts: [node.innerHTML] });
      }
    }
  }

  return items
    .map((item) => {
      if (item.kind === "anchor") return item.outerHTML;
      const clone = item.first.cloneNode(false) as HTMLElement;
      clone.innerHTML = item.innerParts.join("");
      stripPagedArtifacts(clone);
      clone.removeAttribute("data-pagedly-ref");
      clone.removeAttribute("data-pagedly-readonly-source");
      return clone.outerHTML;
    })
    .join("");
}

function anchorHtmlFor(id: string): string {
  return `<template data-section-anchor data-section-id="${escapeAttr(id)}"></template>`;
}

function escapeAttr(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;");
}

export function normalizeRenderedPagedRefs(
  container: HTMLElement,
  options: SourceTransformOptions = {},
): void {
  const roots = findRenderedSourceRoots(container, options);
  const refMap = new Map<string, string>();
  let nextRef = 0;

  for (const root of roots) {
    wrapLooseTopLevelContent(root);
    for (const child of Array.from(root.children) as HTMLElement[]) {
      const oldRef = child.getAttribute("data-pagedly-ref");
      let next = oldRef ? refMap.get(oldRef) : undefined;
      if (next === undefined) {
        next = String(nextRef++);
        if (oldRef) refMap.set(oldRef, next);
      }
      child.setAttribute("data-pagedly-ref", next);

      if (matchesReadOnlyChrome(child, options.readOnlyChromeSelector)) {
        child.setAttribute("data-pagedly-readonly-source", "true");
      }
      for (const chrome of queryReadOnlyChrome(child, options.readOnlyChromeSelector)) {
        chrome.setAttribute("data-pagedly-readonly-source", "true");
      }
    }
  }
}

export function findRenderedSourceRoots(
  container: HTMLElement,
  options: SourceTransformOptions = {},
): HTMLElement[] {
  const pageContents = container.querySelectorAll<HTMLElement>(".pagedjs_page_content");
  const roots: HTMLElement[] = [];

  // Try the configured editable root selector first (e.g. ".letter-body"
  // when the host wraps the source with chrome at render time). Fall back to
  // ".pagedly-source-root" for the default generic editor.
  const selectors: string[] = [];
  if (options.editableRootSelector && options.editableRootSelector !== ".pagedly-source-root") {
    selectors.push(options.editableRootSelector);
  }
  selectors.push(".pagedly-source-root");

  for (const pageContent of pageContents) {
    let matched = false;
    for (const selector of selectors) {
      const matches = safeQueryAllScoped(pageContent, selector).filter(
        (el) => !el.parentElement?.closest(selector),
      );
      if (matches.length > 0) {
        roots.push(...matches);
        matched = true;
        break;
      }
    }
    if (matched) continue;

    const fallback = pageContent.firstElementChild as HTMLElement | null;
    if (fallback && hasDirectSourceChildren(fallback)) roots.push(fallback);
  }

  return roots;
}

function safeQueryAllScoped(container: HTMLElement, selector: string): HTMLElement[] {
  try {
    return Array.from(container.querySelectorAll<HTMLElement>(selector));
  } catch {
    return [];
  }
}

export function wrapLooseTopLevelContent(root: HTMLElement): void {
  let paragraph: HTMLParagraphElement | null = null;

  const ensureParagraphBefore = (node: Node): HTMLParagraphElement => {
    if (!paragraph) {
      paragraph = root.ownerDocument.createElement("p");
      root.insertBefore(paragraph, node);
    }
    return paragraph;
  };

  const closeParagraph = () => {
    paragraph = null;
  };

  for (const node of Array.from(root.childNodes)) {
    if (node.nodeType === Node.COMMENT_NODE) {
      node.remove();
      continue;
    }

    if (node.nodeType === Node.TEXT_NODE) {
      let text = node.textContent ?? "";
      if (!compactText(text)) {
        node.remove();
        continue;
      }
      if (text.includes("\n")) {
        text = text.replace(/\s*\n\s*/g, " ");
        if (!paragraph) text = text.trimStart();
        if (nextSiblingClosesLooseParagraph(node)) text = text.trimEnd();
      }
      if (!text) {
        node.remove();
        continue;
      }
      ensureParagraphBefore(node).appendChild(root.ownerDocument.createTextNode(text));
      node.remove();
      continue;
    }

    if (node.nodeType !== Node.ELEMENT_NODE) {
      closeParagraph();
      continue;
    }

    const element = node as HTMLElement;
    if (isTopLevelFlowElement(element)) {
      closeParagraph();
      continue;
    }

    ensureParagraphBefore(element).appendChild(element);
  }
}

export function stripPagedArtifacts(root: HTMLElement): void {
  const elements = [root, ...Array.from(root.querySelectorAll<HTMLElement>("*"))];
  for (const el of elements) {
    if (el.classList.contains("pagedjs_hyphen")) {
      removeGeneratedHyphen(el);
    }

    el.removeAttribute("data-ref");
    el.removeAttribute("data-id");
    el.removeAttribute("data-pagedly-ref");
    el.removeAttribute(EDITABLE_ROOT_REF_ATTR);
    el.removeAttribute("data-pagedly-readonly-source");
    el.removeAttribute("data-split-from");
    el.removeAttribute("data-split-to");
    el.removeAttribute("data-previous-break-after");
    el.removeAttribute("data-break-before");
    el.removeAttribute("data-undisplayed");
    el.removeAttribute("contenteditable");
    el.removeAttribute("spellcheck");
    el.removeAttribute("aria-readonly");
    el.removeAttribute("tabindex");

    for (const className of Array.from(el.classList)) {
      if (className.startsWith("pagedjs_")) el.classList.remove(className);
    }
    if (el.classList.length === 0) el.removeAttribute("class");
  }
}

function stampEditableRootRefs(root: HTMLElement, selector?: string): void {
  if (!selector) return;
  let editableRoots: HTMLElement[] = [];
  try {
    editableRoots = Array.from(root.querySelectorAll<HTMLElement>(selector)).filter(
      (el) => !el.parentElement?.closest(selector),
    );
  } catch {
    return;
  }

  // Preserve existing identifiers (set by splitOversizedHtml when it broke a
  // container into page-fitting chunks); only assign new sequential ones to
  // editable roots that don't yet have an identifier.
  let nextRef = 0;
  const taken = new Set<string>();
  for (const editableRoot of editableRoots) {
    const existing = editableRoot.getAttribute(EDITABLE_ROOT_REF_ATTR);
    if (existing) taken.add(existing);
  }
  for (const editableRoot of editableRoots) {
    if (editableRoot.hasAttribute(EDITABLE_ROOT_REF_ATTR)) continue;
    while (taken.has(String(nextRef))) nextRef++;
    editableRoot.setAttribute(EDITABLE_ROOT_REF_ATTR, String(nextRef));
    taken.add(String(nextRef));
    nextRef++;
  }
}

function reconstructionRefFor(node: HTMLElement): string | null {
  const editableRootRef = node.getAttribute(EDITABLE_ROOT_REF_ATTR);
  if (editableRootRef) return `${EDITABLE_ROOT_REF_ATTR}:${editableRootRef}`;
  return node.getAttribute("data-pagedly-ref");
}

function hasDirectSourceChildren(root: HTMLElement): boolean {
  return Array.from(root.children).some((child) => child.hasAttribute("data-pagedly-ref"));
}

function nextSiblingClosesLooseParagraph(node: Node): boolean {
  let next = node.nextSibling;
  while (next) {
    if (next.nodeType === Node.COMMENT_NODE) {
      next = next.nextSibling;
      continue;
    }
    if (next.nodeType === Node.TEXT_NODE && !compactText(next.textContent ?? "")) {
      next = next.nextSibling;
      continue;
    }
    if (next.nodeType !== Node.ELEMENT_NODE) return true;
    return isTopLevelFlowElement(next as HTMLElement);
  }
  return true;
}

function isTopLevelFlowElement(element: HTMLElement): boolean {
  return TOP_LEVEL_FLOW_TAGS.has(element.tagName);
}

const TOP_LEVEL_FLOW_TAGS = new Set([
  "ADDRESS",
  "ARTICLE",
  "ASIDE",
  "BLOCKQUOTE",
  "DIV",
  "DL",
  "FIGURE",
  "FOOTER",
  "H1",
  "H2",
  "H3",
  "H4",
  "H5",
  "H6",
  "HEADER",
  "HR",
  "IMG",
  "MAIN",
  "NAV",
  "OL",
  "P",
  "PRE",
  "SECTION",
  "TABLE",
  "TEMPLATE", // section-anchor sentinels — must stay at top level, never wrapped in a paragraph
  "UL",
]);

function removeGeneratedHyphen(el: HTMLElement): void {
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  let last: Text | null = null;
  let node = walker.nextNode() as Text | null;
  while (node) {
    last = node;
    node = walker.nextNode() as Text | null;
  }
  if (last?.textContent?.endsWith("\u2011")) {
    last.textContent = last.textContent.slice(0, -1);
  }
}

function matchesReadOnlyChrome(el: HTMLElement, selector?: string): boolean {
  if (!selector) return false;
  try {
    return el.matches(selector);
  } catch {
    return false;
  }
}

function queryReadOnlyChrome(root: HTMLElement, selector?: string): HTMLElement[] {
  if (!selector) return [];
  try {
    return Array.from(root.querySelectorAll<HTMLElement>(selector));
  } catch {
    return [];
  }
}

function compactText(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}
