// HTML -> DOCX (OOXML) export. Boundary-only: reads the editor's serialized
// HTML and produces a valid .docx byte stream. Never touches the pagination
// engine. Dependency-free — includes a minimal store-only ZIP writer + CRC32
// and a focused HTML->WordprocessingML mapping (paragraphs, headings, runs with
// bold/italic/underline/strike, lists, blockquote, tables, images, links).

// ── CRC32 ─────────────────────────────────────────────────────────
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(bytes: Uint8Array): number {
  let c = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

// ── Minimal store-only ZIP ────────────────────────────────────────
type ZipEntry = { name: string; data: Uint8Array };

function zipStore(entries: ZipEntry[]): Uint8Array {
  const enc = new TextEncoder();
  const chunks: Uint8Array[] = [];
  const central: Uint8Array[] = [];
  let offset = 0;

  const u16 = (n: number) => new Uint8Array([n & 0xff, (n >>> 8) & 0xff]);
  const u32 = (n: number) =>
    new Uint8Array([n & 0xff, (n >>> 8) & 0xff, (n >>> 16) & 0xff, (n >>> 24) & 0xff]);
  const concat = (arrs: Uint8Array[]) => {
    const len = arrs.reduce((a, b) => a + b.length, 0);
    const out = new Uint8Array(len);
    let p = 0;
    for (const a of arrs) { out.set(a, p); p += a.length; }
    return out;
  };

  for (const e of entries) {
    const nameBytes = enc.encode(e.name);
    const crc = crc32(e.data);
    const local = concat([
      u32(0x04034b50), u16(20), u16(0), u16(0), u16(0), u16(0),
      u32(crc), u32(e.data.length), u32(e.data.length),
      u16(nameBytes.length), u16(0), nameBytes, e.data,
    ]);
    chunks.push(local);
    central.push(
      concat([
        u32(0x02014b50), u16(20), u16(20), u16(0), u16(0), u16(0), u16(0),
        u32(crc), u32(e.data.length), u32(e.data.length),
        u16(nameBytes.length), u16(0), u16(0), u16(0), u16(0), u32(0),
        u32(offset), nameBytes,
      ]),
    );
    offset += local.length;
  }

  const centralBlob = concat(central);
  const end = concat([
    u32(0x06054b50), u16(0), u16(0),
    u16(entries.length), u16(entries.length),
    u32(centralBlob.length), u32(offset), u16(0),
  ]);
  return concat([...chunks, centralBlob, end]);
}

// ── HTML -> WordprocessingML ──────────────────────────────────────
const xmlEscape = (s: string): string =>
  s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

type RunStyle = {
  b?: boolean;
  i?: boolean;
  u?: boolean;
  strike?: boolean;
  /** Half-points (w:sz). */
  szHalf?: number;
  /** 6-digit hex, no '#'. */
  color?: string;
  /** Background fill, 6-digit hex, no '#' (w:shd). */
  fill?: string;
  /** Font family name. */
  font?: string;
};

// Collected while walking the HTML: hyperlink/image relationships + embedded
// media bytes, so the produced package carries everything the document refs.
type ExportCtx = {
  rels: string[]; // <Relationship .../> entries for word/_rels/document.xml.rels
  media: ZipEntry[]; // word/media/* binary parts
  nextRelId: number; // rId counter (rId1 = numbering, see DOC_RELS base)
  mediaExts: Set<string>; // for [Content_Types].xml Default entries
};
const newExportCtx = (): ExportCtx => ({ rels: [], media: [], nextRelId: 2, mediaExts: new Set() });

// CSS color (#rgb/#rrggbb/rgb()) → 6-digit hex without '#', or null.
function cssColorToHex(v: string): string | null {
  const s = v.trim();
  let m = /^#([0-9a-f]{6})$/i.exec(s);
  if (m) return m[1].toUpperCase();
  m = /^#([0-9a-f]{3})$/i.exec(s);
  if (m) return m[1].split("").map((c) => c + c).join("").toUpperCase();
  m = /^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})/i.exec(s);
  if (m) {
    return [m[1], m[2], m[3]]
      .map((n) => Math.min(255, Number(n)).toString(16).padStart(2, "0"))
      .join("")
      .toUpperCase();
  }
  return null;
}

// CSS font-size (pt/px) → half-points, or null.
function cssFontSizeToHalf(v: string): number | null {
  const m = /^(\d+(?:\.\d+)?)(pt|px)$/i.exec(v.trim());
  if (!m) return null;
  const n = Number(m[1]);
  const pt = m[2].toLowerCase() === "pt" ? n : n * 0.75; // px → pt at 96dpi
  if (!(pt > 0 && pt < 400)) return null;
  return Math.round(pt * 2);
}

// Fold an element's inline style into the inherited run style (visual character
// formatting — the inverse of the importer's runStyle()).
function foldElementStyle(el: HTMLElement, style: RunStyle): RunStyle {
  const next: RunStyle = { ...style };
  const fs = el.style.fontSize;
  if (fs) {
    const half = cssFontSizeToHalf(fs);
    if (half != null) next.szHalf = half;
  }
  if (el.style.color) {
    const hex = cssColorToHex(el.style.color);
    if (hex) next.color = hex;
  }
  const bg = el.style.backgroundColor || el.style.background;
  if (bg) {
    const hex = cssColorToHex(bg);
    if (hex) next.fill = hex;
  }
  if (el.style.fontFamily) {
    const fam = el.style.fontFamily.split(",")[0].trim().replace(/^['"]|['"]$/g, "");
    if (fam && /^[\w \-]+$/.test(fam)) next.font = fam;
  }
  const td = el.style.textDecoration || el.style.textDecorationLine;
  if (td && /underline/i.test(td)) next.u = true;
  if (td && /line-through/i.test(td)) next.strike = true;
  return next;
}

function rPrXml(style: RunStyle): string {
  const props: string[] = [];
  if (style.b) props.push("<w:b/>");
  if (style.i) props.push("<w:i/>");
  if (style.u) props.push('<w:u w:val="single"/>');
  if (style.strike) props.push("<w:strike/>");
  if (style.font) props.push(`<w:rFonts w:ascii="${xmlEscape(style.font)}" w:hAnsi="${xmlEscape(style.font)}"/>`);
  if (style.szHalf != null) props.push(`<w:sz w:val="${style.szHalf}"/><w:szCs w:val="${style.szHalf}"/>`);
  if (style.color) props.push(`<w:color w:val="${style.color}"/>`);
  if (style.fill) props.push(`<w:shd w:val="clear" w:color="auto" w:fill="${style.fill}"/>`);
  return props.length ? `<w:rPr>${props.join("")}</w:rPr>` : "";
}

// Decode a data:image/...;base64 URL into bytes + extension, or null.
function decodeDataImage(src: string): { bytes: Uint8Array; ext: string } | null {
  const m = /^data:image\/(png|jpeg|jpg|gif|webp);base64,([A-Za-z0-9+/=]+)$/i.exec(src.trim());
  if (!m) return null;
  try {
    const bin = atob(m[2]);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    const ext = m[1].toLowerCase() === "jpg" ? "jpeg" : m[1].toLowerCase();
    return { bytes, ext };
  } catch {
    return null;
  }
}

// <img> → inline w:drawing referencing an embedded media part. Only data:image
// sources embed (the editor stores images as data URLs); external URLs fall back
// to their alt text so nothing silently disappears.
function imageToDrawing(el: HTMLElement, ctx: ExportCtx): string {
  const src = el.getAttribute("src") ?? "";
  const alt = el.getAttribute("alt") ?? "";
  const decoded = decodeDataImage(src);
  if (!decoded) {
    return alt ? `<w:r><w:t xml:space="preserve">${xmlEscape(alt)}</w:t></w:r>` : "";
  }
  const idx = ctx.media.length + 1;
  const name = `media/image${idx}.${decoded.ext}`;
  const rId = `rId${ctx.nextRelId++}`;
  ctx.media.push({ name: `word/${name}`, data: decoded.bytes });
  ctx.mediaExts.add(decoded.ext);
  ctx.rels.push(
    `<Relationship Id="${rId}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="${name}"/>`,
  );
  // Dimensions: width/height attrs (px) → EMU (×9525); default 300px wide.
  const wPx = Number(el.getAttribute("width")) || 300;
  const hPx = Number(el.getAttribute("height")) || Math.round(wPx * 0.75);
  const cx = Math.max(1, Math.round(wPx * 9525));
  const cy = Math.max(1, Math.round(hPx * 9525));
  const nv = xmlEscape(alt || `image${idx}`);
  return (
    `<w:r><w:drawing>` +
    `<wp:inline xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" distT="0" distB="0" distL="0" distR="0">` +
    `<wp:extent cx="${cx}" cy="${cy}"/>` +
    `<wp:docPr id="${idx}" name="${nv}"/>` +
    `<a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">` +
    `<a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture">` +
    `<pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">` +
    `<pic:nvPicPr><pic:cNvPr id="${idx}" name="${nv}"/><pic:cNvPicPr/></pic:nvPicPr>` +
    `<pic:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="${rId}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>` +
    `<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr>` +
    `</pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r>`
  );
}

function runsFromInline(node: Node, style: RunStyle, ctx: ExportCtx): string {
  if (node.nodeType === Node.TEXT_NODE) {
    const text = (node.nodeValue ?? "").replace(/​/g, "");
    if (!text) return "";
    return `<w:r>${rPrXml(style)}<w:t xml:space="preserve">${xmlEscape(text)}</w:t></w:r>`;
  }
  if (node.nodeType !== Node.ELEMENT_NODE) return "";
  const el = node as HTMLElement;
  const tag = el.tagName;
  if (tag === "BR") return '<w:r><w:br/></w:r>';
  if (tag === "IMG") return imageToDrawing(el, ctx);
  let next: RunStyle = { ...style };
  if (tag === "STRONG" || tag === "B") next.b = true;
  if (tag === "EM" || tag === "I") next.i = true;
  if (tag === "U" || tag === "INS") next.u = true;
  if (tag === "S" || tag === "STRIKE" || tag === "DEL") next.strike = true;
  if (tag === "CODE") next.font = "Consolas";
  next = foldElementStyle(el, next);
  const inner = Array.from(el.childNodes).map((c) => runsFromInline(c, next, ctx)).join("");
  // Hyperlink: wrap the runs + register an external relationship. http(s)/mailto
  // only — anything else (e.g. fragment links into the doc) stays plain runs.
  if (tag === "A") {
    const href = el.getAttribute("href") ?? "";
    if (/^(https?:|mailto:)/i.test(href)) {
      const rId = `rId${ctx.nextRelId++}`;
      ctx.rels.push(
        `<Relationship Id="${rId}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="${xmlEscape(href)}" TargetMode="External"/>`,
      );
      return `<w:hyperlink r:id="${rId}">${inner}</w:hyperlink>`;
    }
  }
  return inner;
}

function paragraph(
  inner: string,
  opts: { style?: string; numId?: number; ilvl?: number; pPrRaw?: string } = {},
): string {
  const pPr: string[] = [];
  if (opts.style) pPr.push(`<w:pStyle w:val="${opts.style}"/>`);
  if (opts.numId != null) {
    pPr.push(`<w:numPr><w:ilvl w:val="${opts.ilvl ?? 0}"/><w:numId w:val="${opts.numId}"/></w:numPr>`);
  }
  if (opts.pPrRaw) pPr.push(opts.pPrRaw);
  const pPrXml = pPr.length ? `<w:pPr>${pPr.join("")}</w:pPr>` : "";
  return `<w:p>${pPrXml}${inner}</w:p>`;
}

// Block-level inline style → pPr fragments (the inverse of the importer's
// paragraphStyle()): text-align → w:jc, margin-top/bottom + line-height →
// w:spacing (pt → twips ×20; multiple → ×240), margin-left/right + text-indent
// → w:ind (negative indent = hanging, positive = firstLine).
function pPrFromStyle(el: HTMLElement): string {
  const out: string[] = [];
  const ta = el.style.textAlign;
  const jcMap: Record<string, string> = { center: "center", right: "right", justify: "both" };
  if (ta && jcMap[ta]) out.push(`<w:jc w:val="${jcMap[ta]}"/>`);

  const pt = (v: string): number | null => {
    const m = /^(-?\d+(?:\.\d+)?)(pt|px)$/i.exec(v.trim());
    if (!m) return null;
    const n = Number(m[1]);
    return m[2].toLowerCase() === "pt" ? n : n * 0.75;
  };
  const spacing: string[] = [];
  const mb = el.style.marginBottom ? pt(el.style.marginBottom) : null;
  const mt = el.style.marginTop ? pt(el.style.marginTop) : null;
  if (mb != null && mb >= 0) spacing.push(`w:after="${Math.round(mb * 20)}"`);
  if (mt != null && mt >= 0) spacing.push(`w:before="${Math.round(mt * 20)}"`);
  const lh = el.style.lineHeight;
  if (lh && /^\d+(\.\d+)?$/.test(lh.trim())) {
    const mult = Number(lh);
    if (mult > 0.5 && mult < 4) spacing.push(`w:line="${Math.round(mult * 240)}"`, 'w:lineRule="auto"');
  }
  if (spacing.length) out.push(`<w:spacing ${spacing.join(" ")}/>`);

  const ind: string[] = [];
  const ml = el.style.marginLeft ? pt(el.style.marginLeft) : null;
  const mr = el.style.marginRight ? pt(el.style.marginRight) : null;
  const ti = el.style.textIndent ? pt(el.style.textIndent) : null;
  // Importer maps hanging → margin-left:(left+hanging) + text-indent:-hanging;
  // invert that here so a round-trip reproduces the original w:ind.
  if (ti != null && ti < 0) {
    const hang = Math.round(-ti * 20);
    const left = Math.max(0, Math.round(((ml ?? 0) + ti) * 20));
    ind.push(`w:left="${left}"`, `w:hanging="${hang}"`);
  } else {
    if (ml != null && ml > 0) ind.push(`w:left="${Math.round(ml * 20)}"`);
    if (ti != null && ti > 0) ind.push(`w:firstLine="${Math.round(ti * 20)}"`);
  }
  if (mr != null && mr > 0) ind.push(`w:right="${Math.round(mr * 20)}"`);
  if (ind.length) out.push(`<w:ind ${ind.join(" ")}/>`);
  return out.join("");
}

function blockToOoxml(el: HTMLElement, body: string[], ctx: ExportCtx): void {
  const tag = el.tagName;
  // Block style folds into the run baseline so e.g. a styled <p> colors its text.
  const base = foldElementStyle(el, {});
  const pPrRaw = pPrFromStyle(el);
  if (/^H[1-6]$/.test(tag)) {
    body.push(paragraph(runsFromInline(el, base, ctx), { style: `Heading${tag[1]}`, pPrRaw }));
    return;
  }
  // A generated TOC: emit the title + one paragraph per entry. Flattening it as a
  // plain DIV would concatenate every entry + page number into one run-on line.
  if (tag === "DIV" && el.classList.contains("pagedly-toc")) {
    const title = el.querySelector(".pagedly-toc__title")?.textContent?.trim();
    if (title) {
      body.push(paragraph(`<w:r><w:rPr><w:b/></w:rPr><w:t xml:space="preserve">${xmlEscape(title)}</w:t></w:r>`));
    }
    for (const entry of Array.from(el.querySelectorAll(".pagedly-toc__entry"))) {
      const text = (entry.querySelector(".pagedly-toc__text")?.textContent ?? "").trim();
      if (text) body.push(paragraph(`<w:r><w:t xml:space="preserve">${xmlEscape(text)}</w:t></w:r>`));
    }
    return;
  }
  if (tag === "P" || tag === "DIV") {
    body.push(paragraph(runsFromInline(el, base, ctx), { pPrRaw }));
    return;
  }
  if (tag === "BLOCKQUOTE") {
    body.push(paragraph(runsFromInline(el, base, ctx), { style: "Quote", pPrRaw }));
    return;
  }
  if (tag === "PRE") {
    const text = (el.textContent ?? "").split("\n");
    for (const line of text) {
      body.push(paragraph(`<w:r><w:rPr><w:rFonts w:ascii="Consolas" w:hAnsi="Consolas"/></w:rPr><w:t xml:space="preserve">${xmlEscape(line)}</w:t></w:r>`));
    }
    return;
  }
  if (tag === "UL" || tag === "OL") {
    const numId = tag === "OL" ? 2 : 1;
    walkList(el, numId, 0, body, ctx);
    return;
  }
  if (tag === "HR") {
    body.push('<w:p><w:pPr><w:pBdr><w:bottom w:val="single" w:sz="6" w:space="1" w:color="auto"/></w:pBdr></w:pPr></w:p>');
    return;
  }
  if (tag === "FIGURE") {
    const cap = el.querySelector("figcaption");
    body.push(paragraph(runsFromInline(el.querySelector("img") ?? el, base, ctx)));
    if (cap) body.push(paragraph(`<w:r><w:rPr><w:i/></w:rPr><w:t xml:space="preserve">${xmlEscape(cap.textContent ?? "")}</w:t></w:r>`, { style: "Caption" }));
    return;
  }
  if (tag === "TABLE") {
    body.push(tableToOoxml(el, ctx));
    return;
  }
  // Fallback.
  body.push(paragraph(runsFromInline(el, base, ctx), { pPrRaw }));
}

function walkList(list: HTMLElement, numId: number, level: number, body: string[], ctx: ExportCtx): void {
  for (const li of Array.from(list.children)) {
    if (li.tagName !== "LI") continue;
    const liEl = li as HTMLElement;
    const nested = Array.from(li.children).filter((c) => c.tagName === "UL" || c.tagName === "OL") as HTMLElement[];
    const contentNodes = Array.from(li.childNodes).filter(
      (c) => !(c.nodeType === Node.ELEMENT_NODE && ((c as Element).tagName === "UL" || (c as Element).tagName === "OL")),
    );
    const base = foldElementStyle(liEl, {});
    const inner = contentNodes.map((c) => runsFromInline(c, base, ctx)).join("");
    body.push(paragraph(inner, { numId, ilvl: level, pPrRaw: pPrFromStyle(liEl) }));
    for (const n of nested) walkList(n, n.tagName === "OL" ? 2 : 1, level + 1, body, ctx);
  }
}

function tableToOoxml(table: HTMLElement, ctx: ExportCtx): string {
  const rows = Array.from(table.querySelectorAll("tr"));
  const rowXml = rows
    .map((tr) => {
      const cells = Array.from(tr.querySelectorAll("th,td"))
        .map((c) => {
          const cell = c as HTMLElement;
          // colspan/rowspan → gridSpan / vMerge restart (continuation rows are
          // handled by Word from the gridSpan/vMerge of the origin cell; our
          // editor's merged tables physically remove the swallowed cells, which
          // Word tolerates for gridSpan but not vMerge — keep vMerge best-effort).
          const tcPr: string[] = ['<w:tcW w:w="0" w:type="auto"/>'];
          const colspan = Number(cell.getAttribute("colspan") || "1");
          if (colspan > 1) tcPr.push(`<w:gridSpan w:val="${colspan}"/>`);
          const base = foldElementStyle(cell, {});
          return `<w:tc><w:tcPr>${tcPr.join("")}</w:tcPr>${paragraph(runsFromInline(cell, base, ctx), { pPrRaw: pPrFromStyle(cell) })}</w:tc>`;
        })
        .join("");
      return `<w:tr>${cells}</w:tr>`;
    })
    .join("");
  return `<w:tbl><w:tblPr><w:tblStyle w:val="TableGrid"/><w:tblW w:w="0" w:type="auto"/><w:tblBorders><w:top w:val="single" w:sz="4" w:space="0" w:color="auto"/><w:left w:val="single" w:sz="4" w:space="0" w:color="auto"/><w:bottom w:val="single" w:sz="4" w:space="0" w:color="auto"/><w:right w:val="single" w:sz="4" w:space="0" w:color="auto"/><w:insideH w:val="single" w:sz="4" w:space="0" w:color="auto"/><w:insideV w:val="single" w:sz="4" w:space="0" w:color="auto"/></w:tblBorders></w:tblPr>${rowXml}</w:tbl>`;
}

/** Page geometry for the exported sectPr — mirrors docxImport's docxPageGeometry. */
export type DocxExportGeometry = {
  widthMm: number;
  heightMm: number;
  marginMm: { top: number; right: number; bottom: number; left: number };
};

const MM_TO_TWIPS = (mm: number) => Math.round((mm / 25.4) * 1440);

function sectPrXml(geo?: DocxExportGeometry): string {
  if (!geo) {
    return `<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr>`;
  }
  const m = geo.marginMm;
  return (
    `<w:sectPr><w:pgSz w:w="${MM_TO_TWIPS(geo.widthMm)}" w:h="${MM_TO_TWIPS(geo.heightMm)}"/>` +
    `<w:pgMar w:top="${MM_TO_TWIPS(m.top)}" w:right="${MM_TO_TWIPS(m.right)}" w:bottom="${MM_TO_TWIPS(m.bottom)}" w:left="${MM_TO_TWIPS(m.left)}"/></w:sectPr>`
  );
}

function buildDocumentXml(html: string, ctx: ExportCtx, geo?: DocxExportGeometry): string {
  const container = document.createElement("div");
  container.innerHTML = html;
  const body: string[] = [];
  for (const node of Array.from(container.childNodes)) {
    if (node.nodeType === Node.ELEMENT_NODE) {
      blockToOoxml(node as HTMLElement, body, ctx);
    } else if (node.nodeType === Node.TEXT_NODE && (node.nodeValue ?? "").trim()) {
      body.push(paragraph(`<w:r><w:t xml:space="preserve">${xmlEscape(node.nodeValue ?? "")}</w:t></w:r>`));
    }
  }
  if (body.length === 0) body.push(paragraph(""));
  // xmlns:r is required by w:hyperlink r:id (a:blip declares its own inline).
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body>${body.join("")}${sectPrXml(geo)}</w:body></w:document>`;
}

const MIME_BY_EXT: Record<string, string> = {
  png: "image/png",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
};

function contentTypesXml(ctx: ExportCtx): string {
  const defaults = [...ctx.mediaExts]
    .map((ext) => `<Default Extension="${ext}" ContentType="${MIME_BY_EXT[ext] ?? "application/octet-stream"}"/>`)
    .join("");
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>${defaults}<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/numbering.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.numbering+xml"/></Types>`;
}

const ROOT_RELS = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`;

function docRelsXml(ctx: ExportCtx): string {
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/numbering" Target="numbering.xml"/>${ctx.rels.join("")}</Relationships>`;
}

// Two abstract numberings: bullet (1) and decimal (2). Each defines ALL nine
// levels (ilvl 0-8) with per-level indent — walkList emits ilvl 1+ for nested
// lists, and a referenced-but-undefined level renders with no bullet/number or
// indent in Word.
function numberingLevels(kind: "bullet" | "decimal"): string {
  let out = "";
  for (let i = 0; i < 9; i++) {
    const indent = 720 * (i + 1);
    const fmt =
      kind === "bullet"
        ? `<w:numFmt w:val="bullet"/><w:lvlText w:val="•"/>`
        : `<w:numFmt w:val="decimal"/><w:lvlText w:val="%${i + 1}."/>`;
    out += `<w:lvl w:ilvl="${i}"><w:start w:val="1"/>${fmt}<w:lvlJc w:val="left"/><w:pPr><w:ind w:left="${indent}" w:hanging="360"/></w:pPr></w:lvl>`;
  }
  return out;
}
const NUMBERING = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:abstractNum w:abstractNumId="0">${numberingLevels(
  "bullet",
)}</w:abstractNum><w:abstractNum w:abstractNumId="1">${numberingLevels(
  "decimal",
)}</w:abstractNum><w:num w:numId="1"><w:abstractNumId w:val="0"/></w:num><w:num w:numId="2"><w:abstractNumId w:val="1"/></w:num></w:numbering>`;

/** Convert editor HTML to a .docx byte stream (Uint8Array). Requires a DOM. */
export function htmlToDocx(html: string, geometry?: DocxExportGeometry): Uint8Array {
  const enc = new TextEncoder();
  const ctx = newExportCtx();
  // Document first — walking it populates ctx (hyperlink/image rels + media).
  const documentXml = buildDocumentXml(html, ctx, geometry);
  return zipStore([
    { name: "[Content_Types].xml", data: enc.encode(contentTypesXml(ctx)) },
    { name: "_rels/.rels", data: enc.encode(ROOT_RELS) },
    { name: "word/document.xml", data: enc.encode(documentXml) },
    { name: "word/_rels/document.xml.rels", data: enc.encode(docRelsXml(ctx)) },
    { name: "word/numbering.xml", data: enc.encode(NUMBERING) },
    ...ctx.media,
  ]);
}

/** Convenience: download the HTML as a .docx file (browser only). */
export function downloadDocx(
  html: string,
  filename = "document.docx",
  geometry?: DocxExportGeometry,
): void {
  const bytes = htmlToDocx(html, geometry);
  const blob = new Blob([bytes.buffer as ArrayBuffer], {
    type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename.endsWith(".docx") ? filename : `${filename}.docx`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}
