// Table row/column editing — pure DOM operations on a cell. The caller
// (Editor.runCommand) finds the caret's cell, runs an op, then dispatches an
// input event so the pagination engine reflows + emits onChange. v1 assumes
// rectangular tables (no merged cells / colspan); merge/split is a later phase.

export function findCell(node: Node | null): HTMLTableCellElement | null {
  let n: Node | null = node;
  while (n) {
    if (n.nodeType === Node.ELEMENT_NODE) {
      const tag = (n as Element).tagName.toLowerCase();
      if (tag === "td" || tag === "th") return n as HTMLTableCellElement;
      if (tag === "table") return null; // walked past the cell
    }
    n = n.parentNode;
  }
  return null;
}

function ownerTable(cell: HTMLTableCellElement): HTMLTableElement | null {
  return cell.closest("table");
}

function cellColIndex(cell: HTMLTableCellElement): number {
  const row = cell.parentElement as HTMLTableRowElement | null;
  if (!row) return 0;
  return Array.prototype.indexOf.call(row.cells, cell);
}

/** All rows of a table in document order (thead + tbody + tfoot). */
function allRows(table: HTMLTableElement): HTMLTableRowElement[] {
  return Array.from(table.querySelectorAll<HTMLTableRowElement>("tr")).filter(
    (tr) => tr.closest("table") === table,
  );
}

function blankCell(tag: "td" | "th"): HTMLTableCellElement {
  const c = document.createElement(tag);
  c.appendChild(document.createElement("br"));
  return c;
}

const spanOf = (cell: HTMLTableCellElement, attr: "colspan" | "rowspan"): number => {
  const v = parseInt(cell.getAttribute(attr) ?? "1", 10);
  return Number.isFinite(v) && v > 0 ? v : 1;
};

// True if any cell spans more than one column/row. Column insert/delete address
// cells by their raw DOM index, which desyncs from the VISUAL grid once merges
// exist (a colspan cell or a rowspan from above shifts every column to its
// right) — and a correct fix needs a full grid model with inherently ambiguous
// rowspan handling. Rather than silently corrupt the table (the wrong cell gets
// added/removed and serializes into saved source), the column ops refuse on a
// merged table. Rectangular tables — the overwhelming common case — are
// unaffected. Row ops and merge/split stay grid-agnostic and safe.
function tableHasMerges(table: HTMLTableElement): boolean {
  return Array.from(table.querySelectorAll<HTMLTableCellElement>("td,th")).some(
    (c) => spanOf(c, "colspan") > 1 || spanOf(c, "rowspan") > 1,
  );
}

/** The section (thead/tbody/tfoot) a row belongs to, for cross-section guards. */
function rowSection(row: HTMLTableRowElement): string {
  return row.parentElement?.tagName.toLowerCase() ?? "tbody";
}

export function insertRow(
  cell: HTMLTableCellElement,
  where: "above" | "below",
): void {
  const row = cell.parentElement as HTMLTableRowElement | null;
  if (!row) return;
  const tag = cell.tagName.toLowerCase() === "th" && where === "above" ? "th" : "td";
  const newRow = document.createElement("tr");
  for (let i = 0; i < row.cells.length; i++) newRow.appendChild(blankCell(tag));
  // Copy data-section-id so the new row stays in the same letter section.
  const sid = row.getAttribute("data-section-id");
  if (sid) newRow.setAttribute("data-section-id", sid);
  row.parentElement?.insertBefore(
    newRow,
    where === "above" ? row : row.nextSibling,
  );
}

export function insertColumn(
  cell: HTMLTableCellElement,
  where: "before" | "after",
): void {
  const table = ownerTable(cell);
  if (!table) return;
  if (tableHasMerges(table)) return; // DOM-index column ops corrupt merged tables
  const at = cellColIndex(cell) + (where === "after" ? 1 : 0);
  for (const row of allRows(table)) {
    const isHeader = row.parentElement?.tagName.toLowerCase() === "thead";
    const newCell = blankCell(isHeader ? "th" : "td");
    const ref = row.cells[at] ?? null;
    row.insertBefore(newCell, ref);
  }
}

/** Returns false (no-op) if it would leave the table with zero rows. */
export function deleteRow(cell: HTMLTableCellElement): boolean {
  const table = ownerTable(cell);
  const row = cell.parentElement as HTMLTableRowElement | null;
  if (!table || !row) return false;
  if (allRows(table).length <= 1) return false; // keep at least one row
  row.remove();
  return true;
}

/** Returns false (no-op) if it would leave the table with zero columns. */
export function deleteColumn(cell: HTMLTableCellElement): boolean {
  const table = ownerTable(cell);
  if (!table) return false;
  if (tableHasMerges(table)) return false; // see tableHasMerges — avoid corruption
  const col = cellColIndex(cell);
  const rows = allRows(table);
  const maxCols = Math.max(...rows.map((r) => r.cells.length), 0);
  if (maxCols <= 1) return false; // keep at least one column
  for (const row of rows) {
    if (row.cells[col]) row.deleteCell(col);
  }
  return true;
}

/** Merge a cell with the next cell in its row (colspan). */
export function mergeRight(cell: HTMLTableCellElement): boolean {
  const row = cell.parentElement as HTMLTableRowElement | null;
  if (!row) return false;
  const idx = Array.prototype.indexOf.call(row.cells, cell);
  const next = row.cells[idx + 1];
  if (!next) return false;
  // Preserve content separated by a space; drop the next cell's lone <br>.
  if ((next.textContent ?? "").trim()) {
    while (next.firstChild) cell.appendChild(next.firstChild);
  }
  cell.setAttribute("colspan", String(spanOf(cell, "colspan") + spanOf(next, "colspan")));
  next.remove();
  return true;
}

/** Merge a cell with the cell directly below it in its column (rowspan). */
export function mergeDown(cell: HTMLTableCellElement): boolean {
  const table = ownerTable(cell);
  const row = cell.parentElement as HTMLTableRowElement | null;
  if (!table || !row) return false;
  const rows = allRows(table);
  const rowIdx = rows.indexOf(row);
  const below = rows[rowIdx + 1];
  if (!below) return false;
  // Don't merge across a thead/tbody/tfoot boundary — a rowspan straddling
  // sections is invalid OOXML and corrupts the table on export.
  if (rowSection(row) !== rowSection(below)) return false;
  const col = cellColIndex(cell);
  const target = below.cells[col];
  if (!target) return false;
  if ((target.textContent ?? "").trim()) {
    while (target.firstChild) cell.appendChild(target.firstChild);
  }
  cell.setAttribute("rowspan", String(spanOf(cell, "rowspan") + spanOf(target, "rowspan")));
  target.remove();
  return true;
}

/** Split a merged cell back into individual cells. */
export function splitCell(cell: HTMLTableCellElement): boolean {
  const table = ownerTable(cell);
  const row = cell.parentElement as HTMLTableRowElement | null;
  if (!table || !row) return false;
  const cs = spanOf(cell, "colspan");
  const rs = spanOf(cell, "rowspan");
  if (cs <= 1 && rs <= 1) return false;
  const tag = cell.tagName.toLowerCase() === "th" ? "th" : "td";
  cell.removeAttribute("colspan");
  cell.removeAttribute("rowspan");
  // Re-add the colspan gap in this row.
  for (let i = 1; i < cs; i++) row.insertBefore(blankCell(tag), cell.nextSibling);
  // Re-add cells in the rows the rowspan covered.
  if (rs > 1) {
    const rows = allRows(table);
    const rowIdx = rows.indexOf(row);
    const col = cellColIndex(cell);
    for (let r = 1; r < rs; r++) {
      const below = rows[rowIdx + r];
      if (!below) continue;
      const ref = below.cells[col] ?? null;
      for (let i = 0; i < cs; i++) below.insertBefore(blankCell(tag), ref);
    }
  }
  return true;
}

/** Removes the whole table; returns the element that should host the caret. */
export function deleteTable(cell: HTMLTableCellElement): HTMLElement | null {
  const table = ownerTable(cell);
  if (!table) return null;
  const parent = table.parentElement;
  // Seed a paragraph in the table's place so the page never goes empty and
  // the caret has somewhere to land.
  const p = document.createElement("p");
  p.appendChild(document.createElement("br"));
  const sid = table.getAttribute("data-section-id");
  if (sid) p.setAttribute("data-section-id", sid);
  parent?.insertBefore(p, table);
  table.remove();
  return p;
}
