// Default "keep this element whole across a page break" predicate.
// Atomic media and anything the host opts in via class or inline
// break-inside: avoid is moved to the next page intact rather than
// split mid-element.
const defaultDoNotBreak = (el: HTMLElement): boolean =>
  // Atomic media that must not be split mid-element. NOT tables —
  // those reflow row-by-row across pages by design.
  /^(img|figure|svg|hr|video)$/i.test(el.tagName) ||
  el.classList?.contains("pagedly-keep-together") ||
  el.style?.breakInside === "avoid" ||
  el.style?.pageBreakInside === "avoid";

const DEFAULT_PAGE_NUMBER_FOOTER = { right: "{page} / {total}" } as const;

// Resolve the effective bottom-margin chrome. An explicit `pageFooterHtml`
// always wins; otherwise page numbers are shown out of the box unless
// `showPageNumbers` is explicitly false. Exported for unit testing.
export function resolvePageFooterHtml(
  pageFooterHtml: { left?: string; right?: string } | undefined,
  showPageNumbers: boolean | undefined,
): { left?: string; right?: string } | undefined {
  if (pageFooterHtml) return pageFooterHtml;
  if (showPageNumbers === false) return undefined;
  return { ...DEFAULT_PAGE_NUMBER_FOOTER };
}

