/**
 * Count words + characters in the editable content, EXCLUDING inert page
 * chrome (page numbers, repeated table headers) which the engine stamps with
 * `aria-hidden="true"`. Single TreeWalker pass, no clone — cheap enough to run
 * on selection changes for typical docs. Whitespace is collapsed so the
 * character count reflects visible text, not the HTML's formatting whitespace.
 */
function computeContentCounts(root: HTMLElement): {
  characterCount: number;
  wordCount: number;
  isEmpty: boolean;
} {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      // Reject any text inside an aria-hidden subtree (chrome / repeated heads).
      let el = node.parentElement;
      while (el && el !== root) {
        if (el.getAttribute("aria-hidden") === "true") {
          return NodeFilter.FILTER_REJECT;
        }
        el = el.parentElement;
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  const parts: string[] = [];
  let current = walker.nextNode();
  while (current) {
    parts.push(current.nodeValue ?? "");
    current = walker.nextNode();
  }
  const normalized = parts
    .join(" ")
    .replace(/​/g, "") // drop zero-width boundary markers
    .replace(/\s+/g, " ")
    .trim();
  const characterCount = normalized.length;
  const wordCount = normalized ? normalized.split(" ").filter(Boolean).length : 0;
  return { characterCount, wordCount, isEmpty: characterCount === 0 };
}

