// Headless "drive the editor from code / an AI agent" API.
//
// Pagedly already exposes an imperative `EditorHandle`. This module wraps it in
// a stable, documented, high-level facade plus a tool CATALOG (name +
// description + JSON-schema parameters) so the same surface can be handed to an
// LLM/agent or exposed over MCP. It adds NO new engine capability — every
// method routes to an existing handle call — so it carries zero pagination risk.

import type { EditorCommand, EditorHandle, ToolbarState } from "./types";
import { htmlToMarkdown, markdownToHtml } from "./markdown";
import { sanitizeEditorHtml } from "./sanitize";

export interface EditorAgent {
  /** Current document HTML (sanitized source). */
  getHtml(): Promise<string>;
  /** Current document as plain text. */
  getText(): Promise<string>;
  /** Current document as Markdown. */
  getMarkdown(): Promise<string>;
  /** Replace/insert document content from a Markdown string. */
  insertMarkdown(markdown: string): void;
  /** Current selection / document toolbar state (counts, block, marks…). */
  getState(): ToolbarState;
  /** Subscribe to state changes; returns an unsubscribe fn. */
  subscribe(listener: (state: ToolbarState) => void): () => void;

  /** Insert raw HTML at the caret. */
  insertHtml(html: string): void;
  /** Replace the whole document (e.g. restore a snapshot/version). */
  setHtml(html: string): void;
  /** List top-level blocks with stable in-session ids (for addressing). */
  getBlocks(): { pid: string; tag: string; text: string }[];
  /** Replace a block's content by its pid. Returns success. */
  replaceBlock(pid: string, html: string): boolean;
  /** Insert plain text at the caret (HTML-escaped). */
  insertText(text: string): void;
  /** Insert an image by URL/data-URL. */
  insertImage(src: string, alt?: string): void;

  /** Toggle an inline mark. */
  setMark(mark: "bold" | "italic" | "underline" | "strikethrough" | "inlineCode"): void;
  /** Set the current block type. */
  setBlock(block: "p" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6"): void;
  /** Toggle a list / structural block. */
  toggleBlock(kind: "bullet" | "numbered" | "checklist" | "quote" | "code"): void;
  /** Set paragraph alignment. */
  align(dir: "left" | "center" | "right" | "justify"): void;
  /** Insert a table. */
  insertTable(rows: number, cols: number, header?: boolean): void;

  undo(): void;
  redo(): void;
  selectAll(): void;
  focus(): void;
  /** Re-run pagination (after external HTML changes). */
  reflow(): Promise<void>;

  /** Escape hatch: run any raw editor command. */
  run(command: EditorCommand, value?: string): void;
}

const MARK_COMMAND: Record<string, EditorCommand> = {
  bold: "bold",
  italic: "italic",
  underline: "underline",
  strikethrough: "strikeThrough",
  inlineCode: "toggleInlineCode",
};

const TOGGLE_COMMAND: Record<string, EditorCommand> = {
  bullet: "insertUnorderedList",
  numbered: "insertOrderedList",
  checklist: "insertChecklist",
  quote: "toggleBlockquote",
  code: "formatCodeBlock",
};

const ALIGN_COMMAND: Record<string, EditorCommand> = {
  left: "justifyLeft",
  center: "justifyCenter",
  right: "justifyRight",
  justify: "justifyFull",
};

const escapeHtml = (s: string): string =>
  s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

const stripTags = (html: string): string => {
  if (typeof document !== "undefined") {
    const div = document.createElement("div");
    div.innerHTML = html;
    return (div.textContent ?? "").replace(/​/g, "");
  }
  // Node fallback (no DOM): crude tag strip.
  return html
    .replace(/<[^>]+>/g, " ")
    .replace(/​/g, "")
    .replace(/\s+/g, " ")
    .trim();
};

/** Wrap an EditorHandle in the headless agent facade. */
export function createEditorAgent(handle: EditorHandle): EditorAgent {
  return {
    getHtml: () => handle.flush(),
    getText: async () => stripTags(await handle.flush()),
    getMarkdown: async () => htmlToMarkdown(await handle.flush()),
    // The agent facade is the LLM/MCP entry point — every HTML-bearing call is
    // untrusted and goes through sanitizeEditorHtml before reaching the engine's
    // execCommand("insertHTML") / innerHTML sinks. Trusted-internal callers of
    // the same handle methods (slash menu, engine self-insertions) are untouched.
    insertMarkdown: (markdown) =>
      handle.insertHtml(sanitizeEditorHtml(markdownToHtml(markdown))),
    getState: () => handle.getState(),
    subscribe: (listener) => handle.subscribe(listener),
    insertHtml: (html) => handle.insertHtml(sanitizeEditorHtml(html)),
    setHtml: (html) => handle.setHtml?.(sanitizeEditorHtml(html)),
    getBlocks: () => handle.getBlocks?.() ?? [],
    replaceBlock: (pid, html) => handle.replaceBlock?.(pid, sanitizeEditorHtml(html)) ?? false,
    insertText: (text) => handle.insertHtml(escapeHtml(text)),
    insertImage: (src, alt) => handle.insertImage(src, alt),
    setMark: (mark) => handle.runCommand(MARK_COMMAND[mark]),
    setBlock: (block) => handle.runCommand("formatBlock", block),
    toggleBlock: (kind) => handle.runCommand(TOGGLE_COMMAND[kind]),
    align: (dir) => handle.runCommand(ALIGN_COMMAND[dir]),
    insertTable: (rows, cols, header = true) =>
      handle.runCommand("insertTable", JSON.stringify({ rows, cols, header })),
    undo: () => handle.undo(),
    redo: () => handle.redo(),
    selectAll: () => handle.selectAll(),
    focus: () => handle.focus(),
    reflow: () => handle.reflow(),
    run: (command, value) => handle.runCommand(command, value),
  };
}

// ── Tool catalog (for LLM / MCP exposure) ─────────────────────────
export interface EditorAgentTool {
  name: string;
  description: string;
  parameters: {
    type: "object";
    properties: Record<string, { type: string; enum?: string[]; description?: string }>;
    required?: string[];
  };
}

export const EDITOR_AGENT_TOOLS: EditorAgentTool[] = [
  { name: "get_html", description: "Return the document's current HTML.", parameters: { type: "object", properties: {} } },
  { name: "get_text", description: "Return the document's current plain text.", parameters: { type: "object", properties: {} } },
  { name: "get_markdown", description: "Return the document as Markdown.", parameters: { type: "object", properties: {} } },
  { name: "get_blocks", description: "List top-level blocks with stable ids (pid, tag, text).", parameters: { type: "object", properties: {} } },
  { name: "replace_block", description: "Replace a block's content by its pid.", parameters: { type: "object", properties: { pid: { type: "string" }, html: { type: "string" } }, required: ["pid", "html"] } },
  { name: "insert_markdown", description: "Insert content from a Markdown string at the caret.", parameters: { type: "object", properties: { markdown: { type: "string" } }, required: ["markdown"] } },
  { name: "insert_html", description: "Insert raw HTML at the caret.", parameters: { type: "object", properties: { html: { type: "string" } }, required: ["html"] } },
  { name: "insert_text", description: "Insert plain text at the caret.", parameters: { type: "object", properties: { text: { type: "string" } }, required: ["text"] } },
  { name: "insert_image", description: "Insert an image by URL or data URL.", parameters: { type: "object", properties: { src: { type: "string" }, alt: { type: "string" } }, required: ["src"] } },
  { name: "set_mark", description: "Toggle an inline mark on the selection.", parameters: { type: "object", properties: { mark: { type: "string", enum: ["bold", "italic", "underline", "strikethrough", "inlineCode"] } }, required: ["mark"] } },
  { name: "set_block", description: "Set the current block type.", parameters: { type: "object", properties: { block: { type: "string", enum: ["p", "h1", "h2", "h3", "h4", "h5", "h6"] } }, required: ["block"] } },
  { name: "toggle_block", description: "Toggle a list or structural block.", parameters: { type: "object", properties: { kind: { type: "string", enum: ["bullet", "numbered", "checklist", "quote", "code"] } }, required: ["kind"] } },
  { name: "align", description: "Set paragraph alignment.", parameters: { type: "object", properties: { dir: { type: "string", enum: ["left", "center", "right", "justify"] } }, required: ["dir"] } },
  { name: "insert_table", description: "Insert a table.", parameters: { type: "object", properties: { rows: { type: "number" }, cols: { type: "number" }, header: { type: "boolean" } }, required: ["rows", "cols"] } },
  { name: "undo", description: "Undo the last edit.", parameters: { type: "object", properties: {} } },
  { name: "redo", description: "Redo the last undone edit.", parameters: { type: "object", properties: {} } },
];

/**
 * Route a tool call (name + JSON args) to the agent. Returns a value for the
 * read tools, otherwise undefined. Throws on an unknown tool. This is the
 * adapter an MCP server or function-calling loop hands tool calls to.
 */
export async function invokeEditorTool(
  agent: EditorAgent,
  name: string,
  args: Record<string, unknown> = {},
): Promise<unknown> {
  switch (name) {
    case "get_html":
      return agent.getHtml();
    case "get_text":
      return agent.getText();
    case "get_markdown":
      return agent.getMarkdown();
    case "get_blocks":
      return agent.getBlocks();
    case "replace_block":
      return agent.replaceBlock(String(args.pid ?? ""), String(args.html ?? ""));
    case "insert_markdown":
      return agent.insertMarkdown(String(args.markdown ?? ""));
    case "insert_html":
      return agent.insertHtml(String(args.html ?? ""));
    case "insert_text":
      return agent.insertText(String(args.text ?? ""));
    case "insert_image":
      return agent.insertImage(String(args.src ?? ""), args.alt ? String(args.alt) : undefined);
    case "set_mark":
      return agent.setMark(args.mark as Parameters<EditorAgent["setMark"]>[0]);
    case "set_block":
      return agent.setBlock(args.block as Parameters<EditorAgent["setBlock"]>[0]);
    case "toggle_block":
      return agent.toggleBlock(args.kind as Parameters<EditorAgent["toggleBlock"]>[0]);
    case "align":
      return agent.align(args.dir as Parameters<EditorAgent["align"]>[0]);
    case "insert_table":
      return agent.insertTable(Number(args.rows), Number(args.cols), args.header as boolean | undefined);
    case "undo":
      return agent.undo();
    case "redo":
      return agent.redo();
    default:
      throw new Error(`Unknown editor tool: ${name}`);
  }
}
