// Shared HTML/URL sanitizer for UNTRUSTED input crossing into the live DOM:
// clipboard paste, Markdown import, and the agent/MCP facade (LLM-supplied
// HTML). Centralizes on DOMPurify — the same dependency + allow-list strategy
// the letter sanitizer (src/letter/sourceHtml.ts) already proves against the
// full editor vocabulary.
//
// Threat model (review Batch 1, issues 2/6/8/20): a paste / markdown / agent
// payload must never reach execCommand("insertHTML") or el.innerHTML carrying an
// event handler, a javascript:/vbscript: URL, or a scriptable element
// (<script>/<style>/<svg>/<math>/<iframe>/<object>/<embed>/<form>). DOMPurify
// strips on* handlers + bad schemes intrinsically; the dangerous elements are
// dropped by OMISSION from ALLOWED_TAGS (no FORBID_* — that would fight the
// allow-list and risk stripping the editor's own vocabulary).
//
// Over-stripping is as dangerous as a missed sink: the allow-list below is a
// VERBATIM copy of the letter sanitizer's, so pagedly-* classes (via `class`),
// colspan/rowspan, tracked-changes <ins>/<del>, <template> section anchors, every
// editor data-* attribute, and data:image image sources all survive untouched.
import DOMPurify from "dompurify";

// Editor content vocabulary — must stay in sync with src/letter/sourceHtml.ts.
const ALLOWED_TAGS = [
  "p", "br", "strong", "b", "em", "i", "u", "s", "strike", "sub", "sup",
  "h1", "h2", "h3", "h4", "h5", "h6", "ul", "ol", "li", "blockquote", "pre",
  "code", "a", "table", "thead", "tbody", "tfoot", "tr", "th", "td", "hr",
  "span", "div", "img", "figure", "figcaption", "ins", "del", "template",
];

// Editor data-* attributes the engine + features read (section routing,
// comments, TOC, cross-refs, footnotes, checklist, alignment).
const EDITOR_DATA_ATTRS = [
  "data-att-id", "data-text-align", "data-checked", "data-align",
  "data-comment-id", "data-toc-index", "data-toc-level", "data-xref-index",
  "data-xref-id", "data-xref-target", "data-fn", "data-fn-text", "data-fn-note",
  "data-section-id", "data-section-anchor", "data-generated-letter-chrome",
];

const ALLOWED_ATTR = [
  "href", "target", "rel", "colspan", "rowspan", "src", "alt", "title",
  "width", "height", "class", "style", "contenteditable", ...EDITOR_DATA_ATTRS,
];

// data:image is needed for inserted/dropped/pasted images (DOMPurify's default
// URI policy strips ALL data: URIs). blob: covers object URLs from the image
// downscale path. javascript:/vbscript:/data:text/html/data:image/svg+xml and
// protocol-relative (//host) are rejected.
const EDITOR_URI_REGEXP =
  /^(?:https?:|mailto:|tel:|#|\/(?!\/)|blob:|data:image\/(?:png|jpeg|jpg|gif|webp);base64,)/i;

const CONFIG = {
  ALLOWED_TAGS,
  ALLOWED_ATTR,
  // ALLOW_DATA_ATTR is false (don't blanket-allow arbitrary data-*); the editor
  // ones are whitelisted explicitly via ADD_ATTR + ADD_URI_SAFE_ATTR so they
  // survive even though DOMPurify would otherwise treat them as data attrs.
  ADD_ATTR: ["target", "contenteditable", ...EDITOR_DATA_ATTRS],
  // A custom ALLOWED_URI_REGEXP makes DOMPurify URI-check EVERY attribute not in
  // its URI-safe set — so non-URI attributes whose values aren't URLs (colspan="2",
  // width="40", and the editor data-*) get wrongly stripped. Exempt them here.
  // (The letter sanitizer omits the table-span attrs and so silently drops merges
  // on save — a latent bug this shared sanitizer avoids.)
  ADD_URI_SAFE_ATTR: [
    "target", "contenteditable", "colspan", "rowspan", "width", "height",
    ...EDITOR_DATA_ATTRS,
  ],
  ALLOW_DATA_ATTR: false,
  KEEP_CONTENT: true,
  ALLOWED_URI_REGEXP: EDITOR_URI_REGEXP,
} as const;

/**
 * Sanitize untrusted HTML for insertion into the editor. No-ops outside a DOM
 * (SSR) — same guard the letter sanitizer uses; jsdom provides `window`, so the
 * test suite exercises the real path.
 */
export function sanitizeEditorHtml(dirty: string): string {
  if (typeof window === "undefined") return dirty;
  return DOMPurify.sanitize(dirty ?? "", CONFIG as unknown as Record<string, unknown>);
}

/**
 * Validate + escape a URL for an HTML attribute (href/src). Returns "" for any
 * disallowed scheme (javascript:, vbscript:, data:text/html, data:image/svg+xml,
 * protocol-relative //host) so the attribute renders inert rather than executing.
 *
 * Used by the two string-template builders (markdown img/link, insertImage) that
 * concatenate URLs into HTML and so bypass DOMPurify's own URI check. Escapes the
 * attribute-breaking characters (" ' < >) but NOT `&` — `&` cannot break out of a
 * double-quoted attribute, and leaving it avoids double-escaping a value the
 * markdown path already entity-escaped.
 */
export function safeUrl(url: string): string {
  const trimmed = (url ?? "").trim();
  if (!trimmed) return "";
  // Protocol-relative URLs inherit the page scheme and can't be scheme-validated.
  if (/^\/\//.test(trimmed)) return "";
  const scheme = /^([a-z][a-z0-9+.-]*):/i.exec(trimmed);
  if (scheme) {
    const name = scheme[1].toLowerCase();
    const schemeOk =
      name === "http" ||
      name === "https" ||
      name === "mailto" ||
      name === "tel" ||
      name === "blob" ||
      /^data:image\/(?:png|jpeg|jpg|gif|webp);base64,/i.test(trimmed);
    if (!schemeOk) return "";
  }
  // Scheme-less (relative / fragment) URLs are safe; escape attribute-breaking chars.
  return trimmed
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}
