import DOMPurify from "dompurify";

import { stripPagedArtifacts, wrapLooseTopLevelContent } from "../paged/reconstruct";
import type {
  LetterDraft,
  LetterSection,
} from "./types";

// Match HRLETTER's working convention: anchors AND blocks share the same
// "data-section-id" attribute so the editor's section-id migration in
// stampPagedRefs/reconstructSourceHtml writes the exact attribute that
// splitBySection consumes. (Previously this was "data-pagedly-section-id" on
// blocks, which the generic reconstructor never wrote, so section info was
// lost on every round-trip.)
const SECTION_ID_ATTR = "data-section-id";
const SECTION_ANCHOR_ATTR = "data-section-anchor";
const SECTION_ANCHOR_ID_ATTR = "data-section-id";
const GENERATED_CHROME_ATTR = "data-generated-letter-chrome";
const CHECKED_ATTR = "data-checked";
const ALIGN_ATTR = "data-align";
const COMMENT_ATTR = "data-comment-id";
const SAVED_DATA_ATTRS = new Set([
  "data-att-id",
  "data-text-align",
  CHECKED_ATTR,
  ALIGN_ATTR,
  COMMENT_ATTR,
  "data-toc-index",
  "data-toc-level",
  "data-xref-index",
  "data-xref-id",
  "data-xref-target",
  "data-fn",
  "data-fn-text",
  "data-fn-note",
]);
const EDITOR_DATA_ATTRS = new Set([
  ...SAVED_DATA_ATTRS,
  SECTION_ID_ATTR,
  SECTION_ANCHOR_ATTR,
  SECTION_ANCHOR_ID_ATTR,
  GENERATED_CHROME_ATTR,
]);

export const LETTER_READ_ONLY_SELECTOR = [
  ".letterhead",
  ".attachments-section",
  `[${SECTION_ANCHOR_ATTR}]`,
  `[${GENERATED_CHROME_ATTR}]`,
].join(", ");

/**
 * The `html` prop given to PagedHtmlEditor when editing a letter. Now just the
 * body inner content — anchors + per-section HTML — without any letterhead or
 * attachments wrapper. The chrome is composed at render time via
 * `buildPagedLetterRenderShell` so paged.js sees the full letter, but the
 * editor's source state stays small and round-trips cleanly.
 */
export function buildLetterEditorHtml(
  draft: LetterDraft,
  options: { bodyHtml?: string } = {},
): string {
  return options.bodyHtml ?? buildMergedLetterBodyHtml(draft);
}

/**
 * Returns the render-shell wrapper used by PagedHtmlEditor at repaginate time
 * (via the `wrapSourceForRender` prop). It receives the editor's stamped body
 * inner HTML and surrounds it with the letterhead + .letter-body wrapper +
 * attachments, and injects the signature image right after the signature
 * section anchor. paged.js sees the complete letter; the editor's source
 * state never has to round-trip the chrome.
 */
export function buildPagedLetterRenderShell(draft: LetterDraft): (innerHtml: string) => string {
  const letterhead = letterheadHtml(draft);
  const attachments = buildAttachmentsBlock(draft);
  const signature = signatureImageHtml(
    draft,
    ` ${GENERATED_CHROME_ATTR}="signature" contenteditable="false"`,
  );
  const signatureSectionId = draft.sections.find((s) => s.sectionId === "signature")?.id;
  return (innerHtml: string) => {
    let body = innerHtml;
    if (signature && signatureSectionId) {
      // Insert the chrome right after the signature section anchor (or right
      // before the first paragraph carrying data-section-id="<signature-id>"
      // if the anchor isn't present in this snapshot).
      const escapedId = escapeRegExp(signatureSectionId);
      const anchorRegex = new RegExp(
        `(<template[^>]*${SECTION_ANCHOR_ATTR}[^>]*${SECTION_ANCHOR_ID_ATTR}="${escapedId}"[^>]*></template>)`,
        "i",
      );
      if (anchorRegex.test(body)) {
        body = body.replace(anchorRegex, `$1${signature}`);
      } else {
        // Fallback: prepend chrome before the first signature-section block.
        const blockRegex = new RegExp(
          `(<[a-z][^>]*${SECTION_ID_ATTR}="${escapedId}"[^>]*>)`,
          "i",
        );
        if (blockRegex.test(body)) body = body.replace(blockRegex, `${signature}$1`);
      }
    }
    return `
      ${letterhead}
      <div class="letter-body">${body}</div>
      ${attachments}
    `;
  };
}

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Legacy: builds the FULL letter HTML (chrome + body) in one go. Kept for
 * tests and any host that prefers to bypass the editor's render-shell prop.
 */
export function buildPagedLetterFullHtml(
  draft: LetterDraft,
  options: { bodyHtml?: string } = {},
): string {
  const body = options.bodyHtml ?? buildMergedLetterBodyHtml(draft);
  return `
    ${letterheadHtml(draft)}
    <div class="letter-body">${body}</div>
    ${buildAttachmentsBlock(draft)}
  `;
}

export function buildMergedLetterBodyHtml(draft: LetterDraft): string {
  // Chrome (signature image, letterhead, attachments) is composed at render
  // time by buildPagedLetterRenderShell — keep it OUT of the body source so
  // reconstruction never has to round-trip it.
  return draft.sections
    .map((section) => anchorHtmlFor(section.id) + sectionHtmlWithMarkers(section))
    .join("");
}

export function splitLetterEditorHtml(
  fullHtml: string,
  sections: LetterSection[] = [],
): { bodyHtml: string; sections: Record<string, string> } {
  // The editor now emits body-inner HTML directly (no .letter-body wrapper)
  // because the chrome is composed at render time. Still accept the legacy
  // wrapped form so old call sites and stored letters keep working.
  const doc = parseHtml(`<div>${fullHtml}</div>`);
  const bodies = doc ? Array.from(doc.querySelectorAll<HTMLElement>(".letter-body")) : [];
  const bodyHtml =
    bodies.length > 0 ? bodies.map((node) => node.innerHTML).join("") : fullHtml;
  return {
    bodyHtml,
    sections: splitBySection(bodyHtml, sections),
  };
}

export function applySectionHtmlToDraft(
  draft: LetterDraft,
  sections: Record<string, string>,
): LetterDraft {
  return {
    ...draft,
    sections: draft.sections.map((section) => {
      if (!Object.prototype.hasOwnProperty.call(sections, section.id)) return section;
      const nextHtml = sanitizeSavedSectionHtml(sections[section.id] ?? "");
      return nextHtml === section.html ? section : { ...section, html: nextHtml };
    }),
  };
}

export function splitBySection(
  sourceHtml: string,
  sections: LetterSection[] | string[] = [],
): Record<string, string> {
  const sectionIds = sectionIdsFrom(sections);
  const firstSectionId = sectionIds[0];
  const doc = parseHtml(`<div>${sourceHtml}</div>`);
  const root = doc?.body.firstElementChild as HTMLElement | null;
  const result: Record<string, string> = {};
  if (!root) return result;

  let currentId: string | null = null;
  let buffer: string[] = [];
  let foundSectionStructure = false;
  // Track sections we've already closed via flush(). Once we move PAST
  // a section, a later block carrying that section's id is treated as
  // a stale reattribution (typically introduced by a copy-paste that
  // dragged `data-section-id` along) — the block stays in whatever
  // section it physically resides in instead of being routed back.
  // Without this guard, each paste round-trip duplicated the pasted
  // blocks into their originating section AND kept them at the
  // cursor location.
  const closedIds = new Set<string>();
  // Track when we've explicitly seen a section anchor for `id` — the
  // anchor is the canonical "start of section X" signal and overrides
  // the stale-id guard so re-opening the same section via anchor is
  // still allowed.
  const anchorOpened = new Set<string>();

  const flush = () => {
    if (currentId != null) {
      result[currentId] = (result[currentId] ?? "") + buffer.join("");
      closedIds.add(currentId);
    }
    buffer = [];
  };

  for (const node of Array.from(root.childNodes)) {
    if (node.nodeType === Node.ELEMENT_NODE) {
      const element = node as HTMLElement;

      if (element.hasAttribute(SECTION_ANCHOR_ATTR)) {
        foundSectionStructure = true;
        flush();
        currentId = element.getAttribute(SECTION_ANCHOR_ID_ATTR);
        if (currentId) {
          anchorOpened.add(currentId);
          // Re-opening via anchor is intentional; allow appending.
          closedIds.delete(currentId);
        }
        continue;
      }

      if (isGeneratedChrome(element)) {
        foundSectionStructure = true;
        continue;
      }

      const markedSectionId = element.getAttribute(SECTION_ID_ATTR);
      if (markedSectionId) {
        foundSectionStructure = true;
        if (markedSectionId !== currentId) {
          // If we've already finished writing this section, treat the
          // attribute as stale (e.g., a pasted block dragged its
          // origin id along). Keep `currentId` so the block lands
          // physically next to its neighbour rather than jumping back
          // to a closed-out section.
          if (closedIds.has(markedSectionId) && !anchorOpened.has(markedSectionId)) {
            // intentional: ignore the stale id, keep current section
          } else {
            flush();
            currentId = markedSectionId;
          }
        }
      } else if (currentId == null && firstSectionId) {
        currentId = firstSectionId;
      }

      buffer.push(cleanNodeHtml(element));
      continue;
    }

    if (node.nodeType === Node.TEXT_NODE) {
      if (currentId == null && firstSectionId) currentId = firstSectionId;
      buffer.push(escapeHtml(node.textContent ?? ""));
    }
  }

  flush();

  for (const id of Object.keys(result)) {
    result[id] = sanitizeSavedSectionHtml(result[id]);
  }

  if (!foundSectionStructure && firstSectionId && sourceHtml.trim()) {
    for (const id of sectionIds.slice(1)) result[id] = "";
  }

  return result;
}

export function signatureImageHtml(draft: LetterDraft, extraAttrs = ""): string {
  const url = draft.employer?.signatureDataUrl;
  if (!isSafeImageRef(url)) return "";
  return `<div class="signature-image"${extraAttrs}><img src="${escapeAttr(url)}" alt="" /></div>`;
}

export function sanitizePagedLetterHtml(dirty: string): string {
  if (typeof window === "undefined") return dirty;
  const cleaned = DOMPurify.sanitize(dirty, {
    ALLOWED_TAGS: [
      "p",
      "br",
      "strong",
      "b",
      "em",
      "i",
      "u",
      "s",
      "strike",
      "sub",
      "sup",
      "h1",
      "h2",
      "h3",
      "h4",
      "h5",
      "h6",
      "ul",
      "ol",
      "li",
      "blockquote",
      "pre",
      "code",
      "a",
      "table",
      "thead",
      "tbody",
      "tr",
      "th",
      "td",
      "hr",
      "span",
      "div",
      "img",
      "figure",
      "figcaption",
      "ins",
      "del",
      "template",
    ],
    ALLOWED_ATTR: [
      "href",
      "target",
      "rel",
      "colspan",
      "rowspan",
      "src",
      "alt",
      "title",
      "width",
      "height",
      "class",
      "style",
      "data-att-id",
      "data-text-align",
      CHECKED_ATTR,
      ALIGN_ATTR,
      COMMENT_ATTR,
      "data-toc-index",
      "data-toc-level",
      "data-xref-index",
      "data-xref-id",
      "data-xref-target",
      "data-fn",
      "data-fn-text",
      "data-fn-note",
      SECTION_ID_ATTR,
      SECTION_ANCHOR_ATTR,
      SECTION_ANCHOR_ID_ATTR,
      GENERATED_CHROME_ATTR,
      "contenteditable",
    ],
    ADD_ATTR: [
      "target",
      CHECKED_ATTR,
      ALIGN_ATTR,
      COMMENT_ATTR,
      "data-toc-index",
      "data-toc-level",
      "data-xref-index",
      "data-xref-id",
      "data-xref-target",
      "data-fn",
      "data-fn-text",
      "data-fn-note",
      SECTION_ID_ATTR,
      SECTION_ANCHOR_ATTR,
      SECTION_ANCHOR_ID_ATTR,
      GENERATED_CHROME_ATTR,
      "contenteditable",
    ],
    ADD_URI_SAFE_ATTR: [
      "target",
      "contenteditable",
      "data-att-id",
      "data-text-align",
      CHECKED_ATTR,
      ALIGN_ATTR,
      COMMENT_ATTR,
      "data-toc-index",
      "data-toc-level",
      "data-xref-index",
      "data-xref-id",
      "data-xref-target",
      "data-fn",
      "data-fn-text",
      "data-fn-note",
      SECTION_ID_ATTR,
      SECTION_ANCHOR_ATTR,
      SECTION_ANCHOR_ID_ATTR,
      GENERATED_CHROME_ATTR,
    ],
    ALLOW_DATA_ATTR: false,
    KEEP_CONTENT: true,
    ALLOWED_URI_REGEXP:
      /^(?:https?:|mailto:|tel:|#|\/(?!\/)|data:image\/(?:png|jpeg|jpg|gif|webp);base64,)/i,
  });
  return normalizeSanitizedLetterHtml(cleaned);
}

function sectionHtmlWithMarkers(section: LetterSection): string {
  const sanitized = sanitizePagedLetterHtml(section.html || "");
  const doc = parseHtml(`<div>${sanitized}</div>`);
  const root = doc?.body.firstElementChild as HTMLElement | null;
  if (!root) return sanitized;

  wrapLooseTopLevelContent(root);
  for (const element of Array.from(root.children) as HTMLElement[]) {
    element.setAttribute(SECTION_ID_ATTR, section.id);
  }
  return root.innerHTML;
}

function sanitizeSavedSectionHtml(dirty: string): string {
  return stripLetterEditorArtifacts(sanitizePagedLetterHtml(dirty));
}

function stripLetterEditorArtifacts(html: string): string {
  const doc = parseHtml(`<div>${html}</div>`);
  const root = doc?.body.firstElementChild as HTMLElement | null;
  if (!root) return html;

  for (const chrome of Array.from(root.querySelectorAll<HTMLElement>(`[${GENERATED_CHROME_ATTR}]`))) {
    chrome.remove();
  }
  for (const anchor of Array.from(root.querySelectorAll<HTMLElement>(`[${SECTION_ANCHOR_ATTR}]`))) {
    anchor.remove();
  }

  for (const element of [root, ...Array.from(root.querySelectorAll<HTMLElement>("*"))]) {
    stripDisallowedDataAttributes(element, SAVED_DATA_ATTRS);
    element.removeAttribute("role");
    element.removeAttribute("aria-multiline");
  }

  return root.innerHTML;
}

function cleanNodeHtml(node: Node): string {
  const clone = node.cloneNode(true);
  if (clone.nodeType === Node.ELEMENT_NODE) {
    const element = clone as HTMLElement;
    stripPagedArtifacts(element);
    for (const chrome of Array.from(element.querySelectorAll<HTMLElement>(`[${GENERATED_CHROME_ATTR}]`))) {
      chrome.remove();
    }
    for (const anchor of Array.from(element.querySelectorAll<HTMLElement>(`[${SECTION_ANCHOR_ATTR}]`))) {
      anchor.remove();
    }
    for (const item of [element, ...Array.from(element.querySelectorAll<HTMLElement>("*"))]) {
      stripDisallowedDataAttributes(item, SAVED_DATA_ATTRS);
      item.removeAttribute("role");
      item.removeAttribute("aria-multiline");
    }
    return element.outerHTML;
  }
  return escapeHtml(clone.textContent ?? "");
}

function normalizeSanitizedLetterHtml(html: string): string {
  const doc = parseHtml(`<div>${html}</div>`);
  const root = doc?.body.firstElementChild as HTMLElement | null;
  if (!root) return html;

  for (const element of Array.from(root.querySelectorAll<HTMLElement>("*"))) {
    stripDisallowedDataAttributes(element, EDITOR_DATA_ATTRS);
    normalizeAnchorAttributes(element);
    normalizeStyleAttribute(element);
  }

  return root.innerHTML;
}

function stripDisallowedDataAttributes(element: HTMLElement, allowed: Set<string>): void {
  for (const attr of Array.from(element.attributes)) {
    if (attr.name.startsWith("data-") && !allowed.has(attr.name)) {
      element.removeAttribute(attr.name);
    }
  }
}

function normalizeAnchorAttributes(element: HTMLElement): void {
  if (element.tagName !== "A") return;

  const target = element.getAttribute("target");
  if (!target) return;

  const normalized = target.toLowerCase();
  if (!["_blank", "_self", "_parent", "_top"].includes(normalized)) {
    element.removeAttribute("target");
    return;
  }

  element.setAttribute("target", normalized);
  if (normalized === "_blank") {
    element.setAttribute("rel", "noopener noreferrer");
  }
}

function normalizeStyleAttribute(element: HTMLElement): void {
  const style = element.getAttribute("style");
  if (!style) return;

  if (element.hasAttribute(SECTION_ANCHOR_ATTR)) {
    element.setAttribute("style", "display:none");
    return;
  }

  // Accumulate the safe subset of inline style. Block tags may carry
  // text-align AND margin-left (indent); images carry width; ANY element may
  // carry visual character formatting (color / font-size / highlight / font),
  // so imported (DOCX) or pasted rich text keeps its look on save.
  const decls: string[] = [];
  const isBlock = /^(P|DIV|H1|H2|H3|H4|H5|H6|LI|TD|TH|BLOCKQUOTE|PRE)$/.test(element.tagName);
  if (isBlock) {
    const textAlign = safeTextAlignFromStyle(style);
    if (textAlign) decls.push(`text-align: ${textAlign}`);
    const marginLeft = safeMarginHFromStyle(style, "margin-left");
    if (marginLeft) decls.push(`margin-left: ${marginLeft}`);
    const marginRight = safeMarginHFromStyle(style, "margin-right");
    if (marginRight) decls.push(`margin-right: ${marginRight}`);
    // First-line / hanging indent (imported DOCX w:ind firstLine/hanging) —
    // may be negative (hanging), clamped to ±288pt (4in).
    const textIndent = safeTextIndentFromStyle(style);
    if (textIndent) decls.push(`text-indent: ${textIndent}`);
    const lineHeight = safeLineHeightFromStyle(style);
    if (lineHeight) decls.push(`line-height: ${lineHeight}`);
    // Vertical paragraph spacing (e.g. imported DOCX w:spacing before/after) so
    // the page count survives a save instead of reverting to the editor default.
    const marginTop = safeMarginVFromStyle(style, "margin-top");
    if (marginTop) decls.push(`margin-top: ${marginTop}`);
    const marginBottom = safeMarginVFromStyle(style, "margin-bottom");
    if (marginBottom) decls.push(`margin-bottom: ${marginBottom}`);
  }
  const color = safeColorFromStyle(style, "color");
  if (color) decls.push(`color: ${color}`);
  const bg = safeColorFromStyle(style, "background-color");
  if (bg) decls.push(`background-color: ${bg}`);
  const fontSize = safeFontSizeFromStyle(style);
  if (fontSize) decls.push(`font-size: ${fontSize}`);
  const fontFamily = safeFontFamilyFromStyle(style);
  if (fontFamily) decls.push(`font-family: ${fontFamily}`);
  if (element.tagName === "IMG") {
    const imageWidth = safeImageWidthFromStyle(style);
    const maxWidth = safeMaxWidthFromStyle(style);
    if (imageWidth) decls.push(`width: ${imageWidth}`);
    // Preserve the responsive cap. Inserted images carry max-width:100%; dropping
    // it (the old code only matched `width:`) let an unresized large image
    // overflow and get clipped by the page's overflow:hidden after reload.
    if (maxWidth) decls.push(`max-width: ${maxWidth}`);
    if (imageWidth || maxWidth) decls.push("height: auto");
  }

  if (decls.length) element.setAttribute("style", `${decls.join("; ")};`);
  else element.removeAttribute("style");
}

function safeTextAlignFromStyle(style: string): "left" | "center" | "right" | "justify" | "" {
  const match = /(?:^|;)\s*text-align\s*:\s*(left|center|right|justify)\b/i.exec(style);
  return (match?.[1]?.toLowerCase() as "left" | "center" | "right" | "justify" | undefined) ?? "";
}

function safeLineHeightFromStyle(style: string): string {
  // Unitless multiplier (0.5–4) only — rejects px/junk to keep pagination sane.
  const match = /(?:^|;)\s*line-height\s*:\s*(\d+(?:\.\d+)?)\s*(?:;|$)/i.exec(style);
  if (!match) return "";
  const value = Number(match[1]);
  if (!Number.isFinite(value) || value < 0.5 || value > 4) return "";
  return `${value}`;
}

// Horizontal margin (indent) in em / px / pt. pt is what the DOCX importer
// emits (w:ind twips → pt), so it must survive the letter save round-trip.
function safeMarginHFromStyle(style: string, prop: "margin-left" | "margin-right"): string {
  const re = new RegExp(`(?:^|;)\\s*${prop}\\s*:\\s*(\\d+(?:\\.\\d+)?)(em|px|pt)\\b`, "i");
  const match = re.exec(style);
  if (!match) return "";
  const value = Number(match[1]);
  const unit = match[2].toLowerCase();
  if (!Number.isFinite(value) || value <= 0) return "";
  if (unit === "em") return `${Math.min(value, 30)}em`;
  if (unit === "pt") return `${Math.round(Math.min(value, 288) * 100) / 100}pt`; // 4in cap
  return `${Math.round(Math.min(value, 480))}px`;
}

// First-line / hanging indent. May be NEGATIVE (hanging indent from DOCX
// w:ind hanging). Clamped to ±288pt / ±384px / ±30em (≈4in).
function safeTextIndentFromStyle(style: string): string {
  const match = /(?:^|;)\s*text-indent\s*:\s*(-?\d+(?:\.\d+)?)(pt|px|em)\b/i.exec(style);
  if (!match) return "";
  const value = Number(match[1]);
  const unit = match[2].toLowerCase();
  if (!Number.isFinite(value) || value === 0) return "";
  const max = unit === "pt" ? 288 : unit === "px" ? 384 : 30;
  const clamped = Math.max(-max, Math.min(max, value));
  return `${Math.round(clamped * 100) / 100}${unit}`;
}

function safeImageWidthFromStyle(style: string): string {
  // `(?:^|;)` matches `width:` but NOT `max-width:`. The unit uses a lookahead
  // `(?=[\s;]|$)` rather than `\b` — a `\b` after `%` never matches (`%` then `;`
  // are both non-word chars), so a percentage width was silently dropped on save.
  const match = /(?:^|;)\s*width\s*:\s*(\d+(?:\.\d+)?)(px|%)(?=[\s;]|$)/i.exec(style);
  if (!match) return "";
  const value = Number(match[1]);
  const unit = match[2].toLowerCase();
  if (!Number.isFinite(value) || value <= 0) return "";
  if (unit === "%") return `${Math.min(value, 100)}%`;
  return `${Math.round(Math.min(value, 2000))}px`;
}

// A safe CSS color value: #hex (3/6), rgb()/rgba(), or a CSS named color.
// Rejects url()/expression()/var() and anything with parens-not-rgb.
function safeColorFromStyle(style: string, prop: "color" | "background-color"): string {
  // Don't let `color:` match inside `background-color:` (or vice-versa).
  const re = new RegExp(`(?:^|;)\\s*${prop}\\s*:\\s*([^;]+)`, "i");
  const m = re.exec(style);
  if (!m) return "";
  const v = m[1].trim();
  if (/^#[0-9a-f]{3}$|^#[0-9a-f]{6}$/i.test(v)) return v;
  if (/^rgb\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*\)$/i.test(v)) return v;
  if (/^rgba\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*(?:0|1|0?\.\d+)\s*\)$/i.test(v)) return v;
  if (/^[a-z]{3,20}$/i.test(v) && v.toLowerCase() !== "transparent") return v.toLowerCase();
  return "";
}

function safeFontSizeFromStyle(style: string): string {
  const m = /(?:^|;)\s*font-size\s*:\s*(\d+(?:\.\d+)?)(pt|px|em|rem|%)(?=[\s;]|$)/i.exec(style);
  if (!m) return "";
  const value = Number(m[1]);
  const unit = m[2].toLowerCase();
  if (!Number.isFinite(value) || value <= 0) return "";
  // Clamp to a sane document range so an imported absurd size can't break pagination.
  const max = unit === "pt" ? 200 : unit === "px" ? 260 : unit === "%" ? 600 : 16;
  return `${Math.min(value, max)}${unit}`;
}

function safeFontFamilyFromStyle(style: string): string {
  const m = /(?:^|;)\s*font-family\s*:\s*([^;]+)/i.exec(style);
  if (!m) return "";
  // Allow a comma list of quoted/plain font names; reject anything with parens.
  const v = m[1].trim().replace(/\s+/g, " ");
  if (/[()<>{}\\]/.test(v)) return "";
  if (!/^[\w '",\- ]+$/.test(v)) return "";
  return v.slice(0, 120);
}

function safeMarginVFromStyle(style: string, prop: "margin-top" | "margin-bottom"): string {
  const re = new RegExp(`(?:^|;)\\s*${prop}\\s*:\\s*(\\d+(?:\\.\\d+)?)(pt|px|em|rem)(?=[\\s;]|$)`, "i");
  const m = re.exec(style);
  if (!m) return "";
  const value = Number(m[1]);
  const unit = m[2].toLowerCase();
  if (!Number.isFinite(value) || value < 0) return "";
  const max = unit === "pt" ? 96 : unit === "px" ? 128 : 8; // ~1.3in cap
  return `${Math.min(value, max)}${unit}`;
}

function safeMaxWidthFromStyle(style: string): string {
  const match = /(?:^|;)\s*max-width\s*:\s*(\d+(?:\.\d+)?)(px|%)(?=[\s;]|$)/i.exec(style);
  if (!match) return "";
  const value = Number(match[1]);
  const unit = match[2].toLowerCase();
  if (!Number.isFinite(value) || value <= 0) return "";
  if (unit === "%") return `${Math.min(value, 100)}%`;
  return `${Math.round(Math.min(value, 2000))}px`;
}

export function letterheadHtml(draft: LetterDraft): string {
  const url = draft.employer?.letterheadDataUrl;
  if (!isSafeImageRef(url)) return "";
  return `<div class="letterhead"><img src="${escapeAttr(url)}" alt="" /></div>`;
}

export function buildAttachmentsBlock(draft: LetterDraft): string {
  const attached = (draft.evidence ?? []).filter((item) => displayModeOf(item) === "attached");
  if (attached.length === 0) return "";
  const items = attached
    .map((item, index) => {
      const label = item.filename || `${item.kind || "Evidence"} item`;
      const content = item.content ? ` - ${escapeHtml(item.content)}` : "";
      return `<li><strong>${escapeHtml(label)}</strong>${content}<span class="att-num">[Attachment ${index + 1}]</span></li>`;
    })
    .join("\n");
  return `<section class="attachments-section page-break-before">
    <h2>Attachments</h2>
    <ol class="attachments-list">${items}</ol>
  </section>`;
}

function displayModeOf(item: { displayMode?: string }): string {
  return item.displayMode ?? "attached";
}

function anchorHtmlFor(id: string): string {
  // <template> is structurally invisible: it isn't laid out, doesn't render,
  // and paged.js skips it. Earlier we used <span style="display:none"> which
  // paged.js still tried to lay out and that's what caused blank/duplicated
  // first pages. (HRLETTER fix, paged-edit/Editor.tsx:1626.)
  return `<template ${SECTION_ANCHOR_ATTR} ${SECTION_ANCHOR_ID_ATTR}="${escapeAttr(id)}"></template>`;
}

function sectionIdsFrom(sections: LetterSection[] | string[]): string[] {
  return sections.map((section) => (typeof section === "string" ? section : section.id));
}

function isGeneratedChrome(element: HTMLElement): boolean {
  return element.hasAttribute(GENERATED_CHROME_ATTR);
}

function parseHtml(html: string): Document | null {
  if (typeof DOMParser === "undefined") return null;
  return new DOMParser().parseFromString(html, "text/html");
}

function isSafeImageRef(value: unknown): value is string {
  if (typeof value !== "string") return false;
  if (/^data:image\/(?:png|jpeg|jpg|gif|webp);base64,[a-z0-9+/=\s]+$/i.test(value)) {
    return true;
  }
  if (!/^https:\/\//i.test(value)) return false;
  try {
    new URL(value);
    return true;
  } catch {
    return false;
  }
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function escapeAttr(value: string): string {
  return escapeHtml(value);
}
